#!/usr/bin/env python3
"""Smart Irrigation System for Raspberry Pi.

Controls a solenoid valve via gpiozero and reads soil moisture from an
MCP3008 ADC (SPI bus 0, CE0) using spidev.  A lightweight TCP web server
on port 8080 accepts JSON commands to query status or toggle the valve.
"""

import argparse
import json
import logging
import signal
import socket
import sys
import time

import spidev
from gpiozero import DigitalOutputDevice

# ---------------------------------------------------------------------------
# Globals (initialised in main, cleaned up on exit)
# ---------------------------------------------------------------------------
valve: DigitalOutputDevice | None = None
spi: spidev.SpiDev | None = None
running = True
manual_override = False
manual_override_state = False


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description="Smart Irrigation System")
    p.add_argument("--moisture_threshold", type=int, default=30,
                   help="Moisture threshold (0-100) to activate valve")
    p.add_argument("--web_port", type=int, default=8080,
                   help="Web server port")
    p.add_argument("--log_file", type=str, default="irrigation.log",
                   help="Log file path")
    p.add_argument("--valve_pin", type=int, default=17,
                   help="BCM GPIO pin for solenoid valve")
    p.add_argument("--spi_channel", type=int, default=0,
                   help="MCP3008 single-ended channel (0-7)")
    return p.parse_args()


def setup_logging(log_file: str) -> None:
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def init_spi(channel: int) -> spidev.SpiDev:
    s = spidev.SpiDev()
    s.open(0, 0)          # bus 0, device 0 (CE0)
    s.max_speed_hz = 1_000_000
    s.mode = 0
    return s


def init_valve(pin: int) -> DigitalOutputDevice:
    return DigitalOutputDevice(pin, active_high=True, initial_value=False)


def read_moisture(spi: spidev.SpiDev, channel: int) -> int | None:
    """Read a 10-bit value from the MCP3008 single-ended channel.

    Returns None on SPI error or when the sensor appears absent
    (all-zeros or all-ones on the 10-bit result).
    """
    try:
        r = spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
    except OSError as exc:
        logging.error("SPI transfer failed: %s", exc)
        return None

    value = ((r[1] & 0x03) << 8) | r[2]
    if value == 0 or value == 1023:
        logging.warning("Sensor absent or saturated (raw=%d)", value)
        return None
    return value


def moisture_to_percent(value: int) -> int:
    return int(round((value / 1023.0) * 100.0))


def control_valve(valve: DigitalOutputDevice, moisture: int,
                   threshold: int, override: bool,
                   override_state: bool) -> bool:
    """Return the new manual_override_state after applying logic.

    If override is active, the valve is driven to override_state and
    automatic logic is skipped.  Otherwise the valve is opened/closed
    based on the hysteresis band [threshold, threshold + 10].
    """
    if override:
        if override_state:
            valve.on()
        else:
            valve.off()
        return True

    if moisture < threshold:
        valve.on()
        logging.info("Valve ON  (moisture %d%% < threshold %d%%)",
                     moisture, threshold)
    elif moisture > threshold + 10:
        valve.off()
        logging.info("Valve OFF (moisture %d%% > threshold %d%% + hysteresis)",
                     moisture, threshold)
    return False


def handle_command(cmd: dict, threshold: int) -> dict:
    """Process a JSON command dict and return a response dict."""
    global manual_override, manual_override_state

    if not isinstance(cmd, dict):
        return {"error": "Invalid JSON object"}

    action = cmd.get("action", "").lower()

    if action == "get_status":
        return {
            "moisture": "N/A" if moisture is None else moisture,
            "valve": "ON" if valve and valve.is_active else "OFF",
            "threshold": threshold,
            "override": manual_override,
            "override_state": manual_override_state,
        }

    if action == "toggle_valve":
        manual_override = True
        manual_override_state = not manual_override_state
        if valve:
            if manual_override_state:
                valve.on()
            else:
                valve.off()
        return {
            "message": "Valve toggled",
            "new_state": "ON" if manual_override_state else "OFF",
        }

    return {"error": f"Unknown action: {action}"}


def run_web_server(port: int, threshold: int) -> None:
    global running
    server_socket = None
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(("0.0.0.0", port))
        server_socket.listen(1)
        server_socket.settimeout(1.0)
        logging.info("Web server listening on port %d", port)

        while running:
            try:
                client_sock, addr = server_socket.accept()
            except socket.timeout:
                continue
            except OSError:
                break

            with client_sock:
                logging.info("Connection from %s", addr)
                try:
                    data = client_sock.recv(1024)
                    if not data:
                        continue
                    cmd = json.loads(data.decode("utf-8"))
                    resp = handle_command(cmd, threshold)
                    client_sock.sendall(
                        (json.dumps(resp) + "\n").encode("utf-8")
                    )
                except json.JSONDecodeError:
                    logging.error("Invalid JSON from %s", addr)
                except OSError as exc:
                    logging.error("Socket error from %s: %s", addr, exc)
    finally:
        if server_socket:
            server_socket.close()


def cleanup() -> None:
    global valve, spi
    logging.info("Cleaning up resources...")
    if valve is not None:
        try:
            valve.off()
            valve.close()
        except Exception:
            pass
    if spi is not None:
        try:
            spi.close()
        except Exception:
            pass
    logging.info("Cleanup complete.")


def signal_handler(signum, frame) -> None:
    global running
    logging.info("Signal %d received, shutting down...", signum)
    running = False


def main() -> None:
    global valve, spi, running, manual_override, manual_override_state

    args = parse_args()
    setup_logging(args.log_file)
    logging.info("Starting Smart Irrigation System")

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        valve = init_valve(args.valve_pin)
        spi = init_spi(args.spi_channel)
    except Exception as exc:
        logging.error("Initialization failed: %s", exc)
        cleanup()
        sys.exit(1)

    moisture: int | None = None
    try:
        while running:
            raw = read_moisture(spi, args.spi_channel)
            if raw is not None:
                moisture = moisture_to_percent(raw)
                logging.info("Moisture: %d%%", moisture)
            else:
                logging.warning("Moisture read failed; keeping previous value")

            if moisture is not None:
                manual_override = control_valve(
                    valve, moisture, args.moisture_threshold,
                    manual_override, manual_override_state
                )
            else:
                logging.warning("No moisture reading; skipping valve control")

            # Start web server in a daemon thread so it doesn't block
            import threading
            threading.Thread(target=run_web_server,
                             args=(args.web_port, args.moisture_threshold),
                             daemon=True).start()

            time.sleep(5)
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

