import spidev
import time
import datetime
import socket
import json
import signal
import sys
import threading
from gpiozero import Buzzer

# Constants
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1000000
ADC_CHANNELS = {0: "MQ-4", 1: "MQ-7", 2: "MQ-135"}
GAS_LIMITS = {"MQ-4": 50.0, "MQ-7": 25.0, "MQ-135": 100.0}
BUZZER_PIN = 17
SERVER_IP = "127.0.0.1"
SERVER_PORT = 12345
CALIBRATION_READINGS = 10
CALIBRATION_DELAY = 3
DATA_LOGGING_INTERVAL = 60
BUZZER_DURATION = 1

# Global state
spi = None
buzzer = None
running = True
baseline_resistance = {}
spi_lock = threading.Lock()

def signal_handler(sig, frame):
    global running
    running = False

def read_adc(channel):
    try:
        with spi_lock:
            response = spi.xfer2([1, (8 + channel) << 4, 0])
        adc_out = ((response[1] & 3) << 8) + response[2]
        return adc_out
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return None

def calculate_resistance(adc_value):
    if adc_value is None or adc_value == 0:
        return None
    try:
        return 10000 * ((1023.0 / adc_value) - 1)
    except Exception as e:
        print(f"Error calculating resistance: {e}")
        return None

def calculate_gas_concentration(sensor_type, resistance):
    if resistance is None or resistance == 0:
        return None
    try:
        if sensor_type == "MQ-4":
            return 10 ** ((resistance / baseline_resistance["MQ-4"]) - 2)
        elif sensor_type == "MQ-7":
            return 10 ** ((resistance / baseline_resistance["MQ-7"]) - 2.5)
        elif sensor_type == "MQ-135":
            return 10 ** ((resistance / baseline_resistance["MQ-135"]) - 3)
        else:
            return None
    except Exception as e:
        print(f"Error calculating gas concentration for {sensor_type}: {e}")
        return None

def log_data(timestamp, mq4_ppm, mq7_ppm, mq135_ppm):
    filename = f"gas_data_{datetime.date.today().strftime('%Y-%m-%d')}.csv"
    try:
        with open(filename, "a") as f:
            f.write(f"{timestamp},{mq4_ppm},{mq7_ppm},{mq135_ppm}\n")
    except Exception as e:
        print(f"Error logging data: {e}")

def transmit_data(data):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(5)
            s.connect((SERVER_IP, SERVER_PORT))
            s.sendall(json.dumps(data).encode())
    except Exception as e:
        print(f"Error transmitting data: {e}")

def calibrate_sensors():
    global baseline_resistance
    print("Calibrating sensors...")
    for channel, sensor_type in ADC_CHANNELS.items():
        total_resistance = 0
        valid_readings = 0
        for _ in range(CALIBRATION_READINGS):
            adc_value = read_adc(channel)
            if adc_value is not None:
                resistance = calculate_resistance(adc_value)
                if resistance is not None:
                    total_resistance += resistance
                    valid_readings += 1
            time.sleep(CALIBRATION_DELAY)
        if valid_readings > 0:
            baseline_resistance[sensor_type] = total_resistance / valid_readings
            print(f"Calibrated {sensor_type} (Channel {channel}): R0 = {baseline_resistance[sensor_type]:.2f} ohms")
        else:
            print(f"Failed to calibrate {sensor_type} (Channel {channel}).")
    print("Calibration complete.")

def main():
    global spi, buzzer
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
    except Exception as e:
        print(f"Failed to initialize SPI: {e}")
        sys.exit(1)

    try:
        buzzer = Buzzer(BUZZER_PIN)
    except Exception as e:
        print(f"Failed to initialize buzzer on GPIO {BUZZER_PIN}: {e}")
        sys.exit(1)

    calibrate_sensors()

    while running:
        timestamp = datetime.datetime.now().isoformat()
        gas_data = {}

        for channel, sensor_type in ADC_CHANNELS.items():
            adc_value = read_adc(channel)
            if adc_value is not None:
                resistance = calculate_resistance(adc_value)
                if resistance is not None:
                    ppm = calculate_gas_concentration(sensor_type, resistance)
                    if ppm is not None:
                        gas_data[sensor_type] = ppm
                        print(f"{timestamp} - {sensor_type}: {ppm:.2f} ppm")
                        if sensor_type in GAS_LIMITS and ppm > GAS_LIMITS[sensor_type]:
                            print(f"ALERT: {sensor_type} level ({ppm:.2f} ppm) exceeds limit ({GAS_LIMITS[sensor_type]} ppm)!")
                            buzzer.on()
                            time.sleep(BUZZER_DURATION)
                            buzzer.off()
            else:
                print(f"{timestamp} - {sensor_type}: ADC read failed.")

        if len(gas_data) == len(ADC_CHANNELS):
            log_data(timestamp, gas_data.get("MQ-4"), gas_data.get("MQ-7"), gas_data.get("MQ-135"))
            transmit_data({"timestamp": timestamp, "data": gas_data})

        time.sleep(DATA_LOGGING_INTERVAL)

    print("Cleaning up resources...")
    if spi:
        spi.close()
    if buzzer:
        buzzer.close()
    print("Program terminated.")

if __name__ == "__main__":
    main()

