import board
import busio
import adafruit_max30102

LOG_FILE = 'heart_rate_log.txt'
SAMPLE_WINDOW = 4.0
SAMPLE_INTERVAL = 1.0
I2C_ADDR = 0x57

running = True
i2c = None
sensor = None


def handle_sigint(signum, frame):
    global running
    running = False


def cleanup():
    global i2c, sensor
    if sensor is not None:
        try:
            sensor.disable_leds()
        except Exception:
