    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass


def init_sensor():
    global i2c, sensor
    i2c = busio.I2C(board.SCL, board.SDA)
    try:
        sensor = adafruit_max30102.MAX30102(i2c, address=I2C_ADDR)
    except ValueError:
        print(f"Error: MAX30102 not found at I2C address 0x{I2C_ADDR:02X}.")
        cleanup()
        sys.exit(1)
    except OSError as e:
        print(f"Error: I2C bus error while initializing MAX30102: {e}")
        cleanup()
        sys.exit(1)
    try:
        sensor.setup_sensor()
    except Exception as e:
        print(f"Error: Failed to configure MAX30102: {e}")
        cleanup()
        sys.exit(1)
