        sensor.set_pulse_amplitude_red(0x1F)
        sensor.set_pulse_amplitude_ir(0x1F)
    except Exception:
        pass
    try:
        sensor.set_sample_rate(100)
    except Exception:
        pass
    try:
        sensor.set_led_mode(adafruit_max30102.MODE_SPO2)
    except Exception:
        pass
    time.sleep(0.1)


def read_fifo():
    try:
        data = sensor.get_fifo_data()
        if data is None or len(data) < 2:
            return None, None
        return int(data[0]), int(data[1])
    except Exception as e:
        print(f"Warning: FIFO read error: {e}")
        return None, None


def estimate_bpm(ir_samples, window):
    if len(ir_samples) < 2:
        return 0
    threshold = (max(ir_samples) + min(ir_samples)) / 2.0
    crossings = 0
    prev = ir_samples[0]
    rising = prev < threshold
    for v in ir_samples[1:]:
        if v > threshold and not rising:
            crossings += 1
            rising = True
        elif v < threshold and rising:
            rising = False
    if crossings == 0:
        return 0
    duration = window
    return int((crossings / duration) * 60.0)


def log_and_print(timestamp, hr, spo2):
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(f"{timestamp}, {hr}, {spo2}\n")
    except OSError as e:
        print(f"Warning: Failed to write log: {e}")
    print(f"{timestamp}, Heart Rate: {hr} BPM, SpO2: {spo2}%")


def main():
    global running
    signal.signal(signal.SIGINT, handle_sigint)
    init_sensor()
    ir_window = []
    last_log = 0.0
    print("MAX30102 heart-rate monitor started. Press Ctrl-C to stop.")
    while running:
        ts = time.strftime('%Y-%m-%dT%H:%M:%S')
        ir, red = read_fifo()
        if ir is None or red is None:
            time.sleep(SAMPLE_INTERVAL)
            continue
        ir_window.append(ir)
        elapsed = time.monotonic() - last_log
        if elapsed >= SAMPLE_WINDOW:
            hr = estimate_bpm(ir_window, SAMPLE_WINDOW)
            spo2 = int((red / (ir + 1)) * 100)
            log_and_print(ts, hr, spo2)
            last_log = time.monotonic()
            ir_window.clear()
        time.sleep(SAMPLE_INTERVAL)
    cleanup()
    print("Stopped.")


if __name__ == '__main__':
    main()

