import json
import threading
import queue
import signal
import sys
import logging
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput
import RPi.GPIO as GPIO
from gpiozero import LED

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class Camera:
    def __init__(self, config_file):
        self.config_file = config_file
        self.config = self._load_config()
        self.camera = None
        self.output = None
        self.encoder = None
        self._running = False
        self._led = None
        self._led_timer = None

        self._init_camera()
        self._init_gpio()

    def _load_config(self):
        try:
            with open(self.config_file, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            logging.error(f"Config file not found: {self.config_file}")
            raise
        except json.JSONDecodeError as e:
            logging.error(f"Invalid JSON in config file: {e}")
            raise

    def _init_camera(self):
        try:
            width = self.config['camera']['resolution_width']
            height = self.config['camera']['resolution_height']
            framerate = self.config['camera']['framerate']
            self.output = queue.Queue(maxsize=self.config['camera']['queue_size'])

            self.camera = Picamera2()
            video_config = self.camera.create_video_configuration(
                main={"size": (width, height), "format": "RGB888"},
                controls={"FrameRate": framerate}
            )
            self.camera.configure(video_config)
            self.encoder = MJPEGEncoder()
            self.camera.start()
            time.sleep(2)
            self._running = True
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            raise

    def _init_gpio(self):
        gpio_pin = self.config.get('gpio_pin')
        if gpio_pin is not None:
            try:
                self._led = LED(gpio_pin)
                logging.info(f"GPIO pin {gpio_pin} initialized for LED.")
            except Exception as e:
                logging.error(f"Error initializing GPIO pin {gpio_pin}: {e}")
                raise

    def capture_frames(self):
        while self._running:
            try:
                frame = self.camera.capture_array()
                if frame is None:
                    logging.warning("Captured frame is None.")
                    continue

                stream = io.BytesIO()
                self.encoder.encode(stream, [frame])
                stream.seek(0)

                try:
                    self.output.put(stream, timeout=1)
                except queue.Full:
                    logging.warning("Output queue is full. Dropping frame.")

                time.sleep(0.1)
            except Exception as e:
                logging.error(f"Error capturing frame: {e}")
                break

    def start_capture(self):
        self.capture_thread = threading.Thread(target=self.capture_frames, daemon=True)
        self.capture_thread.start()

    def trigger_alert(self):
        if self._led is None:
            logging.warning("No LED configured. Alert skipped.")
            return

        duration = self.config.get('alert_duration', 1)
        if self._led_timer and self._led_timer.is_alive():
            self._led_timer.cancel()

        self._led.on()
        self._led_timer = threading.Timer(duration, self._led.off)
        self._led_timer.start()
        logging.info(f"Alert triggered on GPIO pin for {duration} seconds.")

    def cleanup(self):
        self._running = False
        if self.capture_thread and self.capture_thread.is_alive():
            self.capture_thread.join(timeout=2)

        if self._led_timer and self._led_timer.is_alive():
            self._led_timer.cancel()

        if self._led is not None:
            self._led.close()

        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass

        GPIO.cleanup()
        logging.info("Resources cleaned up.")

def main():
    config_file = 'config.json'
    camera = None

    def signal_handler(sig, frame):
        logging.info("SIGINT received. Exiting...")
        if camera:
            camera.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)

    try:
        camera = Camera(config_file)
        camera.start_capture()

        while True:
            time.sleep(1)
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if camera:
            camera.cleanup()

if __name__ == "__main__":
    main()

