import atexit
import signal
import sys
import threading
import time
import traceback
from typing import Tuple, Optional

from flask import Flask, render_template, Response, request

from config import Config
from mail_config import send_email
from camera import Camera
from object_detection import ObjectDetection

app = Flask(__name__)
config = Config()
object_detection = ObjectDetection()
camera: Optional[Camera] = None
shutdown_event = threading.Event()


def initialize_camera() -> Optional[Camera]:
    """Initialize the picamera2-based Camera wrapper; return None on failure."""
    try:
        cam = Camera(flip=False)
        cam.start()
        return cam
    except Exception as e:
        print(f"Error initializing camera: {e}")
        traceback.print_exc()
        return None


def check_for_objects() -> None:
    """Background thread: periodically detect objects and send email notifications."""
    last_email_time = 0.0
    while not shutdown_event.is_set():
        try:
            if config.send_email_notifications and (
                time.time() - last_email_time
            ) >= int(config.email_send_interval):
                if config.classifier_name == 'motion_detector':
                    frame, detected = object_detection.get_object_with_basic_motion_detection(
                        camera
                    )
                else:
                    frame, detected = object_detection.get_object(
                        camera, config.classifier_name
                    )

                if detected:
                    try:
                        send_email(frame, config)
                        last_email_time = time.time()
                    except Exception as e:
                        print(f"Error sending email: {e}")
                        traceback.print_exc()

            shutdown_event.wait(1.0)
        except Exception as e:
            print(f"Error in object detection loop: {e}")
            traceback.print_exc()
            shutdown_event.wait(5.0)


@app.route('/', methods=['GET', 'POST'])
def index() -> str:
    if request.method == 'POST':
        config.live_preview = 'live_preview' in request.form
        config.send_email_notifications = 'send_email_notifications' in request.form
        config.classifier_name = request.form.get('classifier', config.classifier_name)
        config.receiver_email_address = request.form.get(
            'receiver_email_address', config.receiver_email_address
        )
        config.email_send_interval = int(
            request.form.get('email_send_interval', config.email_send_interval)
        )
    return render_template(
        'index.html',
        classifiers=config.classifierNameLocationDict,
        config=config,
    )


def generate() -> bytes:
    """Generate JPEG frames for multipart/x-mixed-replace streaming."""
    while not shutdown_event.is_set():
        try:
            if config.classifier_name == 'motion_detector':
                frame, _ = object_detection.get_object_with_basic_motion_detection(
                    camera
                )
            else:
                frame, _ = object_detection.get_object(
                    camera, config.classifier_name
                )

            if frame is None:
                shutdown_event.wait(0.1)
                continue

            yield (
                b'--frame\r\n'
                b'Content-Type: image/jpeg\r\n\r\n' + frame + b'\r\n\r\n'
            )
        except Exception as e:
            print(f"Error generating frame: {e}")
            traceback.print_exc()
            shutdown_event.wait(0.5)


@app.route('/video_feed')
def video_feed() -> Response:
    return Response(
        generate(),
        mimetype='multipart/x-mixed-replace; boundary=frame',
    )


def cleanup(signum=None, frame=None) -> None:
    """Release camera and other resources on exit."""
    shutdown_event.set()
    if camera is not None:
        try:
            camera.stop()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


if __name__ == '__main__':
    camera = initialize_camera()
    if camera is None:
        print("Camera initialization failed. Exiting.")
        sys.exit(1)

    atexit.register(cleanup)
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    object_detection_thread = threading.Thread(target=check_for_objects, daemon=True)
    object_detection_thread.start()

    try:
        app.run(host='0.0.0.0', debug=False, threaded=True)
    finally:
        cleanup()

