import numpy as np
import serial
import serial.tools.list_ports
import signal
import sys

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

cap = None
ser = None
tracking = False
min_HSV = np.array([0, 0, 0])
max_HSV = np.array([255, 255, 255])
center_x = 0
center_y = 0
half_extent = 50

try:
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        raise IOError("Cannot open webcam")
    ret, frame = cap.read()
    if not ret or frame is None:
        raise IOError("Cannot read frame from webcam")
    h_frame, w_frame, _ = frame.shape
    center_x = w_frame // 2
    center_y = h_frame // 2
except Exception as e:
    print(f"Camera initialization error: {e}")
    sys.exit(1)

try:
    available_ports = [p.device for p in serial.tools.list_ports.comports()]
except Exception as e:
    print(f"Warning: cannot enumerate serial ports: {e}")
    available_ports = []

if '/dev/ttyACM0' in available_ports:
    port_name = '/dev/ttyACM0'
elif available_ports:
    port_name = available_ports[0]
    print(f"Warning: /dev/ttyACM0 not found; using {port_name}")
else:
    port_name = None
    print("Warning: no serial ports available; continuing in serial-disabled mode")

if port_name is not None:
