import json
import logging
import os
import signal
import statistics
import sys
import time
from datetime import datetime

try:
    from gpiozero import Device, DigitalOutputDevice, DigitalInputDevice
    from gpiozero.pins.native import NativeFactory
except ImportError:
    print("gpiozero is required. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(0)

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensors": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

running = True


def signal_handler(signum, frame):
    global running
    running = False


def load_config(path):
    if not os.path.exists(path):
        logging.warning("Config file '%s' not found; creating default.", path)
        try:
            with open(path, "w") as f:
                json.dump(DEFAULT_CONFIG, f, indent=2)
        except OSError as e:
            logging.error("Could not write default config: %s", e)
        return dict(DEFAULT_CONFIG)
    try:
        with open(path, "r") as f:
            cfg = json.load(f)
        merged = dict(DEFAULT_CONFIG)
        merged.update(cfg)
        merged.setdefault("sensors", DEFAULT_CONFIG["sensors"])
        return merged
    except (json.JSONDecodeError, OSError) as e:
        logging.error("Error loading config '%s': %s; using defaults.", path, e)
        return dict(DEFAULT_CONFIG)


def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )
    logging.info("Water level monitoring system started.")


def measure_distance(trigger, echo, offset, max_distance):
    try:
        trigger.off()
        time.sleep(0.0001)
        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        deadline = time.time() + 0.05
        while echo.value == 0:
            if time.time() > deadline:
                logging.warning("Echo pin stuck LOW (timeout).")
                return None

        pulse_start = time.time()

        deadline = time.time() + 0.05
        while echo.value == 1:
            if time.time() > deadline:
                logging.warning("Echo pin stuck HIGH (timeout).")
                return None

        pulse_duration = time.time() - pulse_start
        distance = (pulse_duration * 34300) / 2
        distance += offset
        if distance < 0 or distance > max_distance:
            logging.warning("Distance %.2f out of range [0, %.2f].", distance, max_distance)
            return None
        return distance
    except Exception as e:
        logging.error("Error measuring distance: %s", e)
        return None


def get_water_level(sensor_config):
    try:
        trigger = DigitalOutputDevice(sensor_config["trigger_pin"])
        echo = DigitalInputDevice(sensor_config["echo_pin"])
    except Exception as e:
        logging.error("Failed to init GPIO pins %d/%d: %s", sensor_config["trigger_pin"], sensor_config["echo_pin"], e)
        return None

    readings = []
    for _ in range(3):
        d = measure_distance(trigger, echo, sensor_config["offset"], sensor_config["max_distance"])
        if d is not None:
            readings.append(d)
        time.sleep(0.05)

    trigger.close()
    echo.close()

    if not readings:
        return None
    water_level = sensor_config["max_distance"] - statistics.median(readings)
    return water_level


def check_alerts(average_level, low, high, last_alert_time, alert_repeat_delay):
    now = time.time()
    if average_level < low and (last_alert_time is None or (now - last_alert_time) > alert_repeat_delay):
        logging.warning("Water level LOW: %.2f", average_level)
        return "low", now
    if average_level > high and (last_alert_time is None or (now - last_alert_time) > alert_repeat_delay):
        logging.warning("Water level HIGH: %.2f", average_level)
        return "high", now
    return None, last_alert_time


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    setup_logging(config["log_file"])

    sensors = config["sensors"]
    low_threshold = config["alert_threshold_low"]
    high_threshold = config["alert_threshold_high"]
    repeat_delay = config["alert_repeat_delay"]

    sensor_errors = {i: 0 for i in range(len(sensors))}
    last_alert = None
    last_alert_time = None

    while running:
        valid_levels = []
        for i, sensor in enumerate(sensors):
            if sensor_errors[i] >= 5:
                logging.warning("Sensor %d excluded after 5 consecutive errors.", i)
                continue
            level = get_water_level(sensor)
            if level is not None:
                valid_levels.append(level)
                sensor_errors[i] = 0
            else:
                sensor_errors[i] += 1
                logging.warning("Sensor %d reading failed (error streak %d).", i, sensor_errors[i])

        if not valid_levels:
            logging.error("No valid sensor readings this cycle.")
        else:
            avg = statistics.mean(valid_levels)
            logging.info("Average water level: %.2f", avg)
            alert, last_alert_time = check_alerts(avg, low_threshold, high_threshold, last_alert_time, repeat_delay)
            if alert:
                last_alert = alert

        for _ in range(5):
            if not running:
                break
            time.sleep(1)

    logging.info("Water level monitoring system stopped.")
    sys.exit(0)


if __name__ == "__main__":
    main()

