import os
import time
import signal
import random
import sys
import logging
import speech_recognition as sr

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
LIGHT_PIN = 17
DHT_PIN = 4
CAMERA_RESOLUTION = (640, 480)
WAKE_WORD = "Greenhouse"
SIMULATED_TEMPERATURE_MIN = 15
SIMULATED_TEMPERATURE_MAX = 35

# Global state
running = True
simulated_gpio = False
simulated_temperature = random.uniform(SIMULATED_TEMPERATURE_MIN, SIMULATED_TEMPERATURE_MAX)

# Attempt to import and initialize hardware libraries
try:
    import RPi.GPIO as GPIO
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
    logging.info("GPIO initialized successfully.")
except Exception as e:
    logging.warning(f"Failed to initialize GPIO: {e}. Falling back to simulation mode.")
    simulated_gpio = True

try:
    import adafruit_dht
    dht_device = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    logging.info("DHT11 sensor initialized successfully.")
except Exception as e:
    logging.warning(f"Failed to initialize DHT11 sensor: {e}. Falling back to simulated temperature.")
    dht_device = None

try:
    from picamera2 import Picamera2
    camera = Picamera2()
    camera.configure(camera.create_still_configuration(main={"size": CAMERA_RESOLUTION}))
    camera.start()
    logging.info("Camera initialized successfully.")
except Exception as e:
    logging.warning(f"Failed to initialize camera: {e}. Picture-taking will be simulated.")
    camera = None

def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    global running
    running = False
    logging.info("Cleaning up resources...")
    if not simulated_gpio:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            GPIO.cleanup()
        except Exception:
            pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    if camera:
        try:
            camera.stop()
            camera.close()
        except Exception:
            pass
    logging.info("Cleanup complete. Exiting.")
    sys.exit(0)

# Register signal handlers
signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

def turn_lights_on():
    """Turns the lights on."""
    if simulated_gpio:
        logging.info("Simulating: Turning lights ON.")
    else:
        try:
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            logging.info("Lights turned ON.")
        except Exception as e:
            logging.error(f"Failed to turn lights on: {e}")

def turn_lights_off():
    """Turns the lights off."""
    if simulated_gpio:
        logging.info("Simulating: Turning lights OFF.")
    else:
        try:
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            logging.info("Lights turned OFF.")
        except Exception as e:
            logging.error(f"Failed to turn lights off: {e}")

def read_temperature():
    """Reads the temperature from the DHT11 sensor or simulates it."""
    global simulated_temperature
    if dht_device:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                logging.info(f"Temperature: {temperature:.1f}°C")
                return temperature
            else:
                logging.warning("DHT11 returned None. Falling back to simulated temperature.")
        except RuntimeError as e:
            logging.warning(f"DHT11 read error (likely checksum or timing): {e}. Falling back to simulated temperature.")
        except Exception as e:
            logging.error(f"Unexpected DHT11 error: {e}. Falling back to simulated temperature.")
    # Fallback to simulated temperature
    simulated_temperature = random.uniform(SIMULATED_TEMPERATURE_MIN, SIMULATED_TEMPERATURE_MAX)
    logging.info(f"Simulated Temperature: {simulated_temperature:.1f}°C")
    return simulated_temperature

def take_picture():
    """Captures an image using the camera or simulates it."""
    if camera:
        try:
            timestamp = time.strftime("%Y%m%d-%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            camera.capture_file(filename)
            logging.info(f"Picture saved as {filename}")
        except Exception as e:
            logging.error(f"Failed to capture picture: {e}. Simulating picture.")
            timestamp = time.strftime("%Y%m%d-%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            with open(filename, 'w') as f:
                f.write("Simulated picture data")
            logging.info(f"Simulated picture saved as {filename}")
    else:
        logging.info("Camera not available. Simulating picture.")
        timestamp = time.strftime("%Y%m%d-%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        with open(filename, 'w') as f:
            f.write("Simulated picture data")
        logging.info(f"Simulated picture saved as {filename}")

def listen_for_commands():
    """Listens for voice commands and executes the corresponding actions."""
    recognizer = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            logging.info("Say 'Greenhouse' followed by a command...")
            audio = recognizer.listen(source, timeout=5)
    except sr.WaitTimeoutError:
        logging.warning("Listening timed out.")
        return
    except Exception as e:
        logging.error(f"Microphone error: {e}")
        return

    try:
        words = recognizer.recognize_google(audio).lower()
        logging.info(f"Recognized: {words}")
    except sr.UnknownValueError:
        logging.warning("Could not understand audio.")
        return
    except sr.RequestError as e:
        logging.error(f"Speech recognition service error: {e}")
        return

    if WAKE_WORD in words:
        logging.info("Wake word detected.")
        if "turn on the lights" in words:
            turn_lights_on()
        elif "turn off the lights" in words:
            turn_lights_off()
        elif "what is the temperature" in words:
            read_temperature()
        elif "take a picture" in words:
            take_picture()
        else:
            logging.warning("Unknown command.")

def main():
    """Main function to run the greenhouse control system."""
    logging.info("Greenhouse control system started.")
    try:
        while running:
            listen_for_commands()
            time.sleep(0.1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()

