    global running
    camera = None
    try:
        camera = Picamera2()
        config = camera.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"},
            controls={"FrameRate": 15}
        )
        camera.configure(config)
        camera.start()
        time.sleep(2)

        baseline_avg = None
        try:
            baseline_avg = camera.capture_array()
            if baseline_avg is None:
                raise RuntimeError("Failed to capture baseline image")
            baseline_avg = float(np.mean(baseline_avg))
        except Exception as e:
            print(f"Error capturing baseline image: {e}")
            return

        while running:
            try:
                current_frame = camera.capture_array()
                if current_frame is None:
                    print("Warning: Captured empty frame, skipping...")
                    time.sleep(2)
                    continue

                current_avg = float(np.mean(current_frame))
                diff = abs(current_avg - baseline_avg)

                if diff > 10:
                    print(f"Motion detected! Difference: {diff:.2f}")
                    try:
                        import cv2
                        cv2.imwrite("motion.jpg", current_frame)
                        print("Motion image saved as motion.jpg")
                    except Exception as e:
                        print(f"Error saving image: {e}")
                    baseline_avg = current_avg

                time.sleep(2)
            except Exception as e:
                print(f"Error during capture loop: {e}")
                time.sleep(2)

    except Exception as e:
        print(f"Camera initialization or runtime error: {e}")
    finally:
        if camera is not None:
            try:
                camera.stop()
            except Exception:
                pass
        print("Camera stopped. Exiting.")

if __name__ == "__main__":
    main()

