import RPi.GPIO as GPIO
import time
import datetime
import argparse
import csv
import os
import sys
import signal

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def parse_arguments():
    parser = argparse.ArgumentParser(description="Vibration Monitoring System for Raspberry Pi")
    parser.add_argument("-g", "--gpio", nargs=3, type=int, required=True, help="Three BCM GPIO pin numbers for vibration sensors")
    parser.add_argument("-l", "--log_file", type=str, required=True, help="Path to the CSV log file")
    parser.add_argument("-i", "--interval", type=float, required=True, help="Sampling interval in seconds")
    parser.add_argument("-c", "--calibrate", type=int, required=True, help="Calibration duration in seconds")
    parser.add_argument("-p", "--picture_interval", type=int, help="Time between image captures in seconds")
    return parser.parse_args()

def setup_gpio(pins):
    GPIO.setmode(GPIO.BCM)
    for pin in pins:
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        except Exception as e:
            print(f"Error setting up GPIO pin {pin}: {e}", file=sys.stderr)
            GPIO.cleanup()
            sys.exit(1)

def read_sensors(pins):
    return [GPIO.input(pin) for pin in pins]

def calibrate_sensors(pins, interval, duration):
    print("Calibrating sensors...")
    start_time = time.time()
    high_counts = [0] * len(pins)
    total_samples = 0
    while time.time() - start_time < duration and _running:
        readings = read_sensors(pins)
        high_counts = [hc + (1 if r else 0) for hc, r in zip(high_counts, readings)]
        total_samples += 1
        time.sleep(interval)
    if total_samples == 0:
        print("Calibration failed: no samples collected.", file=sys.stderr)
        return [0.0] * len(pins)
    baselines = [(hc / total_samples) * 100.0 for hc in high_counts]
    thresholds = [b + 20.0 for b in baselines]
    print(f"Calibration complete. Baselines: {baselines}, Thresholds: {thresholds}")
    return thresholds

def log_data(log_file, timestamp, sensor_states):
    try:
        with open(log_file, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp] + sensor_states)
            csvfile.flush()
    except Exception as e:
        print(f"Error writing to log file: {e}. Logging to console.", file=sys.stderr)
        print(f"Timestamp: {timestamp}, Sensor1: {sensor_states[0]}, Sensor2: {sensor_states[1]}, Sensor3: {sensor_states[2]}")

def capture_image(picam2, interval):
    if Picamera2 is None:
        print("picamera2 not available; skipping image capture.", file=sys.stderr)
        return
    try:
        if (time.time() - capture_image.last_time) >= interval:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
            filename = os.path.join("images", f"{timestamp}.jpg")
            os.makedirs("images", exist_ok=True)
            picam2.capture_file(filename)
            print(f"Image captured: {filename}")
            capture_image.last_time = time.time()
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
capture_image.last_time = 0.0

def main():
    global _running
    args = parse_arguments()
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    setup_gpio(args.gpio)
    thresholds = calibrate_sensors(args.gpio, args.interval, args.calibrate)
    if not thresholds:
        GPIO.cleanup()
        sys.exit(1)

    picam2 = None
    if args.picture_interval is not None and Picamera2 is not None:
        try:
            picam2 = Picamera2()
            picam2.configure(picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
            picam2.start()
            print("Camera initialized successfully.")
        except Exception as e:
            print(f"Error initializing camera: {e}. Continuing without camera.", file=sys.stderr)
            picam2 = None

    try:
        while _running:
            timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")
            sensor_states = []
            for pin in args.gpio:
                reading = GPIO.input(pin)
                sensor_states.append(1 if reading else 0)
            log_data(args.log_file, timestamp, sensor_states)
            if picam2 is not None:
                capture_image(picam2, args.picture_interval)
            time.sleep(args.interval)
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
            except Exception:
                pass
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

