import signal
import sys
import time

try:
    from gpiozero import Button, OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

running = True
btn_pins = []
out_pins = []
state_24 = False


def handle_signal(signum, frame):
    global running
    running = False


def cleanup():
    global btn_pins, out_pins
    for btn in btn_pins:
        try:
            btn.close()
        except Exception:
            pass
    for out in out_pins:
        try:
            out.close()
        except Exception:
            pass
    btn_pins.clear()
    out_pins.clear()


def main():
    global btn_pins, out_pins, state_24

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        for pin in INPUT_PINS:
            btn = Button(pin, pull_up=True, bounce_time=None)
            btn_pins.append(btn)

        for pin in OUTPUT_PINS:
            out = OutputDevice(pin, initial_value=False)
            out_pins.append(out)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"GPIO initialization error: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)
    except PermissionError as e:
        print(f"Permission denied during GPIO setup: {e}", file=sys.stderr)
        print("Hint: run with sudo or add the user to the 'gpio' group.", file=sys.stderr)
        cleanup()
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO setup: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    last_6_state = None

    try:
        while running:
            val4 = btn_pins[0].is_active
            val5 = btn_pins[1].is_active
            val6 = btn_pins[2].is_active

            if not val4:
                out_pins[0].on()
            elif not val5:
                out_pins[0].off()

            if not val6:
                if last_6_state is None or last_6_state:
                    state_24 = not state_24
                    out_pins[1].value = state_24
                last_6_state = False
            else:
                last_6_state = True

            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

