"""
Motion-activated security camera using picamera2.
Captures 5-second H.264 clips when motion is detected.
"""

import argparse
import datetime
import os
import signal
import sys
import time
from pathlib import Path

import cv2
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    print("\nShutdown signal received. Cleaning up...")
    running = False

def parse_arguments():
    parser = argparse.ArgumentParser(description="Motion-activated security camera using picamera2.")
    parser.add_argument("--threshold", type=int, default=5, help="Motion detection threshold (brightness difference).")
    parser.add_argument("--duration", type=int, default=5, help="Recording duration in seconds.")
    parser.add_argument("--max_size", type=str, default="1GB", help="Maximum storage size (e.g., 1GB, 500MB).")
    return parser.parse_args()

def initialize_camera():
    """Initialize picamera2 with 320x240 @ 15 fps. Returns Picamera2 instance or None on failure."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": (320, 240), "format": "RGB888"},
            controls={"FrameRate": 15}
        )
        picam2.configure(config)
        picam2.start()
        # Allow auto-exposure to settle
        time.sleep(2)
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}", file=sys.stderr)
        return None

def create_directory(path):
    """Create directory if it doesn't exist. Returns True on success."""
    try:
        Path(path).mkdir(parents=True, exist_ok=True)
        return True
    except PermissionError:
        print(f"Permission denied creating directory {path}", file=sys.stderr)
        return False
    except OSError as e:
        print(f"OS error creating directory {path}: {e}", file=sys.stderr)
        return False

def calculate_average_brightness(frame):
    """Return mean brightness of a frame (numpy array)."""
    if frame is None:
        return 0.0
    # Convert to grayscale
    gray = cv2.cvtColor(frame, cv2.COLOR_RGB2GRAY)
    return float(np.mean(gray))

def detect_motion(picam2, threshold):
    """Capture two frames and return True if brightness difference exceeds threshold."""
    try:
        frame1 = picam2.capture_array()
        time.sleep(0.1)  # Small delay between frames
        frame2 = picam2.capture_array()
        if frame1 is None or frame2 is None:
            return False
        avg1 = calculate_average_brightness(frame1)
        avg2 = calculate_average_brightness(frame2)
        return abs(avg1 - avg2) > threshold
    except Exception as e:
        print(f"Error during motion detection: {e}", file=sys.stderr)
        return False

def record_video(picam2, output_path, duration):
    """Record H.264 video for given duration. Returns True on success."""
    try:
        encoder = H264Encoder(bitrate=1000000)
        output = FileOutput(output_path)
        picam2.start_recording(encoder, output)
        time.sleep(duration)
        picam2.stop_recording()
        return True
    except Exception as e:
        print(f"Error recording video: {e}", file=sys.stderr)
        # Attempt to stop recording if it failed mid-way
        try:
            picam2.stop_recording()
        except Exception:
            pass
        return False

def manage_storage(directory, max_size_bytes):
    """Delete oldest files if total size exceeds max_size_bytes."""
    try:
        files = []
        total_size = 0
        for f in os.listdir(directory):
            fp = os.path.join(directory, f)
            if os.path.isfile(fp):
                size = os.path.getsize(fp)
                mtime = os.path.getmtime(fp)
                files.append((fp, mtime, size))
                total_size += size

        if total_size <= max_size_bytes:
            return

        # Sort by modification time (oldest first)
        files.sort(key=lambda x: x[1])

        for fp, mtime, size in files:
            if total_size <= max_size_bytes:
                break
            try:
                os.remove(fp)
                total_size -= size
                print(f"Deleted old file: {fp}")
            except OSError as e:
                print(f"Error deleting {fp}: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Error managing storage: {e}", file=sys.stderr)

def main():
    global running
    args = parse_arguments()

    # Parse max_size
    max_size_bytes = 1 * 1024 * 1024 * 1024  # 1 GB default
    if args.max_size.upper().endswith("GB"):
        try:
            max_size_bytes = int(args.max_size[:-2]) * 1024 * 1024 * 1024
        except ValueError:
            print("Invalid max_size format. Use e.g., 1GB, 500MB.", file=sys.stderr)
            sys.exit(1)
    elif args.max_size.upper().endswith("MB"):
        try:
            max_size_bytes = int(args.max_size[:-2]) * 1024 * 1024
        except ValueError:
            print("Invalid max_size format.", file=sys.stderr)
            sys.exit(1)

    # Initialize camera
    picam2 = initialize_camera()
    if picam2 is None:
        sys.exit(1)

    # Create directory
    footage_dir = "/home/pi/security_footage"
    if not create_directory(footage_dir):
        picam2.stop()
        sys.exit(1)

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    print("Security camera started. Press Ctrl+C to stop.")

    try:
        while running:
            if detect_motion(picam2, args.threshold):
                timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
                filename = os.path.join(footage_dir, f"{timestamp}.h264")
                print(f"Motion detected! Recording to {filename}")
                if record_video(picam2, filename, args.duration):
                    print("Recording complete.")
                else:
                    print("Recording failed.", file=sys.stderr)

                # Manage storage after recording
                manage_storage(footage_dir, max_size_bytes)

            time.sleep(2)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        print("Cleaning up...")
        try:
            picam2.stop()
        except Exception:
            pass
        print("Camera stopped. Exiting.")

if __name__ == "__main__":
    main()

