import cv2
import os
import time
import signal
import sys
import numpy as np
from picamera2 import Picamera2

# Constants
IMAGE_DIR = "images"
MAX_PICTURES = 5
CAMERA_INDEX = 0
HAAR_CASCADE_PATH = cv2.data.haarcascades + 'haarcascade_frontalface_default.xml'

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def setup_camera(camera_index=CAMERA_INDEX):
    """Initialize the Picamera2 at the given index, retrying up to 3 times."""
    for attempt in range(1, 4):
        try:
            picam2 = Picamera2(camera_num=camera_index)
            config = picam2.create_preview_configuration(
                main={"size": (640, 480), "format": "BGR888"}
            )
            picam2.configure(config)
            picam2.start()
            print(f"Camera initialized successfully on attempt {attempt}.")
            return picam2
        except Exception as e:
            print(f"Camera initialization attempt {attempt}/3 failed: {e}")
            if attempt < 3:
                time.sleep(1)
    return None

def detect_faces(image, face_cascade):
    """Detect faces in the image using Haar cascade."""
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray, 1.3, 5)

def save_face_image(image, name, count):
    """Save a cropped face image to the images directory."""
    try:
        filename = os.path.join(IMAGE_DIR, f"{name}_{count}.jpg")
        success = cv2.imwrite(filename, image)
        if success:
            print(f"Saved: {filename}")
        else:
            print(f"Failed to write image: {filename}")
    except Exception as e:
        print(f"Error saving image: {e}")

def main():
    global running

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Create image directory if it doesn't exist
    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
    except OSError as e:
        print(f"Error creating directory '{IMAGE_DIR}': {e}")
        sys.exit(1)

    # Get user's name
    try:
        name = input("What is your name? ").strip()
        if not name:
            print("Name cannot be empty.")
            sys.exit(1)
    except EOFError:
        print("No input received.")
        sys.exit(1)

    # Load Haar cascade
    face_cascade = cv2.CascadeClassifier(HAAR_CASCADE_PATH)
    if face_cascade.empty():
        print(f"Error: Could not load Haar cascade from {HAAR_CASCADE_PATH}")
        sys.exit(1)

    # Initialize camera
    picam2 = setup_camera()
    if picam2 is None:
        print("Failed to initialize camera after 3 attempts. Exiting.")
        sys.exit(1)

    picture_count = 0
    try:
        while running and picture_count < MAX_PICTURES:
            # Capture frame
            try:
                frame = picam2.capture_array()
            except Exception as e:
                print(f"Error capturing frame: {e}")
                time.sleep(0.1)
                continue

            if frame is None or frame.size == 0:
                print("Empty frame received.")
                continue

            # Detect faces
            faces = detect_faces(frame, face_cascade)

            # Draw bounding boxes
            for (x, y, w, h) in faces:
                cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

            # Display the frame
            cv2.imshow("Face Capture", frame)

            # Wait for key press
            key = cv2.waitKey(1) & 0xFF

            if key == ord('y'):
                for (x, y, w, h) in faces:
                    face_img = frame[y:y + h, x:x + w]
                    save_face_image(face_img, name, picture_count)
                    picture_count += 1
                    if picture_count >= MAX_PICTURES:
                        break
            elif key == ord('q'):
                break

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        # Clean up resources
        try:
            picam2.stop()
        except Exception:
            pass
        cv2.destroyAllWindows()
        print("Program finished.")

if __name__ == "__main__":
    main()

