import sys
import time
import signal
import threading
import subprocess
import json
import zmq

try:
    from gps3 import gps3
except ImportError:
    print("Error: gps3 library not found. Install with: pip install gps3", file=sys.stderr)
    sys.exit(1)

try:
    from picamera2 import Picamera2
    from picamera2.encoders import MJPEGEncoder
    from picamera2.outputs import Output
except ImportError:
    print("Error: picamera2 library not found. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

DEFAULT_GPS_LAT = "22.483425"
DEFAULT_GPS_LON = "88.455463"
IMAGE_WIDTH = 640
IMAGE_HEIGHT = 480
IMAGE_FRAMERATE = 100
ZMQ_LINGER_TIME_MS = 0
GPS_POLL_INTERVAL = 0.5
GPS_RESTART_RETRIES = 1
ZMQ_ENDPOINT = 'tcp://192.168.1.4:5555'

shutdown_event = threading.Event()
gps_lock = threading.Lock()
current_latitude = DEFAULT_GPS_LAT
current_longitude = DEFAULT_GPS_LON


def restart_gpsd():
    """Attempt to restart gpsd via systemctl; return True on success."""
    try:
        result = subprocess.run(
            ['sudo', 'systemctl', 'restart', 'gpsd'],
            capture_output=True, text=True, timeout=10
        )
        if result.returncode == 0:
            print("gpsd restarted successfully.")
            return True
        else:
            print(f"Failed to restart gpsd: {result.stderr.strip()}", file=sys.stderr)
            return False
    except FileNotFoundError:
        print("'systemctl' not found; cannot restart gpsd.", file=sys.stderr)
        return False
    except subprocess.TimeoutExpired:
        print("Timeout restarting gpsd.", file=sys.stderr)
        return False
    except Exception as e:
        print(f"Unexpected error restarting gpsd: {e}", file=sys.stderr)
        return False


def get_gps_data():
    """Poll gpsd for TPV data; update shared GPS variables on success."""
    global current_latitude, current_longitude

    gps_socket = None
    try:
        gps_socket = gps3.GPSDSocket()
        data_stream = gps3.DataStream()

        try:
            gps_socket.connect()
            gps_socket.watch()
        except Exception as e:
            print(f"Error connecting to gpsd: {e}", file=sys.stderr)
            return

        for raw_data in gps_socket:
            if shutdown_event.is_set():
                break

            if not raw_data:
                continue

            data_stream.unpack(raw_data)
            tpv = data_stream.TPV

            lat = tpv.get('lat')
            lon = tpv.get('lon')

            if isinstance(lat, (int, float)) and isinstance(lon, (int, float)):
                with gps_lock:
                    current_latitude = str(lat)
                    current_longitude = str(lon)
                print(f"GPS: Latitude={current_latitude}, Longitude={current_longitude}")
            else:
                print("GPS: Non-numeric or missing fix, ignoring.", file=sys.stderr)

            time.sleep(GPS_POLL_INTERVAL)

    except Exception as e:
        print(f"Error in GPS polling thread: {e}", file=sys.stderr)
    finally:
        if gps_socket is not None:
            try:
                gps_socket.close()
            except Exception:
                pass


