import io
import logging
import numpy as np
import cv2
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Accumulates picamera2 MJPEG bytes and flushes complete P-frames."""

    def __init__(self, camera: Picamera2):
        if not isinstance(camera, Picamera2):
            raise TypeError("camera must be a picamera2.Picamera2 instance")
        self.c = camera
        self.b = io.BytesIO()
        self._prev_frame_type = None

    def _is_keyframe(self, metadata) -> bool:
        """Return True if the current frame is an I-frame (frame_type == 1)."""
        if not metadata or 'encode' not in metadata:
            return False
        return metadata['encode'].get('frame_type', 0) == 1

    def write(self, d: bytes) -> int:
        """Accumulate bytes d; flush complete P-frames to the output sink."""
        try:
            self.b.write(d)
            metadata = self.c.capture_metadata()
            frame_type = metadata['encode']['frame_type'] if metadata and 'encode' in metadata else 0

            if frame_type != 1 and self._prev_frame_type == 1:
                # Transition from I-frame to P-frame: previous buffer is a complete P-frame
                self._flush()
            self._prev_frame_type = frame_type
            return len(d)
        except (OSError, IOError) as e:
            logger.error("I/O error in CameraStreamBuffer.write: %s", e)
            return 0

    def _flush(self):
        """Write accumulated buffer to the output sink and reset."""
        try:
            data = self.b.getvalue()
            if data:
                # In a real application, forward data to a consumer here
                logger.debug("Flushing %d bytes of P-frame", len(data))
            self.b.seek(0)
            self.b.truncate()
        except (OSError, IOError) as e:
            logger.error("I/O error in CameraStreamBuffer._flush: %s", e)


class MotionDetectionBuffer:
    """Parse MJPEG stream and invoke a callback on consecutive BGR frames."""

    def __init__(self, callback):
        if not callable(callback):
            raise TypeError("callback must be callable")
        self.f = callback
        self.b = io.BytesIO()
        self._prev_frame = None

    def _decode(self, data: bytes):
        """Decode JPEG bytes into a BGR NumPy array."""
        try:
            arr = np.frombuffer(data, dtype=np.uint8)
            frame = cv2.imdecode(arr, cv2.IMREAD_COLOR)
            if frame is None:
                raise ValueError("cv2.imdecode returned None")
            return frame
        except (ValueError, cv2.error) as e:
            logger.error("JPEG decode failed: %s", e)
            return None

    def write(self, d: bytes) -> int:
        """Parse MJPEG stream; detect SOI marker to delimit frames."""
        try:
            if d.startswith(b'\xff\xd8'):
                # New frame begins; decode the previously accumulated frame
                if self.b.tell() > 0:
                    self.b.seek(0)
                    prev_data = self.b.read()
                    prev_frame = self._decode(prev_data)
                    if prev_frame is not None:
                        if self._prev_frame is not None:
                            self.f(self._prev_frame, prev_frame)
                        self._prev_frame = prev_frame
                self.b.seek(0)
                self.b.truncate()
            self.b.write(d)
            return len(d)
        except (OSError, IOError) as e:
            logger.error("I/O error in MotionDetectionBuffer.write: %s", e)
            return 0

