import signal
import sys
import time
import board
import busio
import adafruit_ssd1306
import adafruit_bme280
import adafruit_tsl2561

# --- Configuration -----------------------------------------------------------
OLED_WIDTH = 128
OLED_HEIGHT = 64
OLED_ADDR = 0x3C
BME280_ADDR = 0x76
TSL2561_ADDR = 0x39
UPDATE_INTERVAL_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
_i2c_bus = None
_oled = None
_running = True


def _cleanup():
    """Release hardware resources on exit."""
    global _oled, _i2c_bus
    if _oled is not None:
        try:
            _oled.fill(0)
            _oled.show()
        except Exception:
            pass
    if _i2c_bus is not None:
        try:
            _i2c_bus.deinit()
        except Exception:
            pass


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _init_i2c():
    """Initialize the I2C bus on GPIO3 (SCL) / GPIO2 (SDA)."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize I2C bus: {exc}", file=sys.stderr)
        return None


def _init_oled(i2c):
    """Initialize the SSD1306 OLED display at 0x3C."""
    try:
        return adafruit_ssd1306.SSD1306_I2C(OLED_WIDTH, OLED_HEIGHT, i2c, addr=OLED_ADDR)
    except Exception as exc:
        print(f"[ERROR] SSD1306 not found at 0x{OLED_ADDR:02X}: {exc}", file=sys.stderr)
        return None


def _init_bme280(i2c):
    """Initialize the BME280 sensor at 0x76."""
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(i2c, address=BME280_ADDR)
    except Exception as exc:
        print(f"[ERROR] BME280 not found at 0x{BME280_ADDR:02X}: {exc}", file=sys.stderr)
        return None


def _init_tsl2561(i2c):
    """Initialize the TSL2561 luminosity sensor at 0x39."""
    try:
        return adafruit_tsl2561.TSL2561(i2c, address=TSL2561_ADDR)
    except Exception as exc:
        print(f"[ERROR] TSL2561 not found at 0x{TSL2561_ADDR:02X}: {exc}", file=sys.stderr)
        return None


def _read_sensor(sensor, label):
    """Read a sensor value, returning None on transient error."""
    try:
        return sensor.value
    except Exception as exc:
        print(f"[WARN] {label} read failed: {exc}", file=sys.stderr)
        return None


def _update_display(oled, temp, hum, pres, light):
    """Write sensor values to the OLED display."""
    oled.fill(0)
    oled.text(f"Temp: {temp:.1f} C", 0, 0, 1)
    oled.text(f"Humidity: {hum:.1f} %", 0, 16, 1)
    oled.text(f"Pressure: {pres:.1f} hPa", 0, 32, 1)
    oled.text(f"Light: {light:.1f} lux", 0, 48, 1)
    oled.show()


def main():
    global _i2c_bus, _oled

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _i2c_bus = _init_i2c()
    if _i2c_bus is None:
        sys.exit(1)

    _oled = _init_oled(_i2c_bus)
    if _oled is None:
        _cleanup()
        sys.exit(1)

    bme = _init_bme280(_i2c_bus)
    tsl = _init_tsl2561(_i2c_bus)
    if bme is None or tsl is None:
        _cleanup()
        sys.exit(1)

    # Force a TSL2561 power-on reset for reliable readings.
    try:
        tsl.enabled = True
        tsl.integration_time = 0.5
    except Exception as exc:
        print(f"[WARN] TSL2561 init tweak failed: {exc}", file=sys.stderr)

    print("Sensors initialized. Press Ctrl+C to exit.")

    while _running:
        temp = _read_sensor(bme, "BME280") if bme else None
        hum = _read_sensor(bme, "BME280") if bme else None
        pres = _read_sensor(bme, "BME280") if bme else None
        light = _read_sensor(tsl, "TSL2561") if tsl else None

        if temp is not None and hum is not None and pres is not None and light is not None:
            _update_display(_oled, temp, hum, pres, light)
        else:
            print("[WARN] Skipping display update due to missing sensor data.")

        time.sleep(UPDATE_INTERVAL_S)

    _cleanup()


if __name__ == "__main__":
    main()

