LCD_ROWS = 2
LCD_I2C_ADDRESS = 0x27
DHT_PIN = board.D4
UPDATE_INTERVAL_S = 2.0

# --- Globals for cleanup -----------------------------------------------------
lcd = None
dht_sensor = None
running = True


def cleanup():
    """Clear the LCD and release resources on exit."""
    global lcd, dht_sensor
    if lcd is not None:
        try:
            lcd.clear()
        except Exception:
            pass
    if dht_sensor is not None:
        try:
            dht_sensor.exit()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global running
    running = False


def init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        return None


def init_lcd(i2c_bus):
    """Initialize the 16x2 LCD at the given I2C address."""
    try:
        return character_lcd.Character_LCD_I2C(i2c_bus, LCD_COLUMNS, LCD_ROWS, LCD_I2C_ADDRESS)
    except Exception as exc:
        print(f"Error initializing LCD at 0x{LCD_I2C_ADDRESS:02X}: {exc}", file=sys.stderr)
        return None


def init_dht22():
    """Initialize the DHT22 sensor on the specified pin."""
    try:
        return adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Error initializing DHT22 on {DHT_PIN}: {exc}", file=sys.stderr)
        return None


def read_sensor(sensor):
    """Attempt to read temperature and humidity from the DHT22.

    Returns (temperature, humidity) or (None, None) if the read fails.
    """
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as exc:
        # DHT22 frequently throws transient checksum / timing errors.
        print(f"Sensor read error (transient): {exc}", file=sys.stderr)
        return None, None
    except Exception as exc:
        print(f"Unexpected sensor error: {exc}", file=sys.stderr)
        return None, None


def display_reading(lcd_display, temperature, humidity):
    """Write the latest reading to the LCD."""
    if lcd_display is None:
        return
    try:
        lcd_display.message = f"Temp: {temperature:.1f} C\nHumidity: {humidity:.1f}%"
    except Exception as exc:
        print(f"Error writing to LCD: {exc}", file=sys.stderr)


def main():
    global lcd, dht_sensor

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = init_i2c()
    if i2c_bus is None:
        sys.exit(1)

    lcd = init_lcd(i2c_bus)
    if lcd is None:
        sys.exit(1)

    dht_sensor = init_dht22()
    if dht_sensor is None:
        print("Warning: DHT22 sensor not available. LCD will display blank readings.", file=sys.stderr)

    try:
        while running:
            temperature, humidity = read_sensor(dht_sensor) if dht_sensor else (None, None)
            display_reading(lcd, temperature, humidity)
            time.sleep(UPDATE_INTERVAL_S)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

