import os
import sys
import time
import signal
import logging
from PIL import Image, ImageOps
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306
from typing import List, Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class GifPlayer:
    def __init__(self, i2c_port: int = 1, i2c_address: int = 0x3C, width: int = 128, height: int = 64):
        self.i2c_port = i2c_port
        self.i2c_address = i2c_address
        self.width = width
        self.height = height
        self.device = None
        self._running = True

    def initialize_display(self) -> bool:
        try:
            serial = i2c(port=self.i2c_port, address=self.i2c_address)
            self.device = ssd1306(serial, width=self.width, height=self.height)
            logger.info("OLED display initialized successfully.")
            return True
        except Exception as e:
            logger.error(f"Error initializing OLED display: {e}")
            return False

    def cleanup(self):
        if self.device:
            try:
                self.device.cleanup()
                logger.info("Display resources released.")
            except Exception as e:
                logger.error(f"Error during display cleanup: {e}")
            finally:
                self.device = None

    def _signal_handler(self, signum, frame):
        logger.info("Interrupt received, stopping...")
        self._running = False

    def load_gifs(self, folder_path: str) -> List[str]:
        if not os.path.isdir(folder_path):
            logger.error(f"Folder not found: {folder_path}")
            return []
        gif_files = [os.path.join(folder_path, f) for f in os.listdir(folder_path) if f.lower().endswith('.gif')]
        if not gif_files:
            logger.warning(f"No GIF files found in folder: {folder_path}")
        return gif_files

    def resize_and_pad(self, image: Image.Image) -> Image.Image:
        try:
            resized = image.resize((self.width, self.height), Image.LANCZOS)
            padded = ImageOps.expand(resized, border=(0, 0, 0, 0), fill=(0, 0, 0))
            return padded
        except Exception as e:
            logger.error(f"Error resizing/padding image: {e}")
            return None

    def display_frame(self, image: Image.Image):
        if not self.device:
            logger.error("Display not initialized.")
            return
        try:
            with canvas(self.device) as draw:
                draw.bitmap((0, 0), image)
        except Exception as e:
            logger.error(f"Error displaying frame: {e}")

    def play_gif(self, gif_path: str, loop_count: int = 0):
        try:
            with Image.open(gif_path) as img:
                n_frames = getattr(img, 'n_frames', 1)
                durations = [img.info.get('duration', 100) for _ in range(n_frames)]
                loop = loop_count if loop_count > 0 else getattr(img, 'loop', 0)
                loop = loop_count if loop_count > 0 else 0

                while self._running:
                    for i in range(n_frames):
                        if not self._running:
                            break
                        img.seek(i)
                        frame = self.resize_and_pad(img)
                        if frame is None:
                            continue
                        self.display_frame(frame)
                        time.sleep(durations[i] / 1000.0)
                    if loop > 0 and self._running:
                        loop -= 1
                    elif loop == 0 and self._running:
                        break
        except FileNotFoundError:
            logger.error(f"GIF file not found: {gif_path}")
        except Exception as e:
            logger.error(f"Error playing GIF {gif_path}: {e}")

    def run(self, folder_path: str, loop_count: int = 0):
        if not self.initialize_display():
            return
        signal.signal(signal.SIGINT, self._signal_handler)
        signal.signal(signal.SIGTERM, self._signal_handler)

        gif_files = self.load_gifs(folder_path)
        if not gif_files:
            self.cleanup()
            return

        for gif_file in gif_files:
            if not self._running:
                break
            logger.info(f"Playing: {gif_file}")
            self.play_gif(gif_file, loop_count)

        self.cleanup()

if __name__ == "__main__":
    player = GifPlayer()
    gifs_folder = sys.argv[1] if len(sys.argv) > 1 else "."
    loop = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    player.run(gifs_folder, loop)

