import math
import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

# Pin assignments (BCM numbering)
LEFT_MOTOR_PWM_PIN = 12
LEFT_MOTOR_DIR_PIN = 13
RIGHT_MOTOR_PWM_PIN = 18
RIGHT_MOTOR_DIR_PIN = 19

# Control parameters
ANGLE_MIN = 175
ANGLE_MAX = 185
DISTANCE_THRESHOLD = 10
EXTENSION = 50
LOOP_DELAY = 0.1
MAX_ITERATIONS = 1000

# Initial positions
ball = (180, -200)
car_front = (180, -15)
car_back = (200, -15)
goal = (0, 200)

# Global motor handles for cleanup
motors = {}


def setup_motors():
    """Initialize PWM motor outputs and ensure they are stopped."""
    global motors
    try:
        motors = {
            'left_pwm': PWMOutputDevice(LEFT_MOTOR_PWM_PIN),
            'left_dir': PWMOutputDevice(LEFT_MOTOR_DIR_PIN),
            'right_pwm': PWMOutputDevice(RIGHT_MOTOR_PWM_PIN),
            'right_dir': PWMOutputDevice(RIGHT_MOTOR_DIR_PIN),
        }
        stop()
    except GPIOZeroError as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        sys.exit(1)


def stop():
    """Stop both motors."""
    for dev in motors.values():
        try:
            dev.value = 0
        except Exception:
            pass


def turn_left():
    """Turn the car left."""
    motors['left_dir'].value = 0.5
    motors['right_dir'].value = 0.5
    motors['left_pwm'].value = 0.3
    motors['right_pwm'].value = 0.3


def turn_right():
    """Turn the car right."""
    motors['left_dir'].value = 0.5
    motors['right_dir'].value = 0.5
    motors['left_pwm'].value = 0.3
    motors['right_pwm'].value = 0.3


def move_forward():
    """Move the car forward."""
    motors['left_dir'].value = 0.5
    motors['right_dir'].value = 0.5
    motors['left_pwm'].value = 0.5
    motors['right_pwm'].value = 0.5


def compute_image_point(ball_x, ball_y, goal_x, goal_y, extension):
    """Compute the image point beyond the ball on the line to the goal."""
    dbg = math.sqrt((goal_x - ball_x) ** 2 + (goal_y - ball_y) ** 2)
    if dbg == 0:
        return ball_x, ball_y
    dgp = dbg + extension
    rx = int(((dgp * ball_x) - (extension * goal_x)) / dbg)
    ry = int(((dgp * ball_y) - (extension * goal_y)) / dbg)
    return rx, ry


def compute_angle(x1, y1, x2, y2):
    """Compute the angle (degrees) of the line from (x1,y1) to (x2,y2) relative to the x-axis."""
    dx = x2 - x1
    dy = y2 - y1
    if dx == 0 and dy == 0:
        return 0.0
    return math.degrees(math.atan2(dy, dx))


def compute_car_heading(front_x, front_y, back_x, back_y):
    """Compute the car's heading angle from front and back positions."""
    return compute_angle(back_x, back_y, front_x, front_y)


def compute_distance(x1, y1, x2, y2):
    """Compute Euclidean distance between two points."""
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)


def angle_difference(angle1, angle2):
    """Compute the smallest absolute difference between two angles."""
    diff = abs(angle1 - angle2) % 360
    return diff if diff <= 180 else 360 - diff


def control_loop():
    """Main control loop."""
    img_x, img_y = compute_image_point(ball[0], ball[1], goal[0], goal[1], EXTENSION)
    car_heading = compute_car_heading(car_front[0], car_front[1], car_back[0], car_back[1])
    goal_angle = compute_angle(car_front[0], car_front[1], goal[0], goal[1])
    img_angle = compute_angle(car_front[0], car_front[1], img_x, img_y)

    print(f"Initial state -> img=({img_x},{img_y}), heading={car_heading:.1f}, goal_angle={goal_angle:.1f}, img_angle={img_angle:.1f}")

    for iteration in range(MAX_ITERATIONS):
        if compute_distance(car_front[0], car_front[1], goal[0], goal[1]) < 5:
            print("Reached goal!")
            break

        # Phase 1: Intercept the ball
        if compute_distance(car_front[0], car_front[1], ball[0], ball[1]) > 5:
            if not (ANGLE_MIN <= angle_difference(car_heading, img_angle) <= ANGLE_MAX):
                if angle_difference(car_heading, img_angle) < 180:
                    turn_right()
                else:
                    turn_left()
            elif compute_distance(car_front[0], car_front[1], img_x, img_y) > DISTANCE_THRESHOLD:
                move_forward()
            else:
                stop()
                print(f"Intercept phase: aligned with image point at iteration {iteration}")
        else:
            print(f"Intercept phase complete at iteration {iteration}")

        # Phase 2: Head towards the goal
        if compute_distance(car_front[0], car_front[1], goal[0], goal[1]) > 5:
            if not (ANGLE_MIN <= angle_difference(car_heading, goal_angle) <= ANGLE_MAX):
                if angle_difference(car_heading, goal_angle) < 180:
                    turn_right()
                else:
                    turn_left()
            elif compute_distance(car_front[0], car_front[1], goal[0], goal[1]) > DISTANCE_THRESHOLD:
                move_forward()
            else:
                stop()
                print(f"Goal phase: aligned with goal at iteration {iteration}")
        else:
            print(f"Goal phase complete at iteration {iteration}")
            break

        time.sleep(LOOP_DELAY)
    else:
        print("Warning: Maximum iterations reached without reaching the goal.")


def cleanup(signum=None, frame=None):
    """Clean up GPIO resources and stop motors."""
    print("\nCleaning up...")
    stop()
    for dev in motors.values():
        try:
            dev.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    setup_motors()
    try:
        control_loop()
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

