import time
import sys
import board
import adafruit_dht

# DHT11 requires at least 1 second between reads; 2 s is a safe margin.
READ_INTERVAL_S = 2.0
MAX_RETRIES = 5
SENSOR_PIN = board.D4  # BCM GPIO4 (physical pin 7)


def read_dht11(sensor):
    """Attempt a single DHT11 read; return (temp, humidity) or None on failure."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            return None
        return temperature, humidity
    except RuntimeError:
        # Common DHT11 transient errors: checksum mismatch, timeout, etc.
        return None
    except Exception:
        # Unexpected error (e.g., sensor disconnected mid-run)
        return None


def main():
    sensor = None
    try:
        sensor = adafruit_dht.DHT11(SENSOR_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Error: Failed to initialize DHT11 on GPIO4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for attempt in range(1, MAX_RETRIES + 1):
            result = read_dht11(sensor)
            if result is not None:
                temperature, humidity = result
                print(f"Temperature: {temperature:.1f} C")
                sys.exit(0)

            if attempt < MAX_RETRIES:
                time.sleep(READ_INTERVAL_S)

        print("Error: Could not read DHT11 after 5 attempts.", file=sys.stderr)
        sys.exit(1)

    except KeyboardInterrupt:
        print("\nInterrupted by user.", file=sys.stderr)
        sys.exit(130)
    finally:
        # Clean up the underlying GPIO resources.
        try:
            sensor.exit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

