import json
import time
import random
import sys
import signal
import paho.mqtt.client as mqtt

BROKER_HOST = "test.mosquitto.org"
BROKER_PORT = 1883
KEEPALIVE = 60
TOPIC = "classroom/temperature"
MESSAGE_COUNT = 5
RETRY_COUNT = 3
RETRY_DELAY = 2.0

shutdown_requested = False


def signal_handler(signum, frame):
    global shutdown_requested
    shutdown_requested = True


def build_message(index):
    temperature = round(random.uniform(19.0, 26.0), 2)
    return json.dumps({"index": index, "temperature": temperature})


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to broker")
    else:
        print(f"Connection failed with reason code {reason_code}")


def on_publish(client, userdata, mid, reason_code, properties):
    pass


def connect_with_retry(client):
    for attempt in range(1, RETRY_COUNT + 1):
        if shutdown_requested:
            return False
        try:
            client.connect(BROKER_HOST, BROKER_PORT, KEEPALIVE)
            return True
        except Exception as e:
            print(f"Connection attempt {attempt}/{RETRY_COUNT} failed: {e}")
            if attempt < RETRY_COUNT:
                time.sleep(RETRY_DELAY)
    return False


def publish_messages(client):
    global shutdown_requested
    published = 0
    for i in range(MESSAGE_COUNT):
        if shutdown_requested:
            break
        payload = build_message(i)
        info = client.publish(TOPIC, payload, qos=1)
        if info.rc == mqtt.MQTT_ERR_SUCCESS:
            published += 1
            print(f"Published message {i}: {payload}")
        else:
            print(f"Failed to publish message {i}, rc={info.rc}")
        time.sleep(1)
    return published


def main():
    global shutdown_requested
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        client_id="rpi-classroom-publisher",
    )
    client.on_connect = on_connect
    client.on_publish = on_publish

    try:
        if not connect_with_retry(client):
            print("Failed to connect to broker after retries")
            sys.exit(1)

        client.loop_start()
        published = publish_messages(client)
        print(f"Published {published}/{MESSAGE_COUNT} messages")

        if published == MESSAGE_COUNT:
            sys.exit(0)
        else:
            sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
        sys.exit(1)
    finally:
        try:
            client.loop_stop()
            client.disconnect()
            print("Disconnected from broker")
        except Exception as e:
            print(f"Error during disconnect: {e}")


if __name__ == "__main__":
    main()

