import time
import logging
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    """Driver for the Aosong DHT20 I2C temperature/humidity sensor."""

    DHT20_I2C_ADDRESS = 0x38
    DHT20_STATUS_REG = 0x71
    DHT20_MEASURE_REG = 0xAC
    DHT20_MEASURE_CMD = [0x33, 0x00]

    def __init__(self, i2c_bus_number=1):
        self._i2c_bus_number = i2c_bus_number
        self._bus = None
        self._initialize()

    def _initialize(self):
        try:
            self._bus = smbus2.SMBus(self._i2c_bus_number)
        except FileNotFoundError:
            logger.error(f"I2C bus {self._i2c_bus_number} not found. Enable I2C and check /dev/i2c-{self._i2c_bus_number}.")
            return False
        except PermissionError:
            logger.error(f"Permission denied opening /dev/i2c-{self._i2c_bus_number}. Run as root or add user to the 'i2c' group.")
            return False
        except OSError as e:
            logger.error(f"Failed to open I2C bus {self._i2c_bus_number}: {e}")
            return False

        time.sleep(0.5)  # Allow sensor to stabilize after power-up

        try:
            status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
        except OSError as e:
            logger.error(f"Failed to read DHT20 status register: {e}")
            self.close()
            return False

        if (status & 0x18) != 0x18:
            logger.error(f"DHT20 not detected. Status byte 0x{status:02X} does not match expected 0x18.")
            self.close()
            return False

        logger.info("DHT20 initialized successfully.")
        return True

    def _read_register(self, register, length):
        return self._bus.read_i2c_block_data(self.DHT20_I2C_ADDRESS, register, length)

    def _write_register(self, register, data):
        self._bus.write_i2c_block_data(self.DHT20_I2C_ADDRESS, register, data)

    @staticmethod
    def _calculate_crc8(data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def get_temperature_and_humidity(self, retries=5):
        for attempt in range(retries):
            try:
                self._write_register(self.DHT20_MEASURE_REG, self.DHT20_MEASURE_CMD)
                time.sleep(0.05)  # Allow measurement to start

                # Poll status until bit 7 clears (measurement complete) or timeout
                timeout = 0.1
                start_time = time.time()
                while True:
                    status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
                    if (status & 0x80) == 0:
                        break
                    if time.time() - start_time > timeout:
                        logger.warning(f"Measurement timeout on attempt {attempt + 1}/{retries}. Retrying...")
                        time.sleep(2)
                        break
                    time.sleep(0.005)

                if (status & 0x80) != 0:
                    continue

                data = self._read_register(self.DHT20_STATUS_REG, 7)

                # Verify CRC8 over first 6 bytes
                crc_error = self._calculate_crc8(data[:6]) != data[6]
                if crc_error:
                    logger.warning(f"CRC error on attempt {attempt + 1}/{retries}. Retrying...")
                    time.sleep(2)
                    continue

                # Parse 20-bit humidity and temperature
                raw_humidity = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
                raw_temperature = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

                temperature = raw_temperature / 5242.88 - 50
                humidity = raw_humidity / 1048576 * 100

                return temperature, humidity, False

            except OSError as e:
                logger.error(f"I2C bus error on attempt {attempt + 1}/{retries}: {e}")
                time.sleep(2)

        logger.error(f"Failed to read DHT20 after {retries} retries.")
        return None, None, True

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            finally:
                self._bus = None

    def __del__(self):
        self.close()


if __name__ == "__main__":
    sensor = DHT20()
    if sensor._bus is not None:
        temp, hum, crc_err = sensor.get_temperature_and_humidity()
        if temp is not None and hum is not None:
            print(f"Temperature: {temp:.2f} C")
            print(f"Humidity: {hum:.2f} %")
            if crc_err:
                print("Warning: CRC error detected.")
        else:
            print("Failed to read sensor data.")
        sensor.close()
    else:
        print("Sensor initialization failed.")

