import asyncio
import json
import logging
import logging.handlers
import os
import signal
import sys
import time
from typing import Any, Dict, List, Optional, Tuple

import RPi.GPIO as GPIO
import adafruit_dht
import board

DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"name": "Heater", "system_code": "10101", "unit_code": "1"},
        {"name": "Light", "system_code": "10101", "unit_code": "2"},
        {"name": "Fan", "system_code": "10101", "unit_code": "3"},
    ],
}

logger = logging.getLogger("greenhouse")
logger.setLevel(logging.DEBUG)
handler = logging.handlers.RotatingFileHandler(
    "greenhouse.log", maxBytes=1024 * 1024, backupCount=5
)
formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
handler.setFormatter(formatter)
logger.addHandler(handler)


def load_config(config_file: str) -> Dict[str, Any]:
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        merged = DEFAULT_CONFIG.copy()
        merged.update(config)
        return merged
    except FileNotFoundError:
        logger.warning("Configuration file not found. Using default configuration.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logger.error(f"Invalid JSON in configuration file: {e}. Using default configuration.")
        return DEFAULT_CONFIG.copy()


def setup_gpio(transmitter_pin: int) -> None:
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(transmitter_pin, GPIO.OUT, initial=GPIO.LOW)


