import time
import logging
import sys
import signal

try:
    import board
    import busio
    import adafruit_bmp280
    from gpiozero import LED
except ImportError as e:
    print(f"Missing required library: {e}", file=sys.stderr)
    sys.exit(1)

# Configure logging to file with timestamps
logging.basicConfig(
    filename='error.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants
I2C_BUS = 1
BMP280_ADDRESS = 0x76
LED_PINS = [17, 27, 22]
UPDATE_INTERVAL = 5  # seconds
INIT_DELAY = 1  # seconds

# Global resources for cleanup
i2c = None
bmp280 = None
leds = []

def cleanup(signum=None, frame=None):
    """Release all hardware resources on exit."""
    global i2c, bmp280, leds
    for led in leds:
        try:
            led.close()
        except Exception:
            pass
    leds.clear()
    if bmp280 is not None:
        try:
            bmp280 = None
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinitialize()
        except Exception:
            pass
        i2c = None
    if signum is not None:
        sys.exit(0)

def initialize_i2c():
    """Initialize the I2C bus."""
    global i2c
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        logging.error(f"Failed to initialize I2C bus: {e}")
        print(f"Error: Failed to initialize I2C bus: {e}", file=sys.stderr)
        sys.exit(1)

def initialize_bmp280(i2c_bus):
    """Initialize the BMP280 sensor at the specified address."""
    global bmp280
    try:
        bmp280 = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=BMP280_ADDRESS)
        # Force a measurement to let the first reading stabilize
        bmp280.sea_level_pressure = 1013.25
        time.sleep(INIT_DELAY)
        return bmp280
    except ValueError as e:
        logging.error(f"BMP280 not found at address 0x{BMP280_ADDRESS:02X}: {e}")
        print(f"Error: BMP280 not found at address 0x{BMP280_ADDRESS:02X}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        logging.error(f"Failed to initialize BMP280: {e}")
        print(f"Error: Failed to initialize BMP280: {e}", file=sys.stderr)
        sys.exit(1)

def initialize_leds(pin_list):
    """Initialize LEDs on the specified GPIO pins."""
    global leds
    led_objects = []
    for pin in pin_list:
        try:
            led = LED(pin)
            led_objects.append(led)
        except Exception as e:
            logging.error(f"Failed to initialize LED on GPIO{pin}: {e}")
            print(f"Error: Failed to initialize LED on GPIO{pin}: {e}", file=sys.stderr)
            sys.exit(1)
    return led_objects

def read_pressure(bmp280_sensor):
    """Read pressure from the BMP280 sensor."""
    try:
        return bmp280_sensor.pressure
    except Exception as e:
        logging.error(f"Error reading pressure: {e}")
        return None

def control_leds(leds, pressure):
    """Control LEDs based on pressure thresholds."""
    try:
        if pressure is not None:
            if pressure < 990:
                leds[0].on()
                leds[1].off()
                leds[2].off()
            elif 990 <= pressure < 1010:
                leds[0].off()
                leds[1].on()
                leds[2].off()
            else:
                leds[0].off()
                leds[1].off()
                leds[2].on()
    except Exception as e:
        logging.error(f"Error controlling LEDs: {e}")

def main():
    """Main function to read pressure and control LEDs."""
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    i2c_bus = initialize_i2c()
    bmp280_sensor = initialize_bmp280(i2c_bus)
    led_objects = initialize_leds(LED_PINS)

    try:
        while True:
            pressure = read_pressure(bmp280_sensor)
            if pressure is not None:
                print(f"Pressure: {pressure:.2f} hPa")
                control_leds(led_objects, pressure)
            time.sleep(UPDATE_INTERVAL)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
        print(f"Error: Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

