import signal
import sys
import time
import logging
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    DHT20_I2C_ADDRESS = 0x38
    DHT20_STATUS_REG = 0x71
    DHT20_MEASURE_REG = 0xAC
    DHT20_MEASURE_CMD = [0x33, 0x00]
    MEASURE_TIMEOUT = 0.1
    POLL_INTERVAL = 0.01
    CRC_POLYNOMIAL = 0x31
    CRC_INIT = 0xFF

    def __init__(self, i2c_bus_number=1):
        self.i2c_bus_number = i2c_bus_number
        self.bus = None
        self._running = True
        try:
            self.bus = SMBus(self.i2c_bus_number)
        except FileNotFoundError:
            logger.error(f"I2C bus /dev/i2c-{self.i2c_bus_number} not found. Enable I2C and check /boot/config.txt.")
            self.bus = None
        except PermissionError:
            logger.error(f"Permission denied opening /dev/i2c-{self.i2c_bus_number}. Run as root or add user to i2c group.")
            self.bus = None
        except OSError as e:
            logger.error(f"Failed to open I2C bus {self.i2c_bus_number}: {e}")
            self.bus = None

    def _crc8(self, data):
        crc = self.CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_status(self):
        if self.bus is None:
            return None
        try:
            return self.bus.read_byte_data(self.DHT20_I2C_ADDRESS, self.DHT20_STATUS_REG)
        except OSError as e:
            logger.error(f"Error reading status register: {e}")
            return None

    def _write_command(self):
        if self.bus is None:
            return False
        try:
            self.bus.write_i2c_block_data(self.DHT20_I2C_ADDRESS, self.DHT20_MEASURE_REG, self.DHT20_MEASURE_CMD)
            return True
        except OSError as e:
            logger.error(f"Error writing measurement command: {e}")
            return False

    def _read_data(self):
        if self.bus is None:
            return None
        try:
            return self.bus.read_i2c_block_data(self.DHT20_I2C_ADDRESS, self.DHT20_STATUS_REG, 7)
        except OSError as e:
            logger.error(f"Error reading measurement data: {e}")
            return None

    def measure(self):
        if self.bus is None:
            logger.error("I2C bus not initialized.")
            return None, None, True

        if not self._write_command():
            return None, None, True

        start_time = time.time()
        while True:
            status = self._read_status()
            if status is None:
                return None, None, True
            if status & 0x80 == 0:
