import time
import signal
import sys
import board
import adafruit_dht
import RPi.GPIO as GPIO

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D4          # DHT11 data line on BCM GPIO4
RED_PIN = 17                # BCM GPIO17
GREEN_PIN = 27              # BCM GPIO27
BLUE_PIN = 22               # BCM GPIO22
PWM_FREQ = 100              # Hz
DUTY_ON = 100               # percent
DUTY_OFF = 0                # percent
SAMPLE_INTERVAL = 1.0       # seconds (DHT11 supports ~1 Hz)

# --- Globals for cleanup -----------------------------------------------------
_running = True
pwm_red = None
pwm_green = None
pwm_blue = None
dht_device = None

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup():
    global pwm_red, pwm_green, pwm_blue, dht_device
    for pwm in (pwm_red, pwm_green, pwm_blue):
        if pwm is not None:
            try:
                pwm.stop()
            except Exception:
                pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass

def _set_color(red, green, blue):
    if pwm_red is not None:
        pwm_red.ChangeDutyCycle(DUTY_ON if red else DUTY_OFF)
    if pwm_green is not None:
        pwm_green.ChangeDutyCycle(DUTY_ON if green else DUTY_OFF)
    if pwm_blue is not None:
        pwm_blue.ChangeDutyCycle(DUTY_ON if blue else DUTY_OFF)

def _read_temperature():
    """Return temperature in Celsius or None on failure."""
    try:
        return dht_device.temperature
    except RuntimeError as e:
        # DHT11 checksum / timing errors are common; log and continue
        print(f"Warning: DHT11 read error: {e}")
        return None
    except Exception as e:
        print(f"Warning: Unexpected DHT11 error: {e}")
        return None

def _color_for_temp(temp):
    if temp is None:
        return False, True, False  # Blue (last-resort)
    if temp < 20:
        return False, False, True   # Blue
    if temp <= 25:
        return False, True, False   # Green
    return True, False, False      # Red

def main():
    global pwm_red, pwm_green, pwm_blue, dht_device

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- GPIO setup ----------------------------------------------------------
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in (RED_PIN, GREEN_PIN, BLUE_PIN):
        GPIO.setup(pin, GPIO.OUT)

    # --- PWM setup -----------------------------------------------------------
    pwm_red = GPIO.PWM(RED_PIN, PWM_FREQ)
    pwm_green = GPIO.PWM(GREEN_PIN, PWM_FREQ)
    pwm_blue = GPIO.PWM(BLUE_PIN, PWM_FREQ)
    for pwm in (pwm_red, pwm_green, pwm_blue):
        pwm.start(DUTY_OFF)

    # --- DHT11 setup ---------------------------------------------------------
    try:
        dht_device = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Fatal: could not initialise DHT11 on GPIO4: {e}")
        _cleanup()
        sys.exit(1)

    # --- Main loop -----------------------------------------------------------
    last_color = (False, False, False)
    try:
        while _running:
            temp = _read_temperature()
            red, green, blue = _color_for_temp(temp)

            if (red, green, blue) != last_color:
                _set_color(red, green, blue)
                last_color = (red, green, blue)
                if temp is not None:
                    print(f"Temp: {temp:.1f}°C  ->  {'RGB'[red*2 + green*1 + blue*0]}")

            # DHT11 needs ~4 ms per transaction; wait for remainder
            time.sleep(max(0.0, SAMPLE_INTERVAL - 0.004))
    except Exception as e:
        print(f"Error in main loop: {e}")
    finally:
        _cleanup()

if __name__ == "__main__":
    main()

