import time
import math
import random
import logging
import sqlite3
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

VIBRATION_WINDOW = 20
TEMPERATURE_WINDOW = 20
THRESHOLD_REMAINING_LIFE = 100.0
DATABASE_PATH = '/tmp/wearable_health.db'
STATUS_LED_PIN = 23
SAMPLE_INTERVAL = 0.05
NUM_ITERATIONS = 30

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def init_database():
    try:
        conn = sqlite3.connect(DATABASE_PATH)
        conn.execute('CREATE TABLE IF NOT EXISTS alerts (remaining_life REAL, ts REAL)')
        conn.commit()
        return conn
    except sqlite3.Error as e:
        logging.error(f'Database init error: {e}')
        return None

def init_led():
    try:
        return LED(STATUS_LED_PIN)
    except GPIOZeroError as e:
        logging.error(f'LED init error: {e}')
        return None

def read_vibration():
    return random.uniform(0.1, 0.9)

def read_temperature():
    return random.uniform(30.0, 70.0)

def calculate_degradation(vibration_window, temperature_window):
    if not vibration_window or not temperature_window:
        return 0.0
    mean_vibration = sum(vibration_window) / len(vibration_window)
    mean_temperature = sum(temperature_window) / len(temperature_window)
    return 0.6 * mean_vibration + 0.4 * (mean_temperature / 100.0)

def estimate_remaining_life(degradation_score):
    return max(0.0, 500.0 * math.exp(-3.0 * degradation_score))

def store_alert(conn, remaining_life):
    try:
        ts = time.time()
        conn.execute('INSERT INTO alerts (remaining_life, ts) VALUES (?, ?)', (remaining_life, ts))
        conn.commit()
        logging.info(f'Alert stored: remaining_life={remaining_life:.2f}, ts={ts}')
    except sqlite3.Error as e:
        logging.error(f'Database insert error: {e}')

def main():
    conn = init_database()
    if conn is None:
        sys.exit(1)
    led = init_led()
    if led is None:
        conn.close()
        sys.exit(1)
    vibration_window = []
    temperature_window = []
    alert_active = False
    try:
        for i in range(NUM_ITERATIONS):
            if not running:
                break
            vibration = read_vibration()
            temperature = read_temperature()
            vibration_window.append(vibration)
            temperature_window.append(temperature)
            if len(vibration_window) > VIBRATION_WINDOW:
                vibration_window.pop(0)
            if len(temperature_window) > TEMPERATURE_WINDOW:
                temperature_window.pop(0)
            degradation = calculate_degradation(vibration_window, temperature_window)
            remaining_life = estimate_remaining_life(degradation)
            if remaining_life < THRESHOLD_REMAINING_LIFE and not alert_active:
                logging.warning(f'Alert: remaining_life={remaining_life:.2f} < {THRESHOLD_REMAINING_LIFE}')
                store_alert(conn, remaining_life)
                alert_active = True
            elif remaining_life >= THRESHOLD_REMAINING_LIFE and alert_active:
                alert_active = False
            if alert_active:
                led.on()
                time.sleep(1.0)
                led.off()
                time.sleep(1.0)
            else:
                led.off()
            time.sleep(SAMPLE_INTERVAL)
    except Exception as e:
        logging.error(f'Unexpected error: {e}')
    finally:
        if led:
            led.close()
        if conn:
            conn.close()
        logging.info('Cleanup complete.')

if __name__ == '__main__':
    main()

