import RPi.GPIO as GPIO
import time
import sys

DHT_PIN = 4
RETRY_DELAY = 2
MAX_RETRIES = 3
LOOP_DELAY = 5
READ_INTERVAL = 5

def read_dht22():
    """Read temperature and humidity from DHT22 sensor.
    Returns (temperature_c, humidity) or (None, None) on failure."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            # Send start signal: pull low for at least 18 ms
            GPIO.setup(DHT_PIN, GPIO.OUT)
            GPIO.output(DHT_PIN, GPIO.LOW)
            time.sleep(0.02)
            GPIO.output(DHT_PIN, GPIO.HIGH)
            time.sleep(0.000040)  # 40 µs

            # Switch to input and wait for sensor response
            GPIO.setup(DHT_PIN, GPIO.IN)
            timeout = time.time() + 0.0001
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() > timeout:
                    raise TimeoutError("Sensor not responding (no low)")
            timeout = time.time() + 0.0001
            while GPIO.input(DHT_PIN) == GPIO.LOW:
                if time.time() > timeout:
                    raise TimeoutError("Sensor not responding (no high)")
            timeout = time.time() + 0.0001
            while GPIO.input(DHT_PIN) == GPIO.HIGH:
                if time.time() > timeout:
                    raise TimeoutError("Sensor not responding (no low after high)")

            # Read 40 bits (5 bytes)
            data = []
            for _ in range(40):
                timeout = time.time() + 0.0001
                while GPIO.input(DHT_PIN) == GPIO.LOW:
                    if time.time() > timeout:
                        raise TimeoutError("Timeout waiting for bit start")
                start = time.time()
                timeout = time.time() + 0.0001
                while GPIO.input(DHT_PIN) == GPIO.HIGH:
                    if time.time() > timeout:
                        raise TimeoutError("Timeout waiting for bit end")
                duration = time.time() - start
                data.append(1 if duration > 0.00005 else 0)

            # Convert bits to bytes
            bytes_data = []
            for i in range(5):
                byte = 0
                for j in range(8):
                    byte = (byte << 1) | data[i * 8 + j]
                bytes_data.append(byte)

            # Validate checksum
            checksum = (bytes_data[0] + bytes_data[1] + bytes_data[2] + bytes_data[3]) & 0xFF
            if checksum != bytes_data[4]:
                raise ValueError(f"Checksum mismatch: calculated {checksum}, received {bytes_data[4]}")

            # Parse humidity and temperature
            humidity = bytes_data[0] + bytes_data[1] / 10.0
            temperature = bytes_data[2] + bytes_data[3] / 10.0
            return temperature, humidity

        except (TimeoutError, ValueError) as e:
            print(f"Read attempt {attempt}/{MAX_RETRIES} failed: {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                print("All retries exhausted. Waiting before next attempt.")
                time.sleep(LOOP_DELAY)
                return None, None
        except Exception as e:
            print(f"Unexpected error: {e}")
            time.sleep(LOOP_DELAY)
            return None, None

def main():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.IN)
