import serial
import time
import threading
import queue
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.animation as animation

SERIAL_PORT = '/dev/ttyS0'
BAUD_RATE = 9600
TIMEOUT = 1
EXPECTED_VALUES = 768
ROWS = 24
COLS = 32
UPDATE_INTERVAL_MS = 100


class ThermalImager:
    def __init__(self, port, baudrate, timeout):
        self.serial_port = port
        self.baud_rate = baudrate
        self.timeout = timeout
        self.serial_connection = None
        self.data_queue = queue.Queue()
        self.stop_event = threading.Event()
        self.current_image = None
        self.fig = None
        self.ax = None
        self.im = None

    def connect_serial(self):
        try:
            self.serial_connection = serial.Serial(
                self.serial_port, self.baud_rate, timeout=self.timeout
            )
            print(f"Connected to serial port {self.serial_port}")
        except serial.SerialException as e:
            print(f"Error connecting to serial port: {e}")
            raise

    def read_serial_data(self):
        try:
            while not self.stop_event.is_set():
                try:
                    raw = self.serial_connection.readline()
                    if not raw:
                        continue
                    line = raw.decode('ascii', errors='replace').strip()
                    if not line:
                        continue
                    parts = line.split(',')
                    if len(parts) != EXPECTED_VALUES:
                        print(f"Warning: expected {EXPECTED_VALUES} values, got {len(parts)}")
                        continue
                    try:
                        values = [int(x) for x in parts]
                    except ValueError:
                        print(f"Warning: non-integer data received, skipping line")
                        continue
                    image = np.array(values, dtype=np.float32).reshape((ROWS, COLS))
                    self.data_queue.put(image)
                except serial.SerialException as e:
                    print(f"Serial read error: {e}")
                    break
                except Exception as e:
                    print(f"Unexpected error in serial thread: {e}")
                    break
        except Exception as e:
            print(f"Fatal error in serial thread: {e}")
        finally:
            if self.serial_connection and self.serial_connection.is_open:
                try:
                    self.serial_connection.close()
                except Exception:
                    pass
            print("Serial thread stopped.")

    def start_serial_thread(self):
        self.serial_thread = threading.Thread(target=self.read_serial_data, daemon=True)
        self.serial_thread.start()

    def init_plot(self):
        self.fig, self.ax = plt.subplots(figsize=(8, 6))
        self.im = self.ax.imshow(np.zeros((ROWS, COLS)), cmap='inferno', interpolation='nearest', vmin=0, vmax=255)
        self.ax.set_title('Live Thermal Imaging')
        self.ax.set_xlabel('X')
        self.ax.set_ylabel('Y')
        self.fig.colorbar(self.im, ax=self.ax, label='Temperature (arbitrary units)')
        self.fig.canvas.draw()
        self.fig.canvas.flush_events()

    def update_plot(self, frame):
        try:
            image = self.data_queue.get_nowait()
            self.current_image = image
            self.im.set_data(image)
            self.im.set_clim(vmin=image.min(), vmax=image.max())
            return self.im,
        except queue.Empty:
            return self.im,
        except Exception as e:
            print(f"Plot update error: {e}")
            return self.im,

    def run(self):
        self.connect_serial()
        self.start_serial_thread()
        self.init_plot()
        try:
            anim = animation.FuncAnimation(
                self.fig, self.update_plot, interval=UPDATE_INTERVAL_MS, blit=False, cache_frame_data=False
            )
            plt.show()
        except KeyboardInterrupt:
            print("Program interrupted by user.")
        finally:
            self.stop_event.set()
            if self.serial_thread.is_alive():
                self.serial_thread.join(timeout=2.0)
            if self.serial_connection and self.serial_connection.is_open:
                self.serial_connection.close()
            if self.fig:
                plt.close(self.fig)
            print("Resources cleaned up. Exiting.")


if __name__ == "__main__":
    imager = ThermalImager(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    imager.run()

