import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle for cleanup
dht_device = None

def cleanup(signum=None, frame=None):
    """Release sensor resources and exit cleanly."""
    global dht_device
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
        dht_device = None
    if signum is not None:
        sys.exit(0)

def main():
    global dht_device

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize DHT11 sensor on GPIO4 (board.D4)
    try:
        dht_device = adafruit_dht.DHT11(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 sensor: {e}")
        sys.exit(1)

    print("DHT11 sensor initialized. Reading every 5 seconds. Press Ctrl+C to exit.")

    while True:
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C  Humidity: {humidity:.1f} %")
            else:
                print("Failed to retrieve data from sensor (None values).")

        except RuntimeError as e:
            # DHT sensors commonly throw RuntimeError on missed reads
            print(f"RuntimeError reading DHT11: {e}")
        except Exception as e:
            # Catch unexpected errors (e.g., sensor disconnected)
            print(f"Unexpected error: {e}")

        time.sleep(5)

if __name__ == "__main__":
    try:
        main()
    finally:
        cleanup()

