import signal
import sys
import time
import json
import datetime
import threading

try:
    from gpiozero import PWMLED
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

try:
    import adafruit_dht
    import board
except ImportError:
    print("Warning: adafruit-circuitpython-dht or board not installed. "
          "DHT22 logging will be disabled.")
    adafruit_dht = None
    board = None

LED_PIN = 17
DHT_PIN = 4
PWM_FREQUENCY = 100
MAX_BRIGHTNESS = 90
SUNRISE_DURATION = 600
DAYTIME_DURATION = 10
SUNSET_DURATION = 600
NIGHTTIME_DURATION = 10
DHT_READ_INTERVAL = 5
DHT_MAX_RETRIES = 3

running = True
manual_override = False
current_brightness = 0.0
pwm_led = None
dht_device = None


def log_data(brightness, temperature, humidity):
    timestamp = datetime.datetime.now().isoformat()
    log_entry = {
        "timestamp": timestamp,
        "brightness": round(brightness, 2),
        "temperature": temperature,
        "humidity": humidity,
    }
    print(json.dumps(log_entry))


def read_dht22():
    if adafruit_dht is None or board is None:
        return None, None
    if dht_device is None:
        return None, None
    for attempt in range(1, DHT_MAX_RETRIES + 1):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            print(f"DHT22 read attempt {attempt}/{DHT_MAX_RETRIES} failed: {e}")
        except Exception as e:
            print(f"DHT22 unexpected error on attempt {attempt}: {e}")
        time.sleep(0.5)
    return None, None


def set_brightness(target_brightness):
    global current_brightness
    target = max(0.0, min(float(target_brightness), float(MAX_BRIGHTNESS)))
    if target == current_brightness:
        return
    current_brightness = target
    if pwm_led is not None:
        try:
            pwm_led.value = current_brightness / 100.0
        except Exception as e:
            print(f"Error setting PWM duty cycle: {e}")
    log_data(current_brightness, None, None)


def sunrise():
    start_time = time.time()
    while time.time() - start_time < SUNRISE_DURATION and running:
        elapsed = time.time() - start_time
        brightness = (elapsed / SUNRISE_DURATION) * MAX_BRIGHTNESS
        set_brightness(brightness)
        time.sleep(0.1)
    set_brightness(MAX_BRIGHTNESS)


def daytime():
    set_brightness(MAX_BRIGHTNESS)
    time.sleep(DAYTIME_DURATION)


def sunset():
    start_time = time.time()
    while time.time() - start_time < SUNSET_DURATION and running:
        elapsed = time.time() - start_time
        brightness = MAX_BRIGHTNESS - (elapsed / SUNSET_DURATION) * MAX_BRIGHTNESS
        set_brightness(brightness)
        time.sleep(0.1)
    set_brightness(0.0)


def nighttime():
    set_brightness(0.0)
    time.sleep(NIGHTTIME_DURATION)


def emergency_shutdown(signum=None, frame=None):
    global running
    running = False
    print("\nEmergency shutdown initiated...")
    set_brightness(0.0)
    if pwm_led is not None:
        try:
            pwm_led.close()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    print("GPIO resources released. Exiting.")
    sys.exit(0)


def manual_input_thread():
    global manual_override, current_brightness
    while running:
        try:
            user_input = input("Enter brightness (0-90), 'auto', or 'exit': ").strip().lower()
        except EOFError:
            break
        if user_input == "exit":
            emergency_shutdown()
        elif user_input == "auto":
            manual_override = False
            print("Returning to automatic mode.")
        else:
            try:
                brightness = float(user_input)
                if 0 <= brightness <= MAX_BRIGHTNESS:
                    set_brightness(brightness)
                    manual_override = True
                else:
                    print("Brightness must be between 0 and 90.")
            except ValueError:
                print("Invalid input. Please enter a number, 'auto', or 'exit'.")


def main():
    global pwm_led, dht_device

    signal.signal(signal.SIGINT, emergency_shutdown)
    signal.signal(signal.SIGTERM, emergency_shutdown)

    try:
        pwm_led = PWMLED(LED_PIN, frequency=PWM_FREQUENCY, initial_value=0.0)
    except Exception as e:
        print(f"Failed to initialize PWMLED on GPIO{LED_PIN}: {e}")
        sys.exit(1)

    if adafruit_dht is not None and board is not None:
        try:
            dht_device = adafruit_dht.DHT22(board.D4, use_pulseio=False)
            print("DHT22 sensor initialized on GPIO4.")
        except Exception as e:
            print(f"Failed to initialize DHT22 on GPIO4: {e}")
            dht_device = None
    else:
        print("DHT22 logging disabled.")

    input_thread = threading.Thread(target=manual_input_thread, daemon=True)
    input_thread.start()

    try:
        while running:
            if not manual_override:
                sunrise()
                if not running:
                    break
                daytime()
                if not running:
                    break
                sunset()
                if not running:
                    break
                nighttime()
                if not running:
                    break
            else:
                time.sleep(0.5)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        emergency_shutdown()


if __name__ == "__main__":
    main()

