import time
import logging
import signal
import sys
from smbus2 import SMBus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    DHT20_I2C_ADDRESS = 0x38
    DHT20_STATUS_REG = 0x71
    DHT20_MEASURE_REG = 0xAC
    DHT20_MEASURE_CMD = [0x33, 0x00]

    def __init__(self, i2c_bus_number=1):
        self.i2c_bus_number = i2c_bus_number
        self._bus = None
        self._last_measurement = None
        self._last_measurement_time = 0.0
        self._min_measurement_interval = 2.0
        self._shutdown = False

    def __enter__(self):
        if not self.begin():
            raise RuntimeError('Failed to initialize DHT20 sensor')
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()
        return False

    def begin(self):
        try:
            self._bus = SMBus(self.i2c_bus_number)
        except OSError as e:
            logger.error(f'Failed to open I2C bus {self.i2c_bus_number}: {e}')
            self._bus = None
            return False

        time.sleep(0.5)

        try:
            status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
        except OSError as e:
            logger.error(f'Failed to read DHT20 status register: {e}')
            self.close()
            return False

        if (status & 0x18) != 0x18:
            logger.error(f'DHT20 status check failed: got 0x{status:02X}, expected 0x18')
            self.close()
            return False

        logger.info('DHT20 initialized successfully')
        return True

    def close(self):
        if self._bus is not None:
            try:
                self._bus.close()
            except OSError:
                pass
            self._bus = None

    def get_temperature_and_humidity(self):
        if self._shutdown:
            return None, None, True

        now = time.monotonic()
        if self._last_measurement is not None and (now - self._last_measurement_time) < self._min_measurement_interval:
            return self._last_measurement

        for attempt in range(5):
            if self._shutdown:
                return None, None, True

            try:
                temperature, humidity = self._read_temperature_and_humidity()
                if temperature is not None and humidity is not None:
                    self._last_measurement = (temperature, humidity)
                    self._last_measurement_time = now
                    return temperature, humidity
            except OSError as e:
                logger.error(f'I2C bus error during measurement attempt {attempt + 1}: {e}')
            except Exception as e:
                logger.error(f'Unexpected error during measurement attempt {attempt + 1}: {e}')

            if attempt < 4:
                time.sleep(0.01)

        logger.error('Failed to read temperature and humidity after 5 attempts')
        return None, None, True

    def _read_temperature_and_humidity(self):
        try:
            self._write_register(self.DHT20_MEASURE_REG, self.DHT20_MEASURE_CMD)
        except OSError as e:
            logger.error(f'Failed to trigger measurement: {e}')
            raise

        for _ in range(10):
            if self._shutdown:
                raise RuntimeError('Shutdown requested')
            time.sleep(0.08)
            try:
                status = self._read_register(self.DHT20_STATUS_REG, 1)[0]
            except OSError as e:
                logger.error(f'Failed to read status during poll: {e}')
                raise
            if (status & 0x80) == 0:
                break
        else:
            logger.warning('DHT20 measurement timed out after 10 attempts')
            raise TimeoutError('DHT20 measurement timed out')

        try:
            data = self._read_register(self.DHT20_STATUS_REG, 7)
        except OSError as e:
            logger.error(f'Failed to read measurement data: {e}')
            raise

        if len(data) < 7:
            logger.error(f'Incomplete data read: got {len(data)} bytes, expected 7')
            raise IOError('Incomplete data read from DHT20')

        received_crc = data[6]
        calculated_crc = self._calculate_crc8(data[:6])
        if received_crc != calculated_crc:
            logger.warning(f'CRC mismatch: received 0x{received_crc:02X}, calculated 0x{calculated_crc:02X}')
            raise ValueError('CRC mismatch')

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | ((data[3] & 0xF0) >> 4))
        humidity = humidity_raw / 0x100000 * 100.0

        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5])
        temperature = temperature_raw / 0x80000 * 200.0 - 50.0

        return temperature, humidity

    @staticmethod
    def _calculate_crc8(data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _write_register(self, register, data):
        self._bus.write_i2c_block_data(self.DHT20_I2C_ADDRESS, register, data)

    def _read_register(self, register, length):
        return self._bus.read_i2c_block_data(self.DHT20_I2C_ADDRESS, register, length)


def _signal_handler(signum, frame):
    logger.info(f'Received signal {signum}, shutting down...')
    raise SystemExit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        with DHT20(i2c_bus_number=1) as sensor:
            if not sensor.begin():
                print('DHT20 initialization failed. Check wiring and I2C address.')
                sys.exit(0)

            while not sensor._shutdown:
                try:
                    temp, hum, err = sensor.get_temperature_and_humidity()
                    if err:
                        print('Sensor read error; stopping.')
                        break
                    print(f'Temperature: {temp:.2f} C  Humidity: {hum:.2f} %')
                except SystemExit:
                    break
                except Exception as e:
                    logger.error(f'Unexpected loop error: {e}')
                    break
                time.sleep(2.0)
    except SystemExit:
        pass
    except Exception as e:
        logger.error(f'Fatal error: {e}')
        sys.exit(0)


if __name__ == '__main__':
    main()

