import subprocess
import time
import signal
import sys
from gpiozero import PWMOutputDevice

FAN_PIN = 14
PWM_FREQ = 100.0
POLL_INTERVAL = 5.0

TEMP_THRESHOLDS = [
    (70.0, 100.0),
    (60.0, 85.0),
    (50.0, 70.0),
    (40.0, 50.0),
    (32.0, 25.0),
    (25.0, 15.0),
]

DEFAULT_DUTY = 100.0

running = True
fan = None


def get_cpu_temp():
    """Return CPU temperature in °C, or None on error."""
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True, text=True, timeout=5, check=True
        )
        # Expected output: temp=42.8'C
        temp_str = result.stdout.strip()
        return float(temp_str.split('=')[1].split("'")[0])
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired,
            IndexError, ValueError, FileNotFoundError) as e:
        print(f"Error reading CPU temperature: {e}", file=sys.stderr)
        return None


def duty_for_temp(temp):
    for threshold, duty in TEMP_THRESHOLDS:
        if temp > threshold:
            return duty
    return 0.0


def cleanup(signum=None, frame=None):
    global running
    running = False
    if fan is not None:
        try:
            fan.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def main():
    global fan
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    last_duty = DEFAULT_DUTY
    try:
        while running:
            temp = get_cpu_temp()
            if temp is not None:
                last_duty = duty_for_temp(temp)
                fan.value = last_duty / 100.0
                print(f"CPU: {temp:.1f}°C  Fan duty: {last_duty:.0f}%")
            else:
                print(f"Temperature read failed; keeping fan at {last_duty:.0f}%.", file=sys.stderr)
            time.sleep(POLL_INTERVAL)
    finally:
        cleanup()


if __name__ == '__main__':
    main()

