import config
import time
import signal
import sys
import paho.mqtt.client as mqtt
import adafruit_dht
import board

DEGREE_CELSIUS = '\u00B0C'
MIN_READ_INTERVAL = 2.0

running = True
dht_device = None
mqtt_client = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global dht_device, mqtt_client
    if mqtt_client is not None:
        try:
            mqtt_client.loop_stop()
            mqtt_client.disconnect()
        except Exception:
            pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker")
    else:
        print(f"MQTT connection failed with reason code {reason_code}")


def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker (reason code {reason_code})")


def connect_mqtt():
    global mqtt_client
    try:
        mqtt_client = mqtt.Client(
            mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
        )
        mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        mqtt_client.on_connect = on_connect
        mqtt_client.on_disconnect = on_disconnect
        mqtt_client.connect(config.mqttbroker, config.mqttport, keepalive=60)
        mqtt_client.loop_start()
        time.sleep(1)
        if not mqtt_client.is_connected():
            raise RuntimeError("MQTT broker did not accept the connection")
    except Exception as e:
        print(f"MQTT connection error: {e}")
        raise


def publish_data(temperature, humidity):
    if mqtt_client is None or not mqtt_client.is_connected():
        print("MQTT client not connected; skipping publish")
        return
    try:
        temp_topic = f"homie/{config.homieclientid}/{config.homienodes}/temperature"
        hum_topic = f"homie/{config.homieclientid}/{config.homienodes}/humidity"
        mqtt_client.publish(temp_topic, f"{temperature:.1f}", qos=1)
        mqtt_client.publish(hum_topic, f"{humidity:.1f}", qos=1)
        print(f"Published: {temperature:.1f}{DEGREE_CELSIUS}, {humidity:.1f}%")
    except Exception as e:
        print(f"MQTT publish error: {e}")


def read_dht22():
    global dht_device
    try:
        if dht_device is None:
            pin = getattr(board, f"D{config.dhtgpiopin}")
            dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return temperature, humidity
    except RuntimeError as e:
        print(f"DHT22 read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}")
        return None, None


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        connect_mqtt()
    except Exception:
        print("Failed to connect to MQTT. Exiting.")
        cleanup()
        sys.exit(1)

    last_read_time = 0.0
    while running:
        current_time = time.monotonic()
        if current_time - last_read_time >= MIN_READ_INTERVAL:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                publish_data(temperature, humidity)
            last_read_time = current_time
        time.sleep(0.5)

    cleanup()


if __name__ == "__main__":
    main()

