import signal
import sys
import time

import serial

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT_S = 2.0
READ_INTERVAL_S = 1.0
TEMPERATURE_THRESHOLD_C = 30.0
HUMIDITY_THRESHOLD_PCT = 70.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        print(f"Serial port {port} opened at {baud} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening serial port {port}: {e}", file=sys.stderr)
        return None


def read_sensor_data(serial_connection):
    try:
        raw = serial_connection.readline()
        if not raw:
            print("Warning: no data received (sensor absent or cable issue).")
            return None, None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None, None
        parts = line.split(',')
        if len(parts) != 2:
            print(f"Warning: malformed data (expected 2 fields): '{line}'")
            return None, None
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError:
        print(f"Warning: non-numeric data received: '{line}'")
        return None, None
    except serial.SerialException as e:
        print(f"Serial I/O error: {e}", file=sys.stderr)
        return None, None
    except OSError as e:
        print(f"OS I/O error: {e}", file=sys.stderr)
        return None, None


def check_thresholds(temperature, humidity):
    if temperature > TEMPERATURE_THRESHOLD_C:
        print(f"ALERT: Temperature {temperature:.1f}C exceeds threshold {TEMPERATURE_THRESHOLD_C}C")
    if humidity > HUMIDITY_THRESHOLD_PCT:
        print(f"ALERT: Humidity {humidity:.1f}% exceeds threshold {HUMIDITY_THRESHOLD_PCT}%")


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT_S)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            temperature, humidity = read_sensor_data(serial_connection)
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%")
                check_thresholds(temperature, humidity)
            time.sleep(READ_INTERVAL_S)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")


if __name__ == "__main__":
    main()

