import time
import logging

import smbus2
from ina219 import INA219, DeviceRangeError

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("ups_monitor")

SUPPLY_INA219_ADDR = 0x40
BATTERY_INA219_ADDR = 0x45
UPS_I2C_ADDR = 0x17
I2C_BUS = 1
READ_INTERVAL = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False


def read_supply_data(supply_ina):
    try:
        voltage = supply_ina.voltage()
        current = supply_ina.current()
        print(f"Supply: {voltage:.3f} V, {current:.3f} mA")
    except DeviceRangeError:
        log.warning("Supply INA219 current out of range")
    except OSError as exc:
        log.error("Supply INA219 I/O error: %s", exc)
    except Exception as exc:
        log.error("Unexpected error reading supply INA219: %s", exc)


def read_battery_data(battery_ina):
    try:
        voltage = battery_ina.voltage()
        current = battery_ina.current()
        print(f"Battery: {voltage:.3f} V, {current:.3f} mA")
    except DeviceRangeError:
        log.warning("Battery INA219 current out of range")
    except OSError as exc:
        log.error("Battery INA219 I/O error: %s", exc)
    except Exception as exc:
        log.error("Unexpected error reading battery INA219: %s", exc)


def read_ups_data(bus):
    try:
        data = bus.read_i2c_block_data(UPS_I2C_ADDR, 0, 42)
        proc_v = (data[1] << 8) | data[0]
        batt_port_v = (data[5] << 8) | data[4]
        temp = (data[11] << 8) | data[10]
        capacity = (data[19] << 8) | data[18]
        print(f"UPS: Proc {proc_v}mV, Battery Port {batt_port_v}mV, Temp {temp}C, Capacity {capacity}%")
    except OSError as exc:
        log.error("UPS I2C read error: %s", exc)
    except IndexError as exc:
        log.error("UPS data too short: %s", exc)
    except Exception as exc:
        log.error("Unexpected error reading UPS: %s", exc)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        supply_ina = INA219(0.00725, busnum=I2C_BUS, address=SUPPLY_INA219_ADDR)
        supply_ina.configure()
    except OSError as exc:
        log.error("Cannot open supply INA219 at 0x%02X: %s", SUPPLY_INA219_ADDR, exc)
        sys.exit(1)
    except Exception as exc:
        log.error("Unexpected error initializing supply INA219: %s", exc)
        sys.exit(1)

    try:
        battery_ina = INA219(0.005, busnum=I2C_BUS, address=BATTERY_INA219_ADDR)
        battery_ina.configure()
    except OSError as exc:
        log.error("Cannot open battery INA219 at 0x%02X: %s", BATTERY_INA219_ADDR, exc)
        sys.exit(1)
    except Exception as exc:
        log.error("Unexpected error initializing battery INA219: %s", exc)
        sys.exit(1)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        log.error("Cannot open I2C bus %d: %s", I2C_BUS, exc)
        sys.exit(1)

    try:
        while _running:
            read_supply_data(supply_ina)
            read_battery_data(battery_ina)
            read_ups_data(bus)
            time.sleep(READ_INTERVAL)
    finally:
        try:
            bus.close()
        except Exception:
            pass
        log.info("Exited cleanly.")


if __name__ == "__main__":
    main()

