#!/usr/bin/env python3
"""
Raspberry Pi UPS Plus Monitor

Reads voltage, current, and power from two INA219 sensors (power supply at
0x40, battery at 0x45) and polls a UPS Plus controller at 0x17 on I2C bus 1.
"""

import signal
import sys
import time
import logging

import smbus2
from ina219 import INA219, DeviceRangeError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("ups_plus")

DEVICE_BUS = 1
DEVICE_ADDRESS = 0x17
SUPPLY_INA219_ADDRESS = 0x40
BATTERY_INA219_ADDRESS = 0x45
SHUNT_RESISTANCE_SUPPLY = 0.00725
SHUNT_RESISTANCE_BATTERY = 0.005

_running = True


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received, shutting down...", signum)
    _running = False


class INA219Sensor:
    """Thin wrapper around ina219.InA219 with error handling."""

    def __init__(self, shunt_resistance, bus_num, address):
        self.shunt_resistance = shunt_resistance
        self.bus_num = bus_num
        self.address = address
        self.ina = None
        self.bus = None
        self._init_sensor()

    def _init_sensor(self):
        try:
            self.bus = smbus2.SMBus(self.bus_num)
        except OSError as exc:
            log.error("Cannot open I2C bus %d: %s", self.bus_num, exc)
            self.bus = None
            return

        try:
            self.ina = INA219(
                self.shunt_resistance,
                busnum=self.bus_num,
                address=self.address,
            )
            self.ina.configure()
            log.info(
                "INA219 at 0x%02X initialised (shunt=%.5f Ω).",
                self.address,
                self.shunt_resistance,
            )
        except (OSError, ValueError, DeviceRangeError) as exc:
            log.error("INA219 init failed at 0x%02X: %s", self.address, exc)
            self.ina = None
            self._close_bus()

    def _close_bus(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None

    def read_all(self):
        if self.ina is None or self.bus is None:
            return None, None, None
        try:
            return self.ina.voltage(), self.ina.current(), self.ina.power()
        except DeviceRangeError:
            log.warning("Current out of range for INA219 at 0x%02X", self.address)
            return None, None, None
        except OSError as exc:
            log.error("I2C read error at 0x%02X: %s", self.address, exc)
            return None, None, None

    def get_voltage(self):
        v, _, _ = self.read_all()
        return v

    def get_current(self):
        _, c, _ = self.read_all()
        return c

    def get_power(self):
        _, _, p = self.read_all()
        return p

    def close(self):
        self._close_bus()


class UPSPlus:
    """Driver for the UPS Plus controller."""

    def __init__(self, bus_num, device_address):
        self.bus_num = bus_num
        self.device_address = device_address
        self.bus = None
        self._init_bus()

    def _init_bus(self):
        try:
            self.bus = smbus2.SMBus(self.bus_num)
            log.info("I2C bus %d opened for UPS controller 0x%02X.", self.bus_num, self.device_address)
        except OSError as exc:
            log.error("Cannot open I2C bus %d: %s", self.bus_num, exc)
            self.bus = None

    def _read_register(self, register):
        if self.bus is None:
            return None
        try:
            return self.bus.read_byte_data(self.device_address, register)
        except OSError as exc:
            log.error("Read reg 0x%02X failed: %s", register, exc)
            return None

    def _read_word(self, register):
        if self.bus is None:
            return None
        try:
            high = self.bus.read_byte_data(self.device_address, register)
            low = self.bus.read_byte_data(self.device_address, register + 1)
            return (high << 8) | low
        except OSError as exc:
            log.error("Read word 0x%02X failed: %s", register, exc)
            return None

    def get_all_data(self):
        if self.bus is None:
            return None
        data = {}
        for reg in range(256):
            data[reg] = self._read_register(reg)
        data["processor_voltage"] = self._read_word(0x01)
        data["raspberry_pi_voltage"] = self._read_word(0x03)
        data["battery_port_voltage"] = self._read_word(0x05)
        data["type_c_charging_port_voltage"] = self._read_word(0x07)
        data["micro_usb_charging_port_voltage"] = self._read_word(0x09)
        data["battery_temperature"] = self._read_word(0x0B)
        data["full_battery_voltage"] = self._read_word(0x0D)
        data["empty_battery_voltage"] = self._read_word(0x0F)
        data["battery_protection_voltage"] = self._read_word(0x11)
        data["remaining_capacity_percent"] = self._read_word(0x13)
        data["sampling_period_minutes"] = self._read_word(0x15)
        data["power_state"] = self._read_register(0x17)
        data["shutdown_countdown_seconds"] = self._read_register(0x18)
        data["auto_power_on"] = self._read_register(0x19)
        data["restart_countdown_seconds"] = self._read_register(0x1A)
        return data

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    supply_sensor = INA219Sensor(SHUNT_RESISTANCE_SUPPLY, DEVICE_BUS, SUPPLY_INA219_ADDRESS)
    battery_sensor = INA219Sensor(SHUNT_RESISTANCE_BATTERY, DEVICE_BUS, BATTERY_INA219_ADDRESS)
    ups = UPSPlus(DEVICE_BUS, DEVICE_ADDRESS)

    try:
        while _running:
            print("=" * 60)
            print(f"UPS Plus Controller 0x{DEVICE_ADDRESS:02X} | I2C bus {DEVICE_BUS}")
            print("-" * 60)

            print("Power Supply (INA219 @ 0x40):")
            v = supply_sensor.get_voltage()
            c = supply_sensor.get_current()
            p = supply_sensor.get_power()
            if v is not None and c is not None and p is not None:
                print(f"  Voltage: {v:.3f} V | Current: {c:.3f} mA | Power: {p:.3f} mW")
            else:
                print("  Sensor read failed or not present.")

            print("\nBattery (INA219 @ 0x45):")
            v = battery_sensor.get_voltage()
            c = battery_sensor.get_current()
            p = battery_sensor.get_power()
            if v is not None and c is not None and p is not None:
                print(f"  Voltage: {v:.3f} V | Current: {c:.3f} mA | Power: {p:.3f} mW")
            else:
                print("  Sensor read failed or not present.")

            print("\nUPS Controller Data:")
            data = ups.get_all_data()
            if data is not None:
                for key, value in data.items():
                    label = key.replace("_", " ").title()
                    if value is None:
                        print(f"  {label}: <read error>")
                        continue
                    if key in ("power_state", "auto_power_on", "shutdown_countdown_seconds", "restart_countdown_seconds"):
                        print(f"  {label}: {value}")
                    else:
                        print(f"  {label}: {value}")
            else:
                print("  Could not read controller data.")

            print("-" * 60)
            time.sleep(2.0)
    finally:
        supply_sensor.close()
        battery_sensor.close()
        ups.close()
        log.info("Resources released. Exiting.")


if __name__ == "__main__":
    main()

