import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def parse_sensor_data(data_string):
    parts = data_string.split(',')
    if len(parts) != 2:
        return None, None
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError:
        return None, None

def check_thresholds(temperature, humidity):
    if temperature > TEMPERATURE_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
        print('Alert: Thresholds exceeded!')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = None
    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f'Connected to {SERIAL_PORT} at {BAUD_RATE} baud.')

        while running:
            try:
                raw_line = serial_connection.readline()
                if not raw_line:
                    continue

                line = raw_line.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                temperature, humidity = parse_sensor_data(line)
                if temperature is not None and humidity is not None:
                    print(f'Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%')
                    check_thresholds(temperature, humidity)
                else:
                    print(f'Invalid data received: {line}')

                time.sleep(1)

            except serial.SerialException as e:
                print(f'Serial communication error: {e}')
                break
            except OSError as e:
                print(f'I/O error: {e}')
                break

    except serial.SerialException as e:
        print(f'Failed to open serial port {SERIAL_PORT}: {e}')
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print('Serial port closed.')
        print('Program terminated.')

if __name__ == '__main__':
    main()

