import time
import signal
import sys
from gpiozero import InputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

DOOR_SENSOR_PIN = 22
POLL_INTERVAL_S = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = InputDevice(DOOR_SENSOR_PIN, pull_up=True, active_state=None)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to initialize GPIO{DOOR_SENSOR_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error during GPIO setup: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                value = sensor.value
            except Exception as exc:
                print(f"Warning: read error on GPIO{DOOR_SENSOR_PIN}: {exc}", file=sys.stderr)
                time.sleep(POLL_INTERVAL_S)
                continue

            if value == 0:
                print("Door Closed")
            else:
                print("Door Open")

            time.sleep(POLL_INTERVAL_S)

    except KeyboardInterrupt:
        pass
    finally:
        try:
            sensor.close()
        except Exception:
            pass
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

