import signal
import sys
import time
from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Sensor pin definitions (BCM numbering)
SENSOR_PINS = [17, 27, 22]
POLL_INTERVAL = 1.0  # seconds

# Global list to hold device references for cleanup
_devices = []
_running = True


def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def initialize_sensors(pins):
    """Initialize DigitalInputDevice objects for each pin with pull-up enabled.

    Returns a list of (pin, device) tuples.  Raises on GPIO initialization errors.
    """
    devices = []
    for pin in pins:
        try:
            device = DigitalInputDevice(pin=pin, pull_up=True, bounce_time=None)
            devices.append((pin, device))
        except (GPIOZeroError, GPIODeviceError) as exc:
            print(f"Error: failed to initialize GPIO{pin}: {exc}", file=sys.stderr)
            # Clean up any devices already created before re-raising
            for dev in devices:
                dev[1].close()
            raise
    return devices


def read_sensor(pin, device):
    """Read a single sensor pin and return True if HIGH, False otherwise.

    Returns None on read error so the caller can skip the response.
    """
    try:
        return bool(device.value)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: failed to read GPIO{pin}: {exc}", file=sys.stderr)
        return None


def respond_to_sensor(pin, value):
    """Print the appropriate response for a HIGH sensor reading."""
    if value is True:
        if pin == 17:
            print("Response for sensor 1")
        elif pin == 27:
            print("Response for sensor 2")
        elif pin == 22:
            print("Response for sensor 3")


def main():
    """Main polling loop: initialize sensors, poll every POLL_INTERVAL, clean up."""
    global _devices

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        _devices = initialize_sensors(SENSOR_PINS)
    except (GPIOZeroError, GPIODeviceError):
        print("Fatal: could not initialize GPIO sensors. Exiting.", file=sys.stderr)
        sys.exit(1)

    print(f"Monitoring sensors on GPIO pins {SENSOR_PINS} "
          f"(poll interval: {POLL_INTERVAL}s). Press Ctrl+C to exit.")

    try:
        while _running:
            for pin, device in _devices:
                value = read_sensor(pin, device)
                if value is not None:
                    respond_to_sensor(pin, value)
            time.sleep(POLL_INTERVAL)
    finally:
        # Release all GPIO resources on every exit path
        for _, device in _devices:
            try:
                device.close()
            except Exception:
                pass
        _devices.clear()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

