import sys
import time
import threading
import signal
import RPi.GPIO as GPIO

# Assuming DOG module is available and provides send/receive methods
import DOG

# Constants
PROMPT = "JAYES@ROVER53:\t"
HELP_MESSAGES = {
    "help": "Call 'help <command>' for details.\nCommands:\n\t-display\n\t-help\n\t-send\n\t-start\n\t-stop\n\t-exit\n\t-write",
    "start": "Help for 'start':\nStarts listening and logs data to a file.\nUsage: start <filename>",
    "stop": "Help for 'stop':\nStops listening and closes the file.",
    "display": "Help for 'display':\nDisplays the contents of the log file.",
    "send": "Help for 'send':\nSends data using DOG protocol.\nUsage: send <data>",
    "write": "Help for 'write':\nWrites data directly to the log file.\nUsage: write <data>",
    "exit": "Help for 'exit':\nCloses the server and exits.",
}

MANUAL = "Help:\nStarts listening and logs data to a file.\nUsage: start <filename>\nStop listening and close the file.\nUsage: stop\nDisplays the contents of the log file.\nUsage: display\nSends data using DOG protocol.\nUsage: send <data>\nWrites data directly to the log file.\nUsage: write <data>\nHelp on commands:\nUsage: help <command>\nExit the server.\nUsage: exit"

# Global variables
SERVER_STARTED = False
SERVER_LOCK = threading.Lock()
FILE = None
FILE_LOCK = threading.Lock()
LOG_FILE = None
RECEIVE_THREAD = None
GPIO_INITIALIZED = False

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print("\nSignal received, shutting down...")
    stop_server()
    sys.exit(0)

def initialize_gpio():
    global GPIO_INITIALIZED
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO_INITIALIZED = True
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        GPIO_INITIALIZED = False

def cleanup_gpio():
    global GPIO_INITIALIZED
    if GPIO_INITIALIZED:
        try:
            GPIO.cleanup()
            GPIO_INITIALIZED = False
            print("GPIO cleaned up.")
        except Exception as e:
            print(f"Error cleaning up GPIO: {e}")
            GPIO_INITIALIZED = False

def help_command(args):
    if not args or args[0] not in HELP_MESSAGES:
        print(HELP_MESSAGES["help"])
    else:
        print(HELP_MESSAGES[args[0]])

def manual_command(args):
    print(MANUAL)

def receive_loop():
    global FILE, SERVER_STARTED, RECEIVE_THREAD
    while SERVER_STARTED:
        try:
            data = DOG.receive()
            if data:
                with FILE_LOCK:
                    if FILE:
                        FILE.write(data + "\n")
                        FILE.flush()
        except Exception as e:
            print(f"Error in receive loop: {e}")
            stop_server()
            break
        time.sleep(0.1)

def start_server(filename):
    global SERVER_STARTED, FILE, RECEIVE_THREAD, LOG_FILE
    with SERVER_LOCK:
        if SERVER_STARTED:
            print("Server already started.")
            return

        try:
            LOG_FILE = open(filename, "w")
            FILE = LOG_FILE
            SERVER_STARTED = True
            RECEIVE_THREAD = threading.Thread(target=receive_loop, daemon=True)
            RECEIVE_THREAD.start()
            print(f"Server started, logging to {filename}")
        except Exception as e:
            print(f"Error starting server: {e}")
