import sys

# Pin definitions (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Timing constants
SAMPLE_INTERVAL = 0.5
NUM_SAMPLES = 10

def setup_gpio():
    """Configure GPIO pins for the two IR sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def read_sensors():
    """Read both IR sensors. Returns (left, right) where 0 = line detected, 1 = no line."""
    try:
        left_state = GPIO.input(LEFT_SENSOR_PIN)
        right_state = GPIO.input(RIGHT_SENSOR_PIN)
        return left_state, right_state
    except Exception as e:
        print(f"Sensor read error: {e}")
        return None, None

def decide_direction(left_state, right_state):
    """Decide steering direction based on sensor states."""
    if left_state == 0 and right_state == 0:
        return "forward"
    elif left_state == 0 and right_state == 1:
        return "turn-left"
    elif left_state == 1 and right_state == 0:
        return "turn-right"
    else:
        return "search"

def main():
    setup_gpio()
    try:
        for sample in range(NUM_SAMPLES):
            left_state, right_state = read_sensors()
            if left_state is None:
                print(f"Sample {sample}: read error - skipping")
                time.sleep(SAMPLE_INTERVAL)
                continue
            direction = decide_direction(left_state, right_state)
            print(f"Sample {sample}: left={left_state}, right={right_state} -> {direction}")
            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nInterrupted by user")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up")

if __name__ == "__main__":
    main()

