import signal
import sys
import time
from gpiozero import DigitalOutputDevice, DigitalInputDevice, GPIOZeroError

# Constants for GPIO pin numbers (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Constants for data transmission
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
BASE_BUFFER = [0, 0, 0, 0, 0, 0, 0, 0]

# Global flag for graceful shutdown
_running = True

def signal_handler(signum, frame):
    global _running
    _running = False

def char_to_buffer(char: str) -> list:
    if len(char) != 8:
        raise ValueError("Input character must be 8 bits long.")
    return [int(bit) for bit in char]

def buffer_to_char(buffer: list) -> str:
    if len(buffer) != 8:
        raise ValueError("Input buffer must have 8 bits.")
    return "".join(map(str, buffer))

def string_to_buffer_list(input_string: str) -> list:
    return [char_to_buffer(char) for char in input_string]

def buffer_list_to_string(buffer_list: list) -> str:
    return "".join(buffer_to_char(buf) for buf in buffer_list)

def transmit_data(data: str, data_pin: int, timer_pin: int, delay: float = 0.0005) -> None:
    """Transmits a string of data over GPIO pins using gpiozero."""
    data_out = None
    timer_out = None
    try:
        data_out = DigitalOutputDevice(data_pin, initial_value=False)
        timer_out = DigitalOutputDevice(timer_pin, initial_value=False)

        buffer_list = [START_SIGNAL] + string_to_buffer_list(data) + [END_SIGNAL]

        for buffer in buffer_list:
            if not _running:
                break
            for bit in buffer:
                if not _running:
                    break
                timer_out.value = 0
                data_out.value = bit
                time.sleep(delay)
                timer_out.value = 1
                time.sleep(delay)
            time.sleep(delay)
    except GPIOZeroError as e:
        print(f"GPIO error during transmission: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error during transmission: {e}", file=sys.stderr)
    finally:
        if data_out is not None:
            data_out.close()
        if timer_out is not None:
            timer_out.close()

def receive_data(data_pin: int, timer_pin: int, timeout: float = 1.0) -> str:
    """Receives data from GPIO pins using gpiozero."""
    data_in = None
    timer_in = None
    try:
        data_in = DigitalInputDevice(data_pin, pull_up=False)
        timer_in = DigitalInputDevice(timer_pin, pull_up=False)

        start_time = time.time()
        received_buffer_list = []
        current_buffer = list(BASE_BUFFER)

        while _running:
            if time.time() - start_time > timeout:
                raise TimeoutError("Reception timed out.")

            if timer_in.value == 0:
                bit_index = received_buffer_list[-1].index(0) if received_buffer_list else 0
                current_buffer[bit_index] = 1
                received_buffer_list.append(list(current_buffer))
                current_buffer = list(BASE_BUFFER)
            elif timer_in.value == 1 and data_in.value == 1:
                if received_buffer_list and received_buffer_list[-1] == END_SIGNAL:
                    break
                time.sleep(0.0001)

        if not received_buffer_list or received_buffer_list[0] != START_SIGNAL:
            raise ValueError("Invalid start signal received.")

        return buffer_list_to_string(received_buffer_list[1:-1])
    except GPIOZeroError as e:
        print(f"GPIO error during reception: {e}", file=sys.stderr)
        return ""
    except Exception as e:
        print(f"Unexpected error during reception: {e}", file=sys.stderr)
        return ""
    finally:
        if data_in is not None:
            data_in.close()
        if timer_in is not None:
            timer_in.close()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    test_message = "Hello"
    print(f"Transmitting: {test_message}")
    transmit_data(test_message, DATA_OUT_PIN, TIMER_OUT_PIN)

    print("Waiting for reception...")
    received = receive_data(DATA_IN_PIN, TIMER_IN_PIN)
    if received:
        print(f"Received: {received}")
    else:
        print("No valid data received.")

