#!/usr/bin/python3

import pigpio
import signal
import sys
import threading
from enum import Enum
from typing import List, Optional, Tuple

# Constants
MAX_PULSE_US = 1000000  # pigpio hardware limit for pulse length in microseconds


class PullUpDown(Enum):
    """Enumeration for pull-up/down resistor states."""
    OFF = pigpio.PUD_OFF
    UP = pigpio.PUD_UP
    DOWN = pigpio.PUD_DOWN


class ValueList:
    """Manages valid logic values for a pin."""

    def __init__(self, values: Tuple[int, int] = (0, 1)):
        if len(values) != 2:
            raise ValueError("ValueList must contain exactly two values.")
        self._values = values

    def get_value(self, index: int) -> int:
        """Retrieves the value at the specified index (0 or 1)."""
        return self._values[index]

    def get_index(self, value: int) -> int:
        """Retrieves the index (0 or 1) of the specified value."""
        try:
            return self._values.index(value)
        except ValueError:
            raise ValueError(f"Invalid value: {value}. Must be one of {self._values}.")

    def __iter__(self):
        return iter(self._values)


class OutputPin:
    """Represents a GPIO pin configured for output using pigpio."""

    def __init__(self, pin_number: int, name: str, value_list: ValueList, initial_value: int = 0, close_value: Optional[int] = None, pigp: Optional[pigpio.pi] = None):
        """
        Initializes an OutputPin object.

        Args:
            pin_number: Broadcom GPIO pin number.
            name: Descriptive name for the pin.
            value_list: ValueList object defining valid logic values.
            initial_value: Initial logic value written to the pin.
            close_value: Logic value written when the pin is closed (reverted to input).
            pigp: pigpio.pi instance. If None, a new connection is created.
        """
        if not isinstance(pin_number, int) or not (0 <= pin_number <= 53):
            raise ValueError(f"Invalid pin number: {pin_number}. Must be an integer between 0 and 53.")

        if initial_value not in value_list:
            raise ValueError(f"Invalid initial value: {initial_value}. Must be one of {value_list}.")

        if close_value is not None and close_value not in value_list:
            raise ValueError(f"Invalid close value: {close_value}. Must be one of {value_list}.")

        self.pin_number = pin_number
        self.name = name
        self.value_list = value_list
        self._current_value = initial_value
        self._close_value = close_value
        self._lock = threading.Lock()

        if pigp is None:
            self.pigp = pigpio.pi()
            if not self.pigp.connected:
                raise RuntimeError("Failed to connect to pigpio daemon. Is pigpiod running?")
        else:
            self.pigp = pigp

        try:
            self.pigp.set_mode(self.pin_number, pigpio.OUTPUT)
            self._set_pin(self._current_value)
        except pigpio.error as e:
            raise RuntimeError(f"Failed to initialize GPIO {self.pin_number} as output: {e}")

    def shutdown(self) -> None:
        """Reverts the pin to input mode and writes the close value if specified."""
        with self._lock:
            if self.pigp is None or not self.pigp.connected:
                return
            try:
                if self._close_value is not None:
                    self._set_pin(self._close_value)
                self.pigp.set_mode(self.pin_number, pigpio.INPUT)
            except pigpio.error as e:
                print(f"Error shutting down pin {self.pin_number}: {e}", file=sys.stderr)

    def set_value(self, value: int) -> None:
        """Sets the pin's logic value."""
        with self._lock:
            if value not in self.value_list:
                raise ValueError(f"Invalid value: {value}. Must be one of {self.value_list}.")
            if value != self._current_value:
                self._set_pin(value)
                self._current_value = value

    def get_value(self) -> int:
        """Returns the current logic value of the pin."""
        with self._lock:
            return self._current_value

    def _set_pin(self, value: int) -> None:
        """Writes a logic value to the pin using pigpio."""
        try:
            self.pigp.write(self.pin_number, self.value_list.get_index(value))
        except pigpio.error as e:
            raise RuntimeError(f"Failed to write to GPIO {self.pin_number}: {e}")

    def __repr__(self) -> str:
        return f"{self.name} (BCM {self.pin_number}): {self._current_value}"


class TriggerPin(OutputPin):
    """Represents a GPIO pin configured to generate trigger pulses."""

    def __init__(self, pin_number: int, name: str, pulse_us: int, pulse_high: bool = True, pigp: Optional[pigpio.pi] = None):
        """
        Initializes a TriggerPin object.

        Args:
            pin_number: Broadcom GPIO pin number.
            name: Descriptive name for the pin.
            pulse_us: Pulse duration in microseconds.
            pulse_high: True for high-to-low pulse, False for low-to-high.
            pigp: pigpio.pi instance. If None, a new connection is created.
        """
        if not isinstance(pulse_us, int) or pulse_us < 0:
            raise ValueError("pulse_us must be a non-negative integer.")
        if pulse_us > MAX_PULSE_US:
            raise ValueError(f"pulse_us exceeds maximum limit of {MAX_PULSE_US} us.")

        value_list = ValueList((0, 1))
        super().__init__(pin_number, name, value_list, initial_value=0, pigp=pigp)
        self.pulse_us = pulse_us
        self.pulse_high = pulse_high
        self._trigger_lock = threading.Lock()

    def trigger(self) -> None:
        """Generates a trigger pulse on the pin."""
        with self._trigger_lock:
            if self.pigp is None or not self.pigp.connected:
                raise RuntimeError(f"pigpio connection not available for pin {self.pin_number}.")
            try:
                if self.pulse_high:
                    self.pigp.wave_clear()
                    pulse1 = pigpio.pulse(1 << self.pin_number, 0, self.pulse_us)
                    pulse2 = pigpio.pulse(0, 1 << self.pin_number, self.pulse_us)
                    self.pigp.wave_add_generic([pulse1, pulse2])
                    wf_handle = self.pigp.wave_create()
                    if wf_handle >= 0:
                        self.pigp.wave_send_once(wf_handle)
                        while self.pigp.wave_tx_busy():
                            pass
                        self.pigp.wave_delete(wf_handle)
                else:
                    self.pigp.wave_clear()
                    pulse1 = pigpio.pulse(0, 1 << self.pin_number, self.pulse_us)
                    pulse2 = pigpio.pulse(1 << self.pin_number, 0, self.pulse_us)
                    self.pigp.wave_add_generic([pulse1, pulse2])
                    wf_handle = self.pigp.wave_create()
                    if wf_handle >= 0:
                        self.pigp.wave_send_once(wf_handle)
                        while self.pigp.wave_tx_busy():
                            pass
                        self.pigp.wave_delete(wf_handle)
            except pigpio.error as e:
                raise RuntimeError(f"Failed to generate trigger pulse on pin {self.pin_number}: {e}")

    def __repr__(self) -> str:
        return f"{self.name} (BCM {self.pin_number}): trigger pulse {self.pulse_us} us, high={self.pulse_high}"


# Global references for signal handler
example_output: Optional[OutputPin] = None
example_trigger: Optional[TriggerPin] = None


def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM to cleanly shut down GPIO resources."""
    print("\nShutting down GPIO resources...")
    if example_output is not None:
        example_output.shutdown()
    if example_trigger is not None:
        example_trigger.shutdown()
    if example_output is not None and example_output.pigp is not None and example_output.pigp.connected:
        example_output.pigp.stop()
    if example_trigger is not None and example_trigger.pigp is not None and example_trigger.pigp.connected:
        example_trigger.pigp.stop()
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        example_output = OutputPin(pin_number=21, name="ExampleOutput", value_list=ValueList((0, 1)), initial_value=0)
        example_trigger = TriggerPin(pin_number=20, name="ExampleTrigger", pulse_us=100, pulse_high=True)

        print(example_output)
        print(example_trigger)

        # Example usage
        example_output.set_value(1)
        print(example_output)

        example_trigger.trigger()
        print(example_trigger)

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
    finally:
        if example_output is not None:
            example_output.shutdown()
        if example_trigger is not None:
            example_trigger.shutdown()

