# fingerprint_access_control_rpi.py
# Raspberry Pi 5 fingerprint-based access control system using Adafruit Fingerprint sensor over I2C.

import time
import board
import busio
import adafruit_fingerprint

# Constants
I2C_ADDRESS = 0x26
RETRY_DELAY = 1  # seconds between authentication attempts


def initialize_i2c():
    """Initialize the I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except ValueError as e:
        print(f"Error initializing I2C bus (lock/unable to access pins): {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing I2C bus: {e}")
        return None


def initialize_fingerprint_sensor(i2c_bus):
    """Initialize the Adafruit Fingerprint sensor at the specified I2C address."""
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus, addr=I2C_ADDRESS)
        return sensor
    except ValueError as e:
        print(f"Error initializing fingerprint sensor (I2C address 0x{I2C_ADDRESS:02X}): {e}")
        return None
    except RuntimeError as e:
        print(f"Error initializing fingerprint sensor (sensor absent or unresponsive): {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing fingerprint sensor: {e}")
        return None


def capture_fingerprint_image(sensor):
    """Capture a fingerprint image from the sensor. Returns True on success."""
    try:
        while True:
            result = sensor.get_image()
            if result == adafruit_fingerprint.OK:
                return True
            elif result == adafruit_fingerprint.NOFINGER:
                return False
            else:
                print(f"Error capturing image (code {result}); retrying...")
                time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error during image capture: {e}")
        return False


def template_fingerprint_image(sensor):
    """Convert a captured fingerprint image into a template. Returns True on success."""
    try:
        result = sensor.image_2_tz(1)
        if result == adafruit_fingerprint.OK:
            return True
        else:
            print(f"Error templating image (code {result}); retrying...")
            return False
    except Exception as e:
        print(f"Unexpected error during templating: {e}")
        return False


def search_fingerprint_database(sensor):
    """Search the fingerprint database for a match. Returns (True, id, confidence) on success."""
    try:
        result = sensor.finger_search()
        if result == adafruit_fingerprint.OK:
            return True, sensor.finger_id, sensor.confidence
        else:
            return False, None, None
    except Exception as e:
        print(f"Unexpected error during database search: {e}")
        return False, None, None


def authenticate_user(sensor):
    """Authenticate a user by capturing a fingerprint and searching the database."""
    if not capture_fingerprint_image(sensor):
        print("No finger detected; waiting for a print...")
        return False

    if not template_fingerprint_image(sensor):
        print("Failed to template fingerprint; retrying next cycle...")
        return False

    match_found, user_id, confidence = search_fingerprint_database(sensor)
    if match_found:
        print(f"Access Granted for user ID: {user_id} (Confidence: {confidence})")
        return True
    else:
        print("Access Denied: No matching fingerprint found.")
        return False


def main():
    """Main function to run the fingerprint access control system."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_fingerprint_sensor(i2c_bus)
    if sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            authenticate_user(sensor)
            time.sleep(RETRY_DELAY)
    except KeyboardInterrupt:
        print("\nExiting program...")
    finally:
        try:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        except Exception as e:
            print(f"Error deinitializing I2C bus: {e}")


if __name__ == "__main__":
    main()

