import sys
import signal

try:
    from gpiozero import PWMOutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000

fan = None
running = True

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.close()
        except DeviceClosed:
            pass
        except Exception:
            pass
        fan = None

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

try:
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except GPIOZeroError as e:
        print(f"Warning: hardware PWM unavailable on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
        except GPIOZeroError as e2:
            print(f"Error: cannot initialize PWM on GPIO{FAN_PIN}: {e2}", file=sys.stderr)
            sys.exit(1)

    print(f"PWM fan control on GPIO{FAN_PIN} @ {PWM_FREQ} Hz. Enter a speed 0-100 (or 'q' to quit).")

    while running:
        try:
            user_input = input("Enter fan speed (0-100): ").strip()
        except EOFError:
            break

        if user_input.lower() == 'q':
            break

        try:
            speed = float(user_input)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        if not 0 <= speed <= 100:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        try:
            fan.value = speed / 100.0
        except DeviceClosed:
            print("Error: PWM device is closed.", file=sys.stderr)
            break
        except Exception as e:
            print(f"Error setting PWM duty cycle: {e}", file=sys.stderr)
            break

except Exception as e:
    print(f"Unexpected error: {e}", file=sys.stderr)

finally:
    cleanup()
    print("GPIO cleanup done.")

