import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

LED_PIN = 18
HOST = '0.0.0.0'
PORT = 8080

led = None
httpd = None


def cleanup(signum=None, frame=None):
    global httpd, led
    if httpd is not None:
        try:
            httpd.shutdown()
        except Exception:
            pass
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


class LEDRequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            if self.path == '/led/on':
                led.on()
                self._respond(200, 'LED is ON')
            elif self.path == '/led/off':
                led.off()
                self._respond(200, 'LED is OFF')
            else:
                self._respond(404, 'Not Found')
        except Exception as exc:
            self._respond(500, f'Internal Server Error: {exc}')

    def _respond(self, status_code, message):
        body = message.encode('utf-8')
        self.send_response(status_code)
        self.send_header('Content-Type', 'text/plain; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
