#!/usr/bin/env python3
"""
Rainbow HAT 3-bit binary counter.

Touchpads A/B/C toggle bits 2/1/0 respectively.
  A (GPIO5) -> bit 2 (value 4)
  B (GPIO6) -> bit 1 (value 2)
  C (GPIO12) -> bit 0 (value 1)

Displays the decimal value (0-7) on the HT16K33 14-seg display at I2C 0x70,
lights the discrete RGB LEDs, colors the APA102 strip, and plays a tone.
"""

import signal
import sys
import time

import board
import busio

try:
    from gpiozero import Button, LED, OutputDevice
except ImportError:
    print("gpiozero is required: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

try:
    from adafruit_ht16k33.segments import Seg14x4
    from adafruit_ht16k33 import RGBMatrix
except ImportError:
    print("adafruit-circuitpython-ht16k33 is required: pip install adafruit-circuitpython-ht16k33", file=sys.stderr)
    Seg14x4 = None
    RGBMatrix = None

try:
    from adafruit_apa102 import APA102
except ImportError:
    print("adafruit-circuitpython-apa102 is required: pip install adafruit-circuitpython-apa102", file=sys.stderr)
    APA102 = None

# ---------------------------------------------------------------------------
# Pin map (BCM numbering)
# ---------------------------------------------------------------------------
TOUCH_PINS = [5, 6, 12]          # A, B, C
RGB_PINS = (7, 8)                # green, blue (red is fixed on the HAT)
BUZZER_PIN = 13
APA102_DATA_PIN = 10
APA102_CLOCK_PIN = 11

# Midi note 60 -> 261.625 Hz
MIDI_BASE = 60
TONE_DURATION = 0.5

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_display = None
_rgb = None
_strip = None
_buzzer = None
_touch_buttons = []
_bit_states = [False, False, False]


def _shutdown(signum=None, frame=None):
    """Turn everything off and exit cleanly."""
    global _running
    _running = False

    for led in _touch_buttons:
        try:
            led.close()
        except Exception:
            pass
    for led in _touch_buttons:
        try:
            led.close()
        except Exception:
            pass

    if _rgb is not None:
        try:
            _rgb.fill(0, 0, 0)
        except Exception:
            pass
    if _strip is not None:
        try:
            _strip.fill((0, 0, 0))
        except Exception:
            pass
    if _buzzer is not None:
        try:
            _buzzer.close()
        except Exception:
            pass
    if _display is not None:
        try:
            _display.fill(0)
        except Exception:
            pass

    if signum is not None:
        sys.exit(0)


def _update_peripherals(value: int):
    """Update display, discrete LEDs, APA102 strip, and buzzer."""
    # --- Display (HT16K33 14-seg) ---
    if _display is not None:
        try:
            _display.print_hex(value)
        except Exception as exc:
            print(f"Display update failed: {exc}", file=sys.stderr)

    # --- Discrete RGB LEDs ---
    if _rgb is not None:
        try:
            _rgb.fill(
                0xFF if _bit_states[0] else 0x00,   # red   (A)
                0xFF if _bit_states[1] else 0x00,   # green (B)
                0xFF if _bit_states[2] else 0x00,   # blue  (C)
            )
        except Exception as exc:
            print(f"RGB LED update failed: {exc}", file=sys.stderr)

    # --- APA102 strip ---
    if _strip is not None:
        try:
            _strip.fill((0, 0, 0))
            if value == 0:
                _strip[0] = (10, 10, 10)
            elif value == 7:
                for i in range(7):
                    _strip[i] = (10, 10, 10)
            else:
                red = 10 if _bit_states[0] else 0
                green = 10 if _bit_states[1] else 0
                blue = 10 if _bit_states[2] else 0
                _strip[value] = (red, green, blue)
        except Exception as exc:
            print(f"APA102 update failed: {exc}", file=sys.stderr)

    # --- Buzzer ---
    if _buzzer is not None:
        try:
            freq = 440.0 * (2.0 ** ((value - MIDI_BASE) / 12.0))
            _buzzer.frequency = freq
            _buzzer.value = 0.5
            time.sleep(TONE_DURATION)
            _buzzer.value = 0.0
        except Exception as exc:
            print(f"Buzzer update failed: {exc}", file=sys.stderr)


def _on_touch(channel: int):
    """Toggle the bit for the pressed touchpad and refresh peripherals."""
    if 0 <= channel < len(_bit_states):
        _bit_states[channel] = not _bit_states[channel]
        value = sum(2 ** (2 - i) * b for i, b in enumerate(_bit_states))
        _update_peripherals(value)


def main():
    global _display, _rgb, _strip, _buzzer, _touch_buttons

    # --- Signal handlers ---
    signal.signal(signal.SIGINT, _shutdown)
    signal.signal(signal.SIGTERM, _shutdown)

    # --- Touchpads (gpiozero Button) ---
    for idx, pin in enumerate(TOUCH_PINS):
        try:
            btn = Button(pin, pull_up=True, bounce_time=0.05)
            btn.when_pressed = lambda ch=idx: _on_touch(ch)
            _touch_buttons.append(btn)
        except Exception as exc:
            print(f"Failed to init touchpad on GPIO{pin}: {exc}", file=sys.stderr)

    # --- HT16K33 14-seg display ---
    if Seg14x4 is not None:
        try:
            i2c = busio.I2C(board.SCL, board.SDA)
            _display = Seg14x4(i2c, address=0x70)
            _display.brightness = 0.5
            _display.fill(0)
        except Exception as exc:
            print(f"Display init failed: {exc}", file=sys.stderr)
            _display = None

    # --- Discrete RGB LEDs (HT16K33 RGBMatrix) ---
    if RGBMatrix is not None:
        try:
            i2c = busio.I2C(board.SCL, board.SDA)
            _rgb = RGBMatrix(i2c, address=0x70)
            _rgb.brightness = 0.5
            _rgb.fill(0, 0, 0)
        except Exception as exc:
            print(f"RGB LED init failed: {exc}", file=sys.stderr)
            _rgb = None

    # --- APA102 LED strip ---
    if APA102 is not None:
        try:
            _strip = APA102(7, APA102_DATA_PIN, APA102_CLOCK_PIN)
            _strip.fill((0, 0, 0))
        except Exception as exc:
            print(f"APA102 init failed: {exc}", file=sys.stderr)
            _strip = None

    # --- Buzzer ---
    try:
        _buzzer = OutputDevice(BUZZER_PIN)
        _buzzer.value = 0.0
    except Exception as exc:
        print(f"Buzzer init failed: {exc}", file=sys.stderr)
        _buzzer = None

    # --- Initial state ---
    _update_peripherals(0)

    print("Rainbow HAT binary counter running. Press Ctrl+C to exit.")
    try:
        signal.pause()
    except KeyboardInterrupt:
        _shutdown()


if __name__ == "__main__":
    main()

