import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


class LEDController:
    """
    Controls an LED connected to a Raspberry Pi GPIO pin using gpiozero.
    """

    def __init__(self, pin=25):
        """
        Initializes the LEDController on the specified GPIO pin.

        Args:
            pin (int): The GPIO pin number (BCM numbering). Defaults to 25.

        Raises:
            ValueError: If the pin number is invalid or initialization fails.
        """
        if not isinstance(pin, int) or pin < 0:
            raise ValueError(f"Invalid GPIO pin number: {pin!r}")

        try:
            self.led = LED(pin)
        except GPIOZeroError as e:
            raise ValueError(f"Failed to initialize GPIO {pin}: {e}") from e
        except Exception as e:
            raise ValueError(f"Unexpected error initializing GPIO {pin}: {e}") from e

    def on(self):
        """Turns the LED on."""
        try:
            self.led.on()
        except Exception as e:
            print(f"Error turning LED on: {e}", file=sys.stderr)

    def off(self):
        """Turns the LED off."""
        try:
            self.led.off()
        except Exception as e:
            print(f"Error turning LED off: {e}", file=sys.stderr)

    def blink(self, on_duration=1.0, off_duration=0.5):
        """
        Blinks the LED once: on for on_duration, off for off_duration.

        Args:
            on_duration (float): Duration in seconds the LED stays on. Defaults to 1.0.
            off_duration (float): Duration in seconds the LED stays off. Defaults to 0.5.
        """
        if not isinstance(on_duration, (int, float)) or on_duration < 0:
            raise ValueError(f"Invalid on_duration: {on_duration!r}")
        if not isinstance(off_duration, (int, float)) or off_duration < 0:
            raise ValueError(f"Invalid off_duration: {off_duration!r}")

        self.on()
        time.sleep(on_duration)
        self.off()
        time.sleep(off_duration)

    def cleanup(self):
        """Turns the LED off and releases GPIO resources."""
        try:
            self.led.close()
        except Exception:
            pass


def main():
    """Main function to demonstrate LED blinking with graceful shutdown."""
    led_controller = None

    def signal_handler(signum, frame):
        print(f"\nReceived signal {signum}, shutting down...")
        if led_controller is not None:
            led_controller.off()
            led_controller.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        led_controller = LEDController(pin=25)
        print("LED blinking on GPIO 25. Press Ctrl+C to stop.")
        while True:
            led_controller.blink(on_duration=1.0, off_duration=0.5)
    except ValueError as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
        if led_controller is not None:
            led_controller.off()
            led_controller.cleanup()
        sys.exit(1)


if __name__ == "__main__":
    main()

