import random
import json
import sys
from gpiozero import Device

# Constants for command keywords and actions
COMMAND_KEYWORDS = ['water', 'stop', 'status']
FARM_ACTIONS = {
    'water': 'open_valve',
    'stop': 'close_valve',
    'status': 'report'
}

def transcribe_audio_frame(audio_frame):
    """Transcribe a simulated audio frame into a command keyword."""
    energy_level = sum(audio_frame) % 3
    return COMMAND_KEYWORDS[energy_level]

def choose_action(command_keyword):
    """Map a command keyword to a farm action."""
    return FARM_ACTIONS.get(command_keyword, 'unknown')

def save_actions_to_json(actions, filename='voice_actions.json'):
    """Save the list of actions to a JSON file."""
    try:
        with open(filename, 'w') as f:
            json.dump(actions, f, indent=2)
        print(f"Actions saved to {filename}")
    except IOError as e:
        print(f"Error saving actions to {filename}: {e}", file=sys.stderr)

def run_voice_recognition_simulation(num_frames=6):
    """Run the voice recognition simulation loop."""
    chosen_actions = []
    try:
        for frame_index in range(num_frames):
            # Simulate an audio frame as a list of random energy values
            audio_frame = [random.randint(0, 9) for _ in range(3)]
            command_keyword = transcribe_audio_frame(audio_frame)
            action = choose_action(command_keyword)
            chosen_actions.append(action)
            print(f"Frame {frame_index}: Word '{command_keyword}' -> Action '{action}'")
    except Exception as e:
        print(f"An error occurred during simulation: {e}", file=sys.stderr)
    finally:
        save_actions_to_json(chosen_actions)

if __name__ == "__main__":
    run_voice_recognition_simulation(6)

