import random
import signal
import sys
import time

from gpiozero import DigitalOutputDevice, DigitalInputDevice
from gpiozero.exc import GPIOZeroError

PUMP_PIN = 18
SENSOR_PIN = 17
LOW_THRESHOLD = 20
HIGH_THRESHOLD = 80
NUM_READINGS = 5
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_water_level():
    return random.randint(0, 100)

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pump = DigitalOutputDevice(PUMP_PIN, active_high=True, initial_value=False)
        sensor = DigitalInputDevice(SENSOR_PIN, pull_up=True)
    except GPIOZeroError as exc:
        print(f"Failed to initialize GPIO: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break

            level = read_water_level()
            sensor_state = sensor.value

            if level < LOW_THRESHOLD:
                pump.on()
                pump_state = "ON"
            elif level > HIGH_THRESHOLD:
                pump.off()
                pump_state = "OFF"
            else:
                pump_state = "UNCHANGED"

            print(f"Reading {i + 1}/{NUM_READINGS}: Level={level}% | Pump={pump_state} | Sensor={int(sensor_state)}")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)

    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        try:
            pump.close()
            sensor.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

