import time
import datetime
import threading
import json
import os
import gzip
import random
import signal
import sys
import smbus2

# Configuration
I2C_ADDRESSES = [0x3B, 0x3C, 0x3D]
LOG_FILE_SIZE_LIMIT = 1024 * 1024  # 1 MB
LOG_FILE_PERMISSIONS = 0o600
DATA_ACQUISITION_INTERVAL = 5  # seconds

# Global state
sensor_data = {addr: None for addr in I2C_ADDRESSES}
data_lock = threading.Lock()
running = True


def simulate_mcp39f511n_data(i2c_address):
    """Simulates data from an MCP39F511N energy monitor."""
    return {
        "timestamp": datetime.datetime.now().isoformat(),
        "active_power": round(random.uniform(50, 200), 2),
        "voltage": round(random.uniform(220, 240), 2),
        "current": round(random.uniform(0.2, 1.0), 2),
        "frequency": round(random.uniform(59.5, 60.5), 2),
        "power_factor": round(random.uniform(0.8, 1.0), 2),
        "i2c_address": i2c_address,
    }


def log_data(data):
    """Logs sensor data to a JSON file, rotating/compressing when size limit is reached."""
    global running
    if not running:
        return

    try:
        today = datetime.date.today()
        log_filename = f"energy_log_{today.isoformat()}.json"
        temp_filename = f"energy_log_{today.isoformat()}.json.tmp"

        # Check if rotation is needed
        rotate = False
        if os.path.exists(log_filename):
            if os.path.getsize(log_filename) > LOG_FILE_SIZE_LIMIT:
                rotate = True

        if rotate:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            compressed_filename = f"energy_log_{today.isoformat()}_{timestamp}.json.gz"
            try:
                with open(log_filename, 'rb') as f_in, gzip.open(compressed_filename, 'wb') as f_out:
                    f_out.writelines(f_in)
                os.remove(log_filename)
                os.rename(compressed_filename, log_filename)
            except Exception as e:
                print(f"Error compressing log file: {e}", file=sys.stderr)
                return

        # Write new data atomically via temp file
        with open(temp_filename, 'a') as f:
            json.dump(data, f)
            f.write('\n')

        os.replace(temp_filename, log_filename)
        os.chmod(log_filename, LOG_FILE_PERMISSIONS)

    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error in log_data: {e}", file=sys.stderr)


def data_acquisition_thread():
    """Thread function to acquire and log data periodically."""
    global running
    while running:
        for i2c_address in I2C_ADDRESSES:
            try:
                data = simulate_mcp39f511n_data(i2c_address)
                log_data(data)
                with data_lock:
                    sensor_data[i2c_address] = data
            except Exception as e:
                print(f"Error acquiring data from 0x{i2c_address:02X}: {e}", file=sys.stderr)
        time.sleep(DATA_ACQUISITION_INTERVAL)


def view_current_readings():
    """Displays the most recent sensor readings."""
    print("Current Sensor Readings:")
    for i2c_address in I2C_ADDRESSES:
        with data_lock:
            data = sensor_data.get(i2c_address)
        if data:
            print(f"Sensor 0x{i2c_address:02X}: {data['active_power']} W")
        else:
            print(f"Sensor 0x{i2c_address:02X}: No data available")


def view_data_by_date(date_str):
    """Displays sensor data for a specific date."""
    try:
        date = datetime.datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        print("Invalid date format. Please use YYYY-MM-DD.")
        return

    log_filename = f"energy_log_{date.isoformat()}.json"
    if not os.path.exists(log_filename):
        print(f"No data found for {date.isoformat()}.")
        return

    try:
        with open(log_filename, 'r') as f:
            for line in f:
                try:
                    data = json.loads(line.strip())
                    if data.get('timestamp'):
                        dt = datetime.datetime.fromisoformat(data['timestamp'])
                        if dt.date() == date:
                            print(f"0x{data['i2c_address']:02X}: {data['active_power']} W")
                except json.JSONDecodeError:
                    continue
    except OSError as e:
        print(f"Error reading log file: {e}", file=sys.stderr)


def calculate_min_max_avg(date_str, i2c_address):
    """Calculates min, max, and average active power for a given sensor and date."""
    try:
        date = datetime.datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        print("Invalid date format. Please use YYYY-MM-DD.")
        return

    log_filename = f"energy_log_{date.isoformat()}.json"
    if not os.path.exists(log_filename):
        print(f"No data found for {date.isoformat()}.")
        return

    active_powers = []
    try:
        with open(log_filename, 'r') as f:
            for line in f:
                try:
                    data = json.loads(line.strip())
                    if data.get('i2c_address') == i2c_address and data.get('timestamp'):
                        dt = datetime.datetime.fromisoformat(data['timestamp'])
                        if dt.date() == date:
                            active_powers.append(data['active_power'])
                except json.JSONDecodeError:
                    continue
    except OSError as e:
        print(f"Error reading log file: {e}", file=sys.stderr)
        return

    if not active_powers:
        print(f"No data found for sensor 0x{i2c_address:02X} on {date.isoformat()}.")
        return

    min_power = min(active_powers)
    max_power = max(active_powers)
    avg_power = sum(active_powers) / len(active_powers)

    print(f"Sensor 0x{i2c_address:02X} on {date.isoformat()}:")
    print(f"  Min: {min_power:.2f} W")
    print(f"  Max: {max_power:.2f} W")
    print(f"  Avg: {avg_power:.2f} W")


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    running = False


def main():
    """Main function to run the energy monitoring program."""
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    acquisition_thread = threading.Thread(target=data_acquisition_thread, daemon=True)
    acquisition_thread.start()

    try:
        while running:
            print("\nOptions:")
            print("1. View current sensor readings")
            print("2. View data for a specific date (YYYY-MM-DD)")
            print("3. View min/max/avg active power for a sensor and date")
            print("4. Quit")

            choice = input("Enter your choice: ").strip()

            if choice == '1':
                view_current_readings()
            elif choice == '2':
                date_str = input("Enter the date (YYYY-MM-DD): ").strip()
                view_data_by_date(date_str)
            elif choice == '3':
                date_str = input("Enter the date (YYYY-MM-DD): ").strip()
                try:
                    i2c_address = int(input("Enter the I2C address (0x3B, 0x3C, 0x3D): ").strip(), 0)
                except ValueError:
                    print("Invalid I2C address.")
                    continue
                if i2c_address not in I2C_ADDRESSES:
                    print("Invalid I2C address. Must be 0x3B, 0x3C, or 0x3D.")
                    continue
                calculate_min_max_avg(date_str, i2c_address)
            elif choice == '4':
                running = False
            else:
                print("Invalid choice. Please try again.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        running = False
        acquisition_thread.join(timeout=2)
        print("Program terminated.")


if __name__ == "__main__":
    main()

