import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Configuration
LED_PIN = 18
READING_THRESHOLD = 50
NUM_READINGS = 5
DELAY_SECONDS = 2
RETRY_CHANCE = 0.10

# Global flag for graceful shutdown
_running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def simulate_water_quality_reading():
    """Simulates a water quality reading as a percentage (0-100)."""
    return random.randint(0, 100)


def read_water_quality():
    """Reads water quality, retrying once on simulated failure."""
    if random.random() < RETRY_CHANCE:
        print("Sensor read failed, retrying once...")
        time.sleep(0.5)
        return simulate_water_quality_reading()
    return simulate_water_quality_reading()


def control_led(led, water_quality):
    """Controls the LED based on the water quality reading."""
    if water_quality < READING_THRESHOLD:
        led.on()
        print(f"Water quality low ({water_quality}% < {READING_THRESHOLD}%). LED ON.")
    else:
        led.off()
        print(f"Water quality acceptable ({water_quality}% >= {READING_THRESHOLD}%). LED OFF.")


def main():
    """Main function to simulate water quality monitoring."""
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize LED with error handling
    try:
        led = LED(LED_PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Failed to initialize LED on GPIO{LED_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing LED: {e}")
        sys.exit(1)

    try:
        reading_count = 0
        while _running and reading_count < NUM_READINGS:
            try:
                water_quality = read_water_quality()
                control_led(led, water_quality)
            except Exception as e:
                print(f"Error during reading cycle: {e}")
                led.off()

            reading_count += 1
            if _running and reading_count < NUM_READINGS:
                time.sleep(DELAY_SECONDS)

        if not _running:
            print("\nShutdown requested. Exiting gracefully.")
        else:
            print("Water quality monitoring simulation complete.")

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        # Ensure LED is off and resources are released
        try:
            led.off()
            led.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()

