import random
import time
from gpiozero import DigitalInputDevice, DigitalOutputDevice

# GPIO pin definitions
WATER_SENSOR_PIN = 17   # Digital input with internal pull-up (simulated sensor)
PUMP_CONTROL_PIN = 18    # Digital output controlling the water pump

# Water level thresholds
LOW_WATER_THRESHOLD = 20
HIGH_WATER_THRESHOLD = 80

# Simulation parameters
NUM_ITERATIONS = 5
DELAY_SECONDS = 2


def get_simulated_water_level():
    """Generate a random water level between 0 and 100."""
    return random.randint(0, 100)


def main():
    # Initialize GPIO devices with error handling
    try:
        sensor = DigitalInputDevice(WATER_SENSOR_PIN, pull_up=True)
        pump = DigitalOutputDevice(PUMP_CONTROL_PIN, initial_value=False)
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}")
        return

    try:
        for i in range(NUM_ITERATIONS):
            water_level = get_simulated_water_level()
            print(f"[{i + 1}/{NUM_ITERATIONS}] Water Level: {water_level}%")

            if water_level < LOW_WATER_THRESHOLD:
                pump.on()
                print("  Pump State: ON (Water level too low)")
            elif water_level > HIGH_WATER_THRESHOLD:
                pump.off()
                print("  Pump State: OFF (Water level sufficient)")
            else:
                # Maintain current pump state for levels in the safe range
                state = "ON" if pump.value else "OFF"
                print(f"  Pump State: {state} (Water level within safe range)")

            time.sleep(DELAY_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        # Clean resource release on all exit paths
        try:
            pump.close()
        except Exception:
            pass
        try:
            sensor.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

