import time
import signal
import sys
import board
import busio
import adafruit_tcs34725
from PIL import Image

# Global resources for cleanup
i2c_bus = None
color_sensor = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global running
    running = False


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    global i2c_bus
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_color_sensor(i2c):
    """Initialize the TCS34725 color sensor at default address 0x29."""
    global color_sensor
    try:
        color_sensor = adafruit_tcs34725.TCS34725(i2c)
        # Set integration time to 50 ms and gain to 4x
        color_sensor.integration_time = adafruit_tcs34725.INTEGRATION_TIME_50MS
        color_sensor.gain = adafruit_tcs34725.GAIN_4X
        return color_sensor
    except ValueError as e:
        print(f"TCS34725 not found on the I2C bus (address 0x29): {e}")
        return None
    except Exception as e:
        print(f"Error initializing TCS34725 sensor: {e}")
        return None


def get_sensor_color_data(sensor):
    """Read red, green, blue, and clear channel values from the sensor."""
    if sensor is None:
        return 0, 0, 0, 0
    try:
        r, g, b, c = sensor.color_rgb_bytes
        return r, g, b, c
    except Exception as e:
        print(f"Error reading color data: {e}")
        return 0, 0, 0, 0


def find_dominant_image_color(image_path):
    """Identify the dominant color in the specified image file."""
    try:
        with Image.open(image_path) as img:
            resized_img = img.resize((100, 100))
            colors = resized_img.getcolors(10000)
            if colors:
                # colors is a list of (count, (R, G, B)) tuples
                dominant_color = max(colors, key=lambda item: item[0])[1]
                return dominant_color
            return (0, 0, 0)
    except FileNotFoundError:
        print(f"Error: Image file not found at {image_path}")
        return (0, 0, 0)
    except (IOError, OSError) as e:
        print(f"Error opening or processing image: {e}")
        return (0, 0, 0)
    except Exception as e:
        print(f"Unexpected error processing image: {e}")
        return (0, 0, 0)


def cleanup():
    """Release hardware resources."""
    global i2c_bus, color_sensor
    if color_sensor is not None:
        try:
            color_sensor.deinit()
        except Exception:
            pass
        color_sensor = None
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        i2c_bus = None


def main():
    """Main loop: read sensor and image color data every second."""
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c = initialize_i2c()
    if i2c is None:
        sys.exit(1)

    sensor = initialize_color_sensor(i2c)
    if sensor is None:
        cleanup()
        sys.exit(1)

    image_file = "image.jpg"

    try:
        while running:
            r, g, b, c = get_sensor_color_data(sensor)
            print(f"Sensor - R: {r}, G: {g}, B: {b}, Clear: {c}")

            dominant = find_dominant_image_color(image_file)
            print(f"Image - Dominant Color: {dominant}")

            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

