ZSCORE_THRESHOLD = 3.0
MIN_STD = 1.0
NUM_SAMPLES = 15
SAMPLE_DELAY = 0.2

running = True
bus = None

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Shutdown signal received.")

def init_sensor(bus):
    try:
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0x00)
        time.sleep(0.1)
        logging.info("MPU6050 initialized (wakeup).")
    except OSError as e:
        logging.error(f"Failed to initialize MPU6050: {e}")
        raise

def read_acceleration(bus):
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, ACCEL_XOUT_H, 6)
        x = (data[0] << 8) | data[1]
        y = (data[2] << 8) | data[3]
        z = (data[4] << 8) | data[5]
        if x >= 0x8000:
            x -= 0x10000
        if y >= 0x8000:
            y -= 0x10000
        if z >= 0x8000:
            z -= 0x10000
        return x, y, z
    except OSError as e:
        logging.error(f"I2C read error: {e}")
        return None, None, None

def calculate_magnitude(x, y, z):
    return math.sqrt(x * x + y * y + z * z)

def calculate_zscore(value, mean, std):
    return (value - mean) / (std if std > 0 else MIN_STD)

def detect_anomaly(value, window):
    if len(window) < ACCEL_WINDOW_SIZE:
        return False
    mean = sum(window) / len(window)
    variance = sum((x - mean) ** 2 for x in window) / len(window)
    std = math.sqrt(variance)
    zscore = calculate_zscore(value, mean, std)
    return abs(zscore) > ZSCORE_THRESHOLD

def main():
    global bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        bus = smbus2.SMBus(1)
        init_sensor(bus)
        accel_window = deque(maxlen=ACCEL_WINDOW_SIZE)
        for i in range(NUM_SAMPLES):
            if not running:
                break
            x, y, z = read_acceleration(bus)
            if x is None:
                time.sleep(SAMPLE_DELAY)
                continue
            magnitude = calculate_magnitude(x, y, z)
            accel_window.append(magnitude)
            is_anomaly = detect_anomaly(magnitude, accel_window)
            if is_anomaly:
                logging.warning(f"Anomaly detected at sample {i}: magnitude={magnitude:.2f}")
            else:
                logging.info(f"Sample {i}: magnitude={magnitude:.2f}")
            time.sleep(SAMPLE_DELAY)
    except OSError as e:
        logging.error(f"I2C bus error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if bus is not None:
            try:
                bus.close()
                logging.info("I2C bus closed.")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

