import random
import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

PUMP_PIN = 17
THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_soil_moisture():
    return random.randint(0, 100)

def control_water_pump(pump, moisture_level):
    if moisture_level < THRESHOLD:
        pump.on()
        print(f"  -> Water Pump ON: Soil too dry ({moisture_level}% < {THRESHOLD}%)")
    else:
        pump.off()
        print(f"  -> Water Pump OFF: Soil moisture adequate ({moisture_level}%)")

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        pump = OutputDevice(PUMP_PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Failed to initialize GPIO {PUMP_PIN}: {e}")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO {PUMP_PIN}: {e}")
        sys.exit(1)

    try:
        for i in range(ITERATIONS):
            if not _running:
                print("\nShutdown requested. Exiting loop early.")
                break

            moisture = read_soil_moisture()
            print(f"[{i + 1}/{ITERATIONS}] Soil Moisture: {moisture}%")
            control_water_pump(pump, moisture)

            if i < ITERATIONS - 1 and _running:
                time.sleep(DELAY_SECONDS)

    except Exception as e:
        print(f"\nRuntime error: {e}")

    finally:
        try:
            pump.off()
            pump.close()
            print("\nPump turned OFF and GPIO released.")
        except Exception:
            pass

if __name__ == "__main__":
    main()

