#!/usr/bin/env python3
"""
Raspberry Pi control of an Arduino Motor Shield (L293D + 74HC595 shift register)
using RPi.GPIO for bit-banging the shift register and gpiozero for PWM outputs.

Wiring (BCM numbering):
  74HC595: LATCH -> BCM 11, CLOCK -> BCM 9,  DATA -> BCM 10
  Motor 1: PWM -> BCM 13, direction bits 0b00000010 (CW), 0b00000001 (CCW), 0b00000000 (stop)
  Motor 2: PWM -> BCM 12, direction bits 0b00001000 (CW), 0b00000100 (CCW), 0b00000000 (stop)
"""

import logging
import signal
import sys
import time

import RPi.GPIO as GPIO
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class Motor:
    """Single DC motor driven by a 74HC595 shift-register direction line and a PWM pin."""

    def __init__(self, motor_id, pwm_pin, direction_bits, pwm_frequency=100):
        self.motor_id = motor_id
        self.pwm_pin = pwm_pin
        self.direction_bits = direction_bits
        self.pwm_frequency = pwm_frequency
        self.pwm = None
        self._shift_device = None

    def start(self, direction, duty_cycle=50, shift_device=None):
        """Start the motor in *direction* at *duty_cycle* percent."""
        if shift_device is None:
            raise RuntimeError("shift_device must be provided before starting a motor")
        if self.pwm is not None:
            raise RuntimeError(f"Motor {self.motor_id} is already running")
        if direction not in self.direction_bits:
            raise ValueError(f"Invalid direction {direction} for motor {self.motor_id}")
        if not 0 <= duty_cycle <= 100:
            raise ValueError(f"Duty cycle must be 0-100, got {duty_cycle}")

        try:
            shift_device.write_bits(self.direction_bits[direction])
            self.pwm = PWMOutputDevice(
                self.pwm_pin, frequency=self.pwm_frequency, initial_value=0
            )
            self.pwm.value = duty_cycle / 100.0
            logger.info(
                "Motor %d started: direction=%s, duty_cycle=%d%%",
                self.motor_id,
                direction,
                duty_cycle,
            )
        except Exception as exc:
            logger.error("Failed to start motor %d: %s", self.motor_id, exc)
            raise

    def change_duty_cycle(self, duty_cycle):
        """Change the running motor's duty cycle (0-100)."""
        if self.pwm is None:
            raise RuntimeError(f"Motor {self.motor_id} is not running")
        if not 0 <= duty_cycle <= 100:
            raise ValueError(f"Duty cycle must be 0-100, got {duty_cycle}")
        try:
            self.pwm.value = duty_cycle / 100.0
            logger.info("Motor %d duty cycle changed to %d%%", self.motor_id, duty_cycle)
        except Exception as exc:
            logger.error("Failed to change duty cycle for motor %d: %s", self.motor_id, exc)
            raise

    def stop(self, shift_device=None):
        """Stop the motor: clear direction bits and turn off PWM."""
        if shift_device is not None:
            try:
                shift_device.write_bits(0)
            except Exception as exc:
                logger.error("Failed to clear direction bits for motor %d: %s", self.motor_id, exc)
        if self.pwm is not None:
            try:
                self.pwm.value = 0
                self.pwm.close()
            except Exception as exc:
                logger.error("Failed to stop PWM for motor %d: %s", self.motor_id, exc)
            finally:
                self.pwm = None
        logger.info("Motor %d stopped", self.motor_id)


class MotorShield:
    """Bit-bangs a 74HC595 shift register to set motor direction bits and drives PWM via gpiozero."""

    def __init__(self, latch_pin, clock_pin, data_pin, pwm_frequency=100):
        self.latch_pin = latch_pin
        self.clock_pin = clock_pin
        self.data_pin = data_pin
        self.pwm_frequency = pwm_frequency
        self.motors = {}
        self._shift_device = None
        self._gpio_ready = False

    def __enter__(self):
        self._setup_gpio()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.cleanup()
        return False

    def _setup_gpio(self):
        """Configure RPi.GPIO for the shift-register control lines."""
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            for pin in (self.latch_pin, self.clock_pin, self.data_pin):
                GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
            self._gpio_ready = True
            logger.info(
                "Shift register control pins ready: LATCH=%d, CLOCK=%d, DATA=%d",
                self.latch_pin,
                self.clock_pin,
                self.data_pin,
            )
        except Exception as exc:
            logger.error("Failed to setup GPIO: %s", exc)
            self._gpio_ready = False
            raise

    def _cleanup_gpio(self):
        """Release RPi.GPIO resources."""
        if self._gpio_ready:
            try:
                GPIO.cleanup()
            except Exception as exc:
                logger.error("GPIO cleanup error: %s", exc)
            finally:
                self._gpio_ready = False

    def add_motor(self, motor_id, pwm_pin, direction_bits):
        """Register a motor with its PWM pin and direction bit patterns."""
        if motor_id in self.motors:
            raise ValueError(f"Motor ID {motor_id} already exists")
        self.motors[motor_id] = Motor(motor_id, pwm_pin, direction_bits, self.pwm_frequency)

    def start(self, motor_id, direction, duty_cycle=50):
        """Start a registered motor."""
        motor = self.motors.get(motor_id)
        if motor is None:
            raise ValueError(f"Unknown motor ID: {motor_id}")
        motor.start(direction, duty_cycle, self)

    def change_duty_cycle(self, motor_id, duty_cycle):
        """Change the duty cycle of a running motor."""
        motor = self.motors.get(motor_id)
        if motor is None:
            raise ValueError(f"Unknown motor ID: {motor_id}")
        motor.change_duty_cycle(duty_cycle)

    def stop(self, motor_id):
        """Stop a specific motor."""
        motor = self.motors.get(motor_id)
        if motor is None:
            raise ValueError(f"Unknown motor ID: {motor_id}")
        motor.stop(self)

    def stop_all_motors(self):
        """Stop every registered motor."""
        for motor_id in list(self.motors):
            try:
                self.stop(motor_id)
            except Exception as exc:
                logger.error("Failed to stop motor %d: %s", motor_id, exc)

    def cleanup(self):
        """Stop all motors and release GPIO resources."""
        self.stop_all_motors()
        self._cleanup_gpio()


class ShiftRegister74HC595:
    """Bit-bang a 74HC595 shift register via RPi.GPIO."""

    def __init__(self, latch_pin, clock_pin, data_pin):
        self.latch_pin = latch_pin
        self.clock_pin = clock_pin
        self.data_pin = data_pin

    def write_bits(self, value):
        """Shift *value* (8-bit) into the register and latch it."""
        if not isinstance(value, int) or not (0 <= value <= 0xFF):
            raise ValueError("Value must be an 8-bit integer")
        try:
            GPIO.output(self.latch_pin, GPIO.LOW)
            for i in range(8):
                bit = (value >> (7 - i)) & 0x01
                GPIO.output(self.clock_pin, GPIO.LOW)
                GPIO.output(self.data_pin, GPIO.HIGH if bit else GPIO.LOW)
                GPIO.output(self.clock_pin, GPIO.HIGH)
            GPIO.output(self.latch_pin, GPIO.HIGH)
        except Exception as exc:
            logger.error("Shift register write failed: %s", exc)
            raise


def _signal_handler(signum, frame, shield=None):
    """Handle SIGINT/SIGTERM by stopping motors and cleaning up."""
    logger.info("Signal %d received, shutting down...", signum)
    if shield is not None:
        shield.cleanup()
    sys.exit(0)


def main():
    LATCH_PIN = 11
    CLOCK_PIN = 9
    DATA_PIN = 10
    PWM_FREQ = 100

    try:
        with MotorShield(LATCH_PIN, CLOCK_PIN, DATA_PIN, pwm_frequency=PWM_FREQ) as shield:
            shield.add_motor(1, 13, {"cw": 0b00000010, "ccw": 0b00000001, "stop": 0b00000000})
            shield.add_motor(2, 12, {"cw": 0b00001000, "ccw": 0b00000100, "stop": 0b00000000})

            signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, shield))
            signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, shield))

            shield.start(1, "cw", 75)
            shield.start(2, "ccw", 50)
            time.sleep(5)
            shield.change_duty_cycle(1, 25)
            time.sleep(2)
            shield.stop_all_motors()
    except Exception as exc:
        logger.error("Fatal error: %s", exc)
        sys.exit(1)


if __name__ == "__main__":
    main()

