import RPi.GPIO as GPIO
import time
import logging
import sys

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

SERVO_PIN = 18
PWM_FREQUENCY = 50
MIN_DUTY = 2.5
MAX_DUTY = 12.5
MIN_ANGLE = 0
MAX_ANGLE = 180


class ServoController:
    """Reusable controller for a hobby servo on a Raspberry Pi GPIO pin."""

    def __init__(self, control_pin, frequency=50):
        self.control_pin = control_pin
        self.frequency = frequency
        self.pwm_channel = None
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.control_pin, GPIO.OUT)
            self.pwm_channel = GPIO.PWM(self.control_pin, self.frequency)
            self.pwm_channel.start(0)
            logging.info("Servo controller initialized on GPIO %d at %d Hz", control_pin, frequency)
        except Exception as e:
            logging.error("Failed to initialize servo controller: %s", e)
            raise

    def _angle_to_duty_cycle(self, angle):
        """Map a servo angle in degrees to a PWM duty cycle percentage."""
        if not (MIN_ANGLE <= angle <= MAX_ANGLE):
            raise ValueError(f"Angle {angle} out of range [{MIN_ANGLE}, {MAX_ANGLE}]")
        return MIN_DUTY + (angle / 18.0)

    def move_to(self, angle):
        """Move the servo to the requested angle and hold briefly for observation."""
        if self.pwm_channel is None:
            raise RuntimeError("Servo controller not initialized")
        duty_cycle = self._angle_to_duty_cycle(angle)
        self.pwm_channel.ChangeDutyCycle(duty_cycle)
        logging.info("Servo moved to %d degrees (duty %.1f%%)", angle, duty_cycle)
        time.sleep(0.5)

    def stop(self):
        """Stop the PWM signal and release the GPIO pin."""
        if self.pwm_channel is not None:
            try:
                self.pwm_channel.stop()
            except Exception as e:
                logging.warning("Error stopping PWM: %s", e)
        try:
            GPIO.cleanup(self.control_pin)
        except Exception as e:
            logging.warning("Error cleaning up GPIO pin %d: %s", self.control_pin, e)
        logging.info("Servo controller stopped and GPIO released")


def run_demo(servo_controller, angle_list):
    """Sweep the servo through a list of angles for the class demonstration."""
    for target_angle in angle_list:
        servo_controller.move_to(target_angle)


def main():
    """Main entry point: initialize servo, run demo, ensure cleanup on exit."""
    servo_controller = None
    try:
        servo_controller = ServoController(SERVO_PIN, PWM_FREQUENCY)
        demo_angles = [0, 45, 90, 135, 180, 135, 90, 45, 0]
        run_demo(servo_controller, demo_angles)
    except KeyboardInterrupt:
        logging.info("Demo interrupted by user")
    except Exception as e:
        logging.error("Unexpected error: %s", e)
    finally:
        if servo_controller is not None:
            servo_controller.stop()
        else:
            try:
                GPIO.cleanup()
            except Exception:
                pass


if __name__ == "__main__":
    main()

