import serial
import time
import logging
import signal
import sys
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class GSMModule:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=2, power_pin=4):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.power_pin = power_pin
        self._serial = None
        self._gpio_initialized = False
        self._original_handlers = {}

        try:
            self._serial = serial.Serial(
                port=port,
                baudrate=baudrate,
                timeout=timeout,
                write_timeout=timeout
            )
            logger.info(f"Serial port {port} opened at {baudrate} baud.")
        except serial.SerialException as e:
            logger.error(f"Failed to open serial port {port}: {e}")
            raise

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.power_pin, GPIO.OUT, initial=GPIO.LOW)
            self._gpio_initialized = True
            logger.info(f"Power pin GPIO{self.power_pin} configured as output.")
        except Exception as e:
            logger.error(f"Failed to initialize GPIO: {e}")
            self.close()
            raise

        self._install_signal_handlers()

        try:
            self._power_on_module()
            self._verify_module()
        except Exception as e:
            logger.error(f"Module initialization failed: {e}")
            self.close()
            raise

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            self._original_handlers[sig] = signal.getsignal(sig)
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum, frame):
        logger.info(f"Signal {signum} received; shutting down GSMModule.")
        self.close()
        handler = self._original_handlers.get(signum)
        if callable(handler) and handler not in (signal.SIG_DFL, signal.SIG_IGN):
            signal.signal(signum, handler)
            handler(signum, frame)
        else:
            sys.exit(0)

    def _power_on_module(self):
        logger.info("Powering on GSM module...")
        GPIO.output(self.power_pin, GPIO.HIGH)
        time.sleep(2)
        GPIO.output(self.power_pin, GPIO.LOW)
        time.sleep(3)
        logger.info("GSM module powered on.")

    def _verify_module(self):
        logger.info("Verifying module responsiveness...")
        response = self._send_at_command(b'AT')
        if response is None or b'OK' not in response:
            raise RuntimeError("Module did not respond with OK to AT command.")
        logger.info("Module verified.")

    def _send_at_command(self, command, attempts=5):
        if not self._serial or not self._serial.is_open:
            logger.error("Serial port is not open.")
            return None

        for attempt in range(attempts):
            try:
                self._serial.reset_input_buffer()
                self._serial.write(command)
                self._serial.flush()
                response = self.read_response()
                if response is not None:
                    logger.debug(f"CMD: {command!r} -> {response!r}")
                    return response
                logger.warning(f"Attempt {attempt + 1}/{attempts}: no response for {command!r}")
            except serial.SerialException as e:
                logger.error(f"Serial error on attempt {attempt + 1}/{attempts} for {command!r}: {e}")
            time.sleep(0.5)
        logger.error(f"Failed to get valid response for {command!r} after {attempts} attempts.")
        return None

    def read_response(self, attempts=5):
        if not self._serial or not self._serial.is_open:
            return None
        response = b''
        for attempt in range(attempts):
            try:
                partial = self._serial.read(self._serial.in_waiting or 1024)
                if partial:
                    response += partial
                    if b'OK' in response or b'ERROR' in response:
                        break
            except serial.SerialException as e:
                logger.error(f"Serial read error: {e}")
                return None
            time.sleep(0.1)
        return response.decode('utf-8', errors='ignore') if response else None

    def set_gps_reporting(self, interval_seconds=10):
        command = f'AT+GPSRD={interval_seconds}\r\n'.encode('utf-8')
        response = self._send_at_command(command)
        if response is None or b'OK' not in response:
            raise RuntimeError(f"Failed to set GPS reporting interval to {interval_seconds}s.")
        logger.info(f"GPS reporting set to {interval_seconds} seconds.")

    def send_tcp_data(self, data, ip='192.168.100.12', port=50):
        start_cmd = f'AT+CIPSTART="TCP","{ip}",{port}\r\n'.encode('utf-8')
        response = self._send_at_command(start_cmd)
        if response is None or b'OK' not in response:
            raise RuntimeError("Failed to start TCP connection.")

        send_cmd = f'AT+CIPSEND\r\n'.encode('utf-8')
        response = self._send_at_command(send_cmd)
        if response is None or b'> ' not in response:
            self._send_at_command(b'AT+CIPCLOSE\r\n')
            raise RuntimeError("Failed to initiate CIPSEND.")

        try:
            self._serial.write(data.encode('utf-8'))
            self._serial.flush()
            self.send_terminator()
        except serial.SerialException as e:
            logger.error(f"Failed to send data: {e}")
            self._send_at_command(b'AT+CIPCLOSE\r\n')
            raise

        close_cmd = b'AT+CIPCLOSE\r\n'
        response = self._send_at_command(close_cmd)
        if response is None or b'OK' not in response:
            raise RuntimeError("Failed to close TCP connection.")
        logger.info("TCP data sent and connection closed.")

    def send_terminator(self):
        try:
            self._serial.write(b'\x1A')
            self._serial.flush()
            response = self.read_response()
            if response is None:
                logger.warning("No response to terminator.")
            else:
                logger.debug(f"Terminator response: {response!r}")
        except serial.SerialException as e:
            logger.error(f"Failed to send terminator: {e}")

    def set_message_storage(self, storage='SM'):
        command = f'AT+CPMS="{storage}","{storage}","{storage}"\r\n'.encode('utf-8')
        response = self._send_at_command(command)
        if response is None or b'OK' not in response:
            raise RuntimeError(f"Failed to set message storage to {storage}.")
