# Constants for servo channels
BASE_SERVO = 0
DROP_SERVO = 1
SEEK_SERVO = 2
GRAB_SERVO = 4

# Constants for servo angles
ANGLE_DROP_METAL = 135
ANGLE_DROP_PAPER = 90
ANGLE_DROP_PLASTIC = 180
ANGLE_SEEK = 160
ANGLE_DROP = 100
ANGLE_GRAB = 90
ANGLE_BASE_CENTER = 90

# Global flag for graceful shutdown
_running = True

def signal_handler(sig, frame):
    global _running
    _running = False

def initialize_servo_kit():
    """Initializes the ServoKit object with robust error handling."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        kit = ServoKit(channels=16, i2c=i2c)
        return kit
    except Exception as e:
        print(f"Error initializing ServoKit: {e}", file=sys.stderr)
        return None

def move_servo(kit, servo_channel, target_angle, step_size=5, delay=0.04):
    """Moves a servo smoothly to a target angle with error handling."""
    if not kit:
        print("ServoKit not initialized.", file=sys.stderr)
        return False
    if not (0 <= servo_channel <= 15):
        print(f"Invalid servo channel: {servo_channel}", file=sys.stderr)
        return False
    if not (0 <= target_angle <= 180):
        print(f"Invalid target angle: {target_angle}", file=sys.stderr)
        return False
    try:
        current_angle = kit.servo[servo_channel].angle
        if current_angle is None:
            current_angle = 0
        current_angle = int(current_angle)
        if current_angle < target_angle:
            angle_range = range(current_angle, target_angle, step_size)
        else:
            angle_range = range(current_angle, target_angle, -step_size)
        for angle in angle_range:
            if not _running:
                return False
            kit.servo[servo_channel].angle = angle
            time.sleep(delay)
        kit.servo[servo_channel].angle = target_angle
        return True
    except Exception as e:
        print(f"Error moving servo {servo_channel}: {e}", file=sys.stderr)
        return False

def seek(angle):
    return move_servo(kit, SEEK_SERVO, angle)

def deseek(angle):
    return move_servo(kit, SEEK_SERVO, ANGLE_SEEK)

def drop(angle):
    return move_servo(kit, DROP_SERVO, angle)

def pick(angle):
    return move_servo(kit, DROP_SERVO, ANGLE_DROP)

def grab(angle):
    return move_servo(kit, GRAB_SERVO, angle)

def release(angle):
    return move_servo(kit, GRAB_SERVO, angle)

def collect_object_steps(seek_angle):
    """Performs the steps to collect an object."""
    seek(seek_angle)
    grab(ANGLE_GRAB)
    drop(ANGLE_DROP)
    pick(ANGLE_DROP)
    deseek(ANGLE_SEEK)

def drop_object_steps(drop_angle):
    """Performs the steps to drop an object."""
    move_servo(kit, DROP_SERVO, drop_angle, step_size=2, delay=0.01)
    release(120)
    move_servo(kit, DROP_SERVO, ANGLE_DROP)

def get_pos_x(x_center):
    """Calculates the x-position based on the center x-coordinate."""
    if x_center < 160:
        pos_x = 90
    elif x_center < 320:
        pos_x = 67
    else:
        pos_x = 45
    return pos_x

def get_pos_y(y_center):
    """Calculates the y-position based on the center y-coordinate."""
    if y_center < 160:
        pos_y = 22
    elif y_center < 320:
        pos_y = 0
    else:
        pos_y = -22
    return pos_y

def collect_object(x_center, y_center, drop_angle):
    """Collects an object at the specified coordinates and drops it."""
    pos_x = get_pos_x(x_center)
    pos_y = get_pos_y(y_center)
    move_servo(kit, BASE_SERVO, pos_x)
    seek(pos_y)
    collect_object_steps(pos_y)
    drop_object_steps(drop_angle)
    move_servo(kit, SEEK_SERVO, ANGLE_SEEK)
    move_servo(kit, DROP_SERVO, ANGLE_DROP)
    move_servo(kit, GRAB_SERVO, ANGLE_GRAB)
    move_servo(kit, BASE_SERVO, ANGLE_BASE_CENTER)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    kit = initialize_servo_kit()
    if kit is None:
        sys.exit(1)
    try:
        # Example usage
        collect_object(160, 160, ANGLE_DROP_PAPER)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        # Clean up: release all servos and deinitialize I2C
        if kit:
            for ch in range(16):
                try:
                    kit.servo[ch].angle = None
                except Exception:
                    pass
            print("Servos released. Exiting.")

