import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except Exception:
    ServoKit = None

# Constants for servo control
SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
SERVO_COUNT = 16
MIN_ANGLE = 0
MAX_ANGLE = 180
STEP_DEGREES = 5
STEP_DELAY = 0.04

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_servokit(i2c_bus=1, address=0x40):
    """Initializes the ServoKit object.

    Returns the ServoKit instance on success, or None on failure.
    """
    if ServoKit is None:
        print("Error: adafruit_servokit library is not available.")
        return None
    try:
        return ServoKit(channels=SERVO_COUNT, i2c=None, address=address)
    except (OSError, ValueError) as e:
        print(f"Error initializing ServoKit: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        return None


def move_servo(kit, servo_num, target_angle):
    """Moves a servo to a target angle in 5-degree steps.

    Args:
        kit: The ServoKit object.
        servo_num: The servo channel number (0-15).
        target_angle: The target angle in degrees (0-180).

    Returns:
        True if the movement completed successfully, False otherwise.
    """
    if not _running:
        return False

    if not (MIN_ANGLE <= target_angle <= MAX_ANGLE):
        print(f"Error: Target angle {target_angle} is out of range ({MIN_ANGLE}-{MAX_ANGLE}).")
        return False

    if not (0 <= servo_num < SERVO_COUNT):
        print(f"Error: Servo number {servo_num} is out of range (0-{SERVO_COUNT - 1}).")
        return False

    try:
        current_angle = kit.servo[servo_num].angle
        if current_angle is None:
            current_angle = MIN_ANGLE

        step = STEP_DEGREES if target_angle > current_angle else -STEP_DEGREES

        angle = current_angle
        while _running:
            angle += step
            if (step > 0 and angle > target_angle) or (step < 0 and angle < target_angle):
                angle = target_angle

            if not (MIN_ANGLE <= angle <= MAX_ANGLE):
                print(f"Error: Calculated angle {angle} is out of range.")
                return False

            kit.servo[servo_num].angle = angle
            time.sleep(STEP_DELAY)

            if angle == target_angle:
                break

        return True

    except (OSError, ValueError) as e:
        print(f"Error moving servo {servo_num}: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error moving servo {servo_num}: {e}")
        return False


def grab_object(kit, servo_num=SERVO_CHANNEL):
    """Closes the gripper to grab an object."""
    return move_servo(kit, servo_num, GRAB_ANGLE)


def release_object(kit, servo_num=SERVO_CHANNEL):
    """Opens the gripper to release an object."""
    return move_servo(kit, servo_num, RELEASE_ANGLE)


def main():
    """Main function to demonstrate servo control."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servokit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        print("Grabbing object...")
        grab_object(kit)
        time.sleep(1)

        if not _running:
            return

        print("Releasing object...")
