import logging
import signal
import sys
from gpiozero import OutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PUMP_PIN = 20
LIGHT_PIN = 21

# Global list of actuator devices so signal handler can safely close them.
_actuators = []


def init_actuators():
    """Initialize gpiozero OutputDevice objects for the pump and grow light."""
    global _actuators
    try:
        pump = OutputDevice(PUMP_PIN)
        light = OutputDevice(LIGHT_PIN)
        _actuators = [pump, light]
        logging.info("Actuators initialized: pump=BCM%d, light=BCM%d", PUMP_PIN, LIGHT_PIN)
    except Exception as e:
        logging.error("Failed to initialize actuators: %s", e)
        raise


def parse_intent(phrase):
    """Return the recognized intent name for a plain-English hydroponics phrase."""
    lowered = phrase.lower()
    if "pump" in lowered and "on" in lowered:
        return "pump_on"
    if "pump" in lowered and "off" in lowered:
        return "pump_off"
    if "light" in lowered and ("on" in lowered or "off" in lowered or "switch" in lowered):
        return "light_toggle"
    return None


def apply_intent(intent, pump, light):
    """Drive the actuators based on the parsed intent."""
    if intent == "pump_on":
        pump.on()
        logging.info("Pump ON")
    elif intent == "pump_off":
        pump.off()
        logging.info("Pump OFF")
    elif intent == "light_toggle":
        light.toggle()
        logging.info("Light toggled (now %s)", "ON" if light.is_active else "OFF")
    else:
        logging.warning("Unknown intent: %s", intent)


def cleanup(signum=None, frame=None):
    """Close all actuator devices so they are left in a safe (off) state."""
    for dev in _actuators:
        try:
            dev.close()
        except Exception as e:
            logging.error("Error closing actuator: %s", e)
    _actuators.clear()
    if signum is not None:
        logging.info("Received signal %d, exiting.", signum)
        sys.exit(0)


def main():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        init_actuators()
    except Exception:
        sys.exit(1)

    test_phrases = ["turn the pump on", "switch the light", "turn pump off", "unknown command"]
    pump = _actuators[0]
    light = _actuators[1]

    for phrase in test_phrases:
        intent = parse_intent(phrase)
        logging.info("Phrase: '%s' -> intent: %s", phrase, intent)
        if intent:
            apply_intent(intent, pump, light)
        else:
            logging.warning("No intent matched for phrase: %s", phrase)

    cleanup()


if __name__ == "__main__":
    main()

