import RPi.GPIO as GPIO
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

SOLENOID_RELAY_PIN = 24

class SolenoidFlusher:
    def __init__(self, relay_pin):
        self.relay_pin = relay_pin
        self.pulse_count = 0
        self._initialized = False
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.relay_pin, GPIO.OUT, initial=GPIO.LOW)
            self._initialized = True
            logging.info("Solenoid flusher initialized on GPIO %d", self.relay_pin)
        except Exception as e:
            logging.error("Failed to initialize GPIO: %s", e)
            raise

    def pulse_solenoid(self, duration_seconds):
        if not self._initialized:
            logging.error("Solenoid not initialized, cannot pulse")
            return
        try:
            if GPIO.input(self.relay_pin) == GPIO.HIGH:
                logging.warning("Solenoid already active, skipping pulse")
                return
            GPIO.output(self.relay_pin, GPIO.HIGH)
            time.sleep(duration_seconds)
            GPIO.output(self.relay_pin, GPIO.LOW)
            self.pulse_count += 1
            logging.info("Solenoid pulse #%d completed", self.pulse_count)
        except Exception as e:
            logging.error("Error during solenoid pulse: %s", e)
            self._safe_deenergize()

    def _safe_deenergize(self):
        try:
            GPIO.output(self.relay_pin, GPIO.LOW)
        except Exception:
            pass

    def cleanup(self):
        if self._initialized:
            self._safe_deenergize()
            GPIO.cleanup(self.relay_pin)
            self._initialized = False
            logging.info("Solenoid flusher cleaned up")

def run_flush_plan(flusher, pulse_plan):
    for pulse_index, pulse_seconds in enumerate(pulse_plan):
        logging.info("Executing pulse %d/%d", pulse_index + 1, len(pulse_plan))
        flusher.pulse_solenoid(pulse_seconds)
        if pulse_index < len(pulse_plan) - 1:
            time.sleep(1.0)

def signal_handler(signum, frame):
    logging.info("Received signal %d, shutting down", signum)
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    flusher = None
    try:
        flusher = SolenoidFlusher(SOLENOID_RELAY_PIN)
        flush_plan = [0.4, 0.4, 0.4]
        run_flush_plan(flusher, flush_plan)
    except Exception as e:
        logging.error("Fatal error: %s", e)
    finally:
        if flusher:
            flusher.cleanup()

if __name__ == "__main__":
    main()

