import time
import re
import logging
import paho.mqtt.client as mqtt

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

BROKER_HOST = "localhost"
BROKER_PORT = 1883
REPORT_TOPIC = "city/reports"
RUN_DURATION = 5


def classify_report(report_text):
    """Return a short label for an urban monitoring report."""
    if re.search(r"\bnoise\b", report_text.lower()):
        return "noise"
    if re.search(r"\btraffic\b", report_text.lower()):
        return "traffic"
    return "other"


def handle_message(mqtt_client, userdata, message):
    """Process one MQTT message and update the running tally."""
    report_text = message.payload.decode("utf-8", errors="replace")
    category = classify_report(report_text)
    if "category_counts" in userdata:
        userdata["category_counts"][category] = userdata["category_counts"].get(category, 0) + 1
    else:
        userdata["category_counts"] = {category: 1}
    logging.info("Report classified as %s", category)


def on_connect(mqtt_client, userdata, flags, reason_code, properties):
    """Callback for when the client connects to the broker."""
    if reason_code == 0:
        logging.info("Connected to broker successfully")
        mqtt_client.subscribe(REPORT_TOPIC)
    else:
        logging.error("Connection failed with reason code: %s", reason_code)


def on_disconnect(mqtt_client, userdata, flags, reason_code, properties):
    """Callback for when the client disconnects from the broker."""
    logging.info("Disconnected from broker (reason code: %s)", reason_code)


def run_node():
    """Subscribe to MQTT reports and tally classified categories."""
    mqtt_client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        client_id="urban_monitor_node"
    )
    mqtt_client.on_connect = on_connect
    mqtt_client.on_disconnect = on_disconnect
    mqtt_client.user_data_set({"category_counts": {}})
    mqtt_client.message_callback_add(REPORT_TOPIC, handle_message)

    try:
        mqtt_client.connect(BROKER_HOST, BROKER_PORT, keepalive=60)
    except Exception as e:
        logging.error("Failed to connect to broker: %s", e)
        return

    mqtt_client.loop_start()
    try:
        end_time = time.time() + RUN_DURATION
        while time.time() < end_time:
            time.sleep(0.5)
    except KeyboardInterrupt:
        logging.info("Node stopped by user")
    finally:
        mqtt_client.loop_stop()
        mqtt_client.disconnect()
        logging.info("Final category counts: %s", mqtt_client.user_data_get("category_counts"))


if __name__ == "__main__":
    run_node()

