import smbus2
import time
import signal
import sys

# CCS811 I2C address and registers
CCS811_ADDR = 0x5A
CCS811_APP_START = 0xF4
CCS811_ALG_RESULT_DATA = 0x02

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def init_sensor(bus):
    """Initialize the CCS811 sensor by writing 0x20 to the APP_START register."""
    try:
        bus.write_byte_data(CCS811_ADDR, CCS811_APP_START, 0x20)
        return True
    except OSError as e:
        print(f"Error initializing sensor: {e}")
        return False

def read_co2(bus):
    """Read 2-byte CO2 data from the sensor and return as a 16-bit big-endian integer."""
    try:
        data = bus.read_i2c_block_data(CCS811_ADDR, CCS811_ALG_RESULT_DATA, 2)
        return (data[0] << 8) | data[1]
    except OSError as e:
        print(f"Error reading CO2 data: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(1)
    except OSError as e:
        print(f"Error opening I2C bus 1: {e}")
        sys.exit(1)

    # Verify sensor presence before attempting initialization
    try:
        bus.read_byte(CCS811_ADDR)
    except OSError:
        print(f"Error: CCS811 sensor not found at address 0x{CCS811_ADDR:02X} on I2C bus 1.")
        bus.close()
        sys.exit(1)

    if not init_sensor(bus):
        bus.close()
        sys.exit(1)

    print("CCS811 initialized. Starting CO2 readings...")

    try:
        for i in range(5):
            if not running:
                break
            co2_level = read_co2(bus)
            if co2_level is not None:
                print(f"CO2 Concentration: {co2_level} ppm")
            else:
                print("Failed to read CO2 data.")
            if i < 4:
                time.sleep(2)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if bus:
            bus.close()
            print("I2C bus closed.")

if __name__ == "__main__":
    main()

