import signal
import sys
import threading
import time
import board
import busio
import digitalio
import adafruit_24lc32

# Global resources for cleanup
spi_bus = None
chip_select = None
eeprom = None
shutdown_event = threading.Event()

# Lock to prevent concurrent access to the EEPROM
eeprom_lock = threading.Lock()


def cleanup(signum=None, frame=None):
    """Clean up resources on exit or signal."""
    global spi_bus, chip_select, eeprom
    if shutdown_event.is_set():
        return
    shutdown_event.set()
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting...")
    try:
        if eeprom is not None:
            try:
                eeprom.deinit()
            except Exception:
                pass
    except Exception as e:
        print(f"Error deinitializing EEPROM: {e}")
    try:
        if chip_select is not None:
            chip_select.deinit()
    except Exception as e:
        print(f"Error deinitializing CS pin: {e}")
    try:
        if spi_bus is not None:
            spi_bus.deinit()
    except Exception as e:
        print(f"Error deinitializing SPI bus: {e}")
    if signum is not None:
        sys.exit(0)


def write_eeprom(data, address=0):
    """Thread-safe write to the EEPROM."""
    with eeprom_lock:
        if shutdown_event.is_set():
            return
        try:
            eeprom.write(address, data)
            print(f"Data {data} written to address {address}")
        except Exception as e:
            print(f"Error writing to EEPROM: {e}")


def read_eeprom(address=0, length=16):
    """Thread-safe read from the EEPROM."""
    with eeprom_lock:
        if shutdown_event.is_set():
            return
        try:
            data = eeprom.read(address, length)
            print(f"Data {data} read from address {address}")
        except Exception as e:
            print(f"Error reading from EEPROM: {e}")


def main():
    global spi_bus, chip_select, eeprom

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    # Initialize SPI bus
    try:
        spi_bus = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
    except Exception as e:
        print(f"Failed to initialize SPI bus: {e}")
        sys.exit(1)

    # Initialize chip select pin
    try:
        chip_select = digitalio.DigitalInOut(board.D5)
        chip_select.direction = digitalio.Direction.OUTPUT
        chip_select.value = True  # Active-low; idle high
