def cleanup(signum=None, frame=None):
    """Clean up resources on exit or signal."""
    global spi_bus, chip_select, eeprom
    if shutdown_event.is_set():
        return
    shutdown_event.set()
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting...")
    try:
        if eeprom is not None:
            try:
                eeprom.deinit()
            except Exception:
                pass
    except Exception as e:
        print(f"Error deinitializing EEPROM: {e}")
    try:
