            chip_select.deinit()
    except Exception as e:
        print(f"Error deinitializing CS pin: {e}")
    try:
        if spi_bus is not None:
            spi_bus.deinit()
    except Exception as e:
        print(f"Error deinitializing SPI bus: {e}")
    if signum is not None:
        sys.exit(0)


