import signal
import sys
import time

import serial
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0
READ_TIMEOUT = 1.0
LOOP_DELAY = 1.0

running = True
serial_connection = None
alarm = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global serial_connection, alarm
    if alarm is not None:
        try:
            alarm.off()
            alarm.close()
        except Exception:
            pass
        alarm = None
    if serial_connection is not None:
        try:
            serial_connection.close()
        except Exception:
            pass
        serial_connection = None


def main():
    global serial_connection, alarm

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        alarm = OutputDevice(ALARM_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        print(f"Error initializing GPIO {ALARM_PIN}: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    alarm_active = False

    try:
        while running:
            try:
                raw = serial_connection.readline()
            except serial.SerialException as exc:
                print(f"Serial I/O error: {exc}", file=sys.stderr)
                time.sleep(LOOP_DELAY)
                continue

            if not raw:
                continue

            try:
                line = raw.decode('ascii', errors='replace').strip()
            except Exception as exc:
                print(f"Decode error: {exc}", file=sys.stderr)
                time.sleep(LOOP_DELAY)
                continue

            if not line:
                continue

            try:
                radiation_level = float(line)
            except ValueError:
                print(f"Invalid data (not numeric): {line!r}", file=sys.stderr)
                time.sleep(LOOP_DELAY)
                continue

            print(f"Radiation Level: {radiation_level:.2f} µSv/h")

            if radiation_level > RADIATION_THRESHOLD:
                if not alarm_active:
                    alarm.on()
                    alarm_active = True
                    print("ALARM ACTIVATED: Radiation level exceeds threshold!")
            else:
                if alarm_active:
                    alarm.off()
                    alarm_active = False
                    print("ALARM DEACTIVATED: Radiation level is within safe limits.")

            time.sleep(LOOP_DELAY)

    finally:
        cleanup()


if __name__ == '__main__':
    main()

