ALERT_PIN = 17

running = True
serial_connection = None
alert_pin = None


def signal_handler(signum, frame):
    global running
    running = False


def cleanup():
    global serial_connection, alert_pin
    if serial_connection is not None and serial_connection.is_open:
        try:
            serial_connection.close()
        except Exception:
            pass
    if alert_pin is not None:
        try:
            alert_pin.close()
        except Exception:
            pass


def main():
    global serial_connection, alert_pin

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        alert_pin = OutputDevice(ALERT_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f"Error initializing GPIO pin {ALERT_PIN}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print(f"Monitoring {SERIAL_PORT} @ {BAUD_RATE} baud. Threshold: {FLOW_THRESHOLD} L/min. Ctrl+C to exit.")

    try:
        while running:
            try:
                raw_line = serial_connection.readline()
                if not raw_line:
                    continue

                line = raw_line.decode('ascii', errors='replace').strip()
                if not line:
                    continue

                try:
                    flow_rate = float(line)
                except ValueError:
                    print(f"Invalid data received (not numeric): '{line}'", file=sys.stderr)
                    continue

                print(f"Flow Rate: {flow_rate:.2f} L/min")

                if flow_rate > FLOW_THRESHOLD:
                    alert_pin.on()
                else:
                    alert_pin.off()

            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                break
            except OSError as e:
                print(f"I/O error on serial port: {e}", file=sys.stderr)
                break

            time.sleep(1)

    finally:
        cleanup()
        print("Resources released. Exiting.")


if __name__ == '__main__':
    main()

