#!/usr/bin/env python3
"""Read CO2 concentration from a serial sensor on /dev/ttyUSB0 and log readings.

Sensor protocol: ASCII-encoded integer ppm values, one per line.
"""

import signal
import sys
import time
from datetime import datetime

import serial

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1          # seconds
SAMPLE_INTERVAL = 5  # seconds
LOG_FILE = "co2_readings_log.txt"

_running = True


def _handle_signal(signum, frame):
    """Flag the main loop to exit cleanly on SIGINT / SIGTERM."""
    global _running
    _running = False


def initialize_serial(port: str, baudrate: int, timeout: float) -> serial.Serial:
    """Open and return a serial connection, raising on failure."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        # Flush any stale data in the input buffer.
        ser.reset_input_buffer()
        return ser
    except serial.SerialException as exc:
        raise RuntimeError(
            f"Failed to open serial port {port}: {exc}"
        ) from exc


def read_co2_level(ser: serial.Serial) -> int | None:
    """Read one line from the serial port and convert to an integer ppm.

    Returns None on timeout, empty line, or non-numeric data.
    """
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"[WARN] Serial read error: {exc}", file=sys.stderr)
        return None

    if not raw:
        return None  # timeout — no data received within TIMEOUT seconds

    line = raw.decode("ascii", errors="replace").strip()
    if not line:
        return None

    try:
        return int(line)
    except ValueError:
        print(f"[WARN] Non-numeric data received: {line!r}", file=sys.stderr)
        return None


def log_reading(log_path: str, timestamp: str, co2_level: int) -> None:
    """Append a timestamped CO2 reading to the log file and echo to stdout."""
    entry = f"{timestamp} - CO2: {co2_level} ppm\n"
    try:
        with open(log_path, "a", encoding="utf-8") as fh:
            fh.write(entry)
    except OSError as exc:
        print(f"[ERROR] Failed to write log: {exc}", file=sys.stderr)
        return
    print(entry, end="")


def main() -> int:
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    except RuntimeError as exc:
        print(f"[ERROR] {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            co2 = read_co2_level(ser)
            if co2 is not None:
                timestamp = datetime.now().isoformat(timespec="seconds")
                log_reading(LOG_FILE, timestamp, co2)
            # Sleep in small increments so signals are caught promptly.
            slept = 0.0
            while _running and slept < SAMPLE_INTERVAL:
                time.sleep(0.1)
                slept += 0.1
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("\n[INFO] Serial port closed. Exiting.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

