import serial
import time
import signal
import sys

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
TIMEOUT = 1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def decode_coordinate(raw_value, is_longitude):
    if not raw_value:
        return None
    try:
        dot = raw_value.find('.')
        if dot == -1:
            return None
        degrees_minutes = raw_value[:dot]
        decimal_minutes = raw_value[dot + 1:]
        if len(degrees_minutes) < 3:
            return None
        degrees = float(degrees_minutes[:-2])
        minutes = float(degrees_minutes[-2:] + '.' + decimal_minutes)
        value = degrees + minutes / 60.0
        if is_longitude:
            if raw_value[0] == 'W':
                value = -value
        else:
            if raw_value[0] == 'S':
                value = -value
        return value
    except (ValueError, IndexError):
        return None

def parse_gprmc(data):
    if not data.startswith("$GPRMC"):
        return None, None
    parts = data.split(",")
    if len(parts) < 8:
        return None, None
    if parts[2] != "A":
        return None, None
    lat = decode_coordinate(parts[3], is_longitude=False)
    lon = decode_coordinate(parts[5], is_longitude=True)
    return lat, lon

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, baudrate=BAUD_RATE, timeout=TIMEOUT)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud. Reading GPS data...")
        while _running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('utf-8', errors='ignore').strip()
                if not line:
                    continue
                lat, lon = parse_gprmc(line)
                if lat is not None and lon is not None:
                    print(f"Latitude: {lat:.6f}, Longitude: {lon:.6f}")
                    time.sleep(1)
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                break
            except Exception as e:
                print(f"Unexpected error: {e}")
                break
    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"Fatal error: {e}")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")
        print("Exiting.")

if __name__ == "__main__":
    main()

