import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    num_satellites: Optional[int] = None
    altitude: Optional[float] = None


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_port: Optional[serial.Serial] = None
        self._connected = False

    def connect(self) -> bool:
        if self._connected:
            return True
        try:
            self.serial_port = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            self._connected = True
            logger.info("Connected to GPS on %s at %d baud.", self.port, self.baudrate)
            return True
        except serial.SerialException as e:
            logger.error("Failed to open serial port %s: %s", self.port, e)
            self.serial_port = None
            self._connected = False
            return False
        except Exception as e:
            logger.error("Unexpected error opening %s: %s", self.port, e)
            self.serial_port = None
            self._connected = False
            return False

    def disconnect(self) -> None:
        if not self._connected and self.serial_port is None:
            return
        try:
            if self.serial_port is not None and self.serial_port.is_open:
                self.serial_port.close()
                logger.info("Serial port %s closed.", self.port)
        except Exception as e:
            logger.error("Error closing serial port %s: %s", self.port, e)
        finally:
            self._connected = False
            self.serial_port = None

    @staticmethod
    def _verify_checksum(sentence: str) -> bool:
        if "*" not in sentence:
            return False
        body, _, csum_str = sentence.rpartition("*")
        if not body or not csum_str:
            return False
        try:
            expected = int(csum_str.strip()[:2], 16)
        except ValueError:
            return False
        computed = 0
        for ch in body:
            computed ^= ord(ch)
        return computed == expected

    @staticmethod
    def _nmea_to_decimal(value: str, direction: str) -> Optional[float]:
        if not value or not direction:
            return None
        try:
            dot = value.index(".")
            deg_len = dot - 2
            if deg_len <= 0:
                return None
            degrees = float(value[:deg_len])
            minutes = float(value[deg_len:])
            decimal = degrees + minutes / 60.0
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, IndexError):
            return None

    def read_gps_data(self) -> Optional[GPS_readings]:
        if not self._connected or self.serial_port is None:
            return None
        try:
            raw = self.serial_port.readline()
        except serial.SerialException as e:
            logger.error("Serial read error: %s", e)
            return None
        except Exception as e:
            logger.error("Unexpected read error: %s", e)
            return None

        if not raw:
            return None

        try:
            line = raw.decode("ascii", errors="replace").strip()
        except Exception as e:
            logger.error("Decode error: %s", e)
            return None

        if not line.startswith("$GPGGA"):
            return None

        if not self._verify_checksum(line):
            logger.warning("Checksum failed: %s", line)
            return None

        fields = line.split(",")
        if len(fields) < 15:
            logger.warning("Incomplete GPGGA: %s", line)
            return None

        try:
            talker = fields[0][1:3]
        except IndexError:
            logger.warning("Malformed talker field: %s", line)
            return None

        if talker != "GP":
            return None

        try:
            fix_quality = int(fields[6])
        except ValueError:
            logger.warning("Invalid fix quality: %s", line)
            return None

        if fix_quality == 0:
            logger.warning("No GPS fix: %s", line)
            return None

        readings = GPS_readings()

        readings.latitude = self._nmea_to_decimal(fields[2], fields[3])
        if readings.latitude is None:
            logger.warning("Invalid latitude: %s", line)

        readings.longitude = self._nmea_to_decimal(fields[4], fields[5])
        if readings.longitude is None:
            logger.warning("Invalid longitude: %s", line)

        try:
            readings.num_satellites = int(fields[7])
        except ValueError:
            logger.warning("Invalid satellite count: %s", line)

        try:
            readings.altitude = float(fields[9])
        except ValueError:
            logger.warning("Invalid altitude: %s", line)

        return readings


def main():
    reader = GPSReader(port="/dev/serial0", baudrate=9600)

    def _signal_handler(signum, frame):
        logger.info("Signal %d received, shutting down.", signum)
        reader.disconnect()
        sys.exit(0)

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not reader.connect():
        logger.error("Could not connect to GPS. Exiting.")
        sys.exit(1)

    try:
        while True:
            data = reader.read_gps_data()
            if data is not None:
                logger.info(
                    "Lat: %s, Lon: %s, Sats: %s, Alt: %s",
                    data.latitude,
                    data.longitude,
                    data.num_satellites,
                    data.altitude,
                )
    except Exception as e:
        logger.error("Fatal error in main loop: %s", e)
    finally:
        reader.disconnect()


if __name__ == "__main__":
    main()

