    def __init__(self, port='/dev/serial0', baudrate=9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_connection = None
        self._running = True

    def connect(self):
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1
            )
            logging.info(f"Connected to GPS on {self.port} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Serial error connecting to GPS: {e}")
            return False
        except OSError as e:
            logging.error(f"OS error connecting to GPS: {e}")
            return False

    def read_data(self):
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.error("Serial connection is not open.")
            return None
        try:
            if self.serial_connection.in_waiting > 0:
                data = self.serial_connection.readline().decode('utf-8', errors='ignore').strip()
                return data if data else None
            return None
        except serial.SerialException as e:
            logging.error(f"Serial error reading data: {e}")
            return None
        except OSError as e:
            logging.error(f"OS error reading data: {e}")
            return None

    def parse_gga(self, nmea_data):
        if not nmea_data:
            return None
        if not (nmea_data.startswith('$GPGGA') or nmea_data.startswith('$GNGGA')):
            return None
        try:
            parts = nmea_data.split(',')
            if len(parts) < 15:
                return None
            utc_time = parts[1] if parts[1] else None
            latitude = self._convert_to_decimal(parts[2], parts[3]) if parts[2] and parts[3] else None
            longitude = self._convert_to_decimal(parts[4], parts[5]) if parts[4] and parts[5] else None
            fix_quality = parts[6] if parts[6] else None
            num_satellites = parts[7] if parts[7] else None
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GGA data: {e}")
            return None

    def _convert_to_decimal(self, coordinate, direction):
        if not coordinate or not direction:
            return None
        try:
            degrees = float(coordinate[:2])
            minutes = float(coordinate[2:])
            decimal = degrees + (minutes / 60.0)
            if direction in ('S', 'W'):
                decimal = -decimal
            return decimal
        except (IndexError, ValueError) as e:
            logging.error(f"Error converting coordinate: {e}")
            return None

    def close(self):
        if self.serial_connection and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
                logging.info("Serial connection closed.")
            except serial.SerialException as e:
                logging.error(f"Error closing serial connection: {e}")
            except OSError as e:
                logging.error(f"OS error closing serial connection: {e}")
        self.serial_connection = None

    def stop(self):
        self._running = False

def main():
    gps = SimpleGPS()
    if not gps.connect():
        sys.exit(1)
    def signal_handler(sig, frame):
        gps.stop()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        while gps._running:
            data = gps.read_data()
            if data:
                parsed = gps.parse_gga(data)
                if parsed:
                    logging.info(f"Parsed GPS data: {parsed}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        gps.close()

if __name__ == '__main__':
    main()

