from flask import Flask, Response, request, jsonify
import serial
import serial.tools.list_ports
import time
import threading

app = Flask(__name__)

# In-memory data store
data_store = [
    {'id': 1, 'name': 'Task 1', 'done': False},
    {'id': 2, 'name': 'Task 2', 'done': True},
]

# Lock for thread-safe access to the data store
data_lock = threading.Lock()

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1.0


def get_serial_response(command: str) -> str:
    """Open the serial port, send a command, read the response, and close the port.

    Returns the stripped response string.  On any error (port open, write,
    read, or timeout) returns None.
    """
    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
        if not ser.is_open:
            return None

        ser.write(command.encode('ascii'))
        time.sleep(0.1)  # Allow time for the instrument to respond

        # Read all available bytes; read() returns b'' on timeout
        raw = ser.read(4096)
        if not raw:
            return None

        return raw.decode('ascii', errors='replace').strip()

    except serial.SerialException as exc:
        print(f"Serial error: {exc}")
        return None
    except OSError as exc:
        print(f"OS error accessing serial port: {exc}")
        return None
    finally:
        if ser is not None:
            try:
                if ser.is_open:
                    ser.close()
            except Exception:
                pass


@app.route('/version', methods=['GET'])
def version():
    """Query the connected instrument for its identification string."""
    response = get_serial_response('*IDN?\n')
    if response is None:
        return Response(
            "Error: could not communicate with serial device on /dev/ttyUSB0",
            status=503,
            mimetype='text/html',
        )
    html = response.replace('\n', '<br>\n')
    return Response(html, mimetype='text/html')


@app.route('/getdata', methods=['GET'])
def get_data():
    """Return the entire data store as JSON."""
    with data_lock:
        return jsonify(data_store)


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set_item(item_id):
    """Return a single item by id, or 404 if not found."""
    with data_lock:
        item = next((it for it in data_store if it['id'] == item_id), None)
    if item is None:
        return Response('Item not found', status=404, mimetype='text/html')
    return jsonify(item)


@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def add_item(item_id, name):
    """Append a new item with the given id and name; done defaults to False."""
    new_item = {'id': item_id, 'name': name, 'done': False}
    with data_lock:
        data_store.append(new_item)
    return jsonify(data_store)


@app.route('/postjson', methods=['POST', 'GET'])
def post_json():
    """Create a new item with an auto-incremented id.

    Accepts application/json or form-encoded content.
    """
    with data_lock:
        new_id = (data_store[-1]['id'] + 1) if data_store else 1
        new_item = {'id': new_id, 'name': '', 'done': False}

        if request.method == 'POST':
            if request.content_type == 'application/json':
                try:
                    payload = request.get_json(silent=True)
                    if payload is None:
                        return Response(
                            'Invalid or missing JSON body',
                            status=400,
                            mimetype='text/html',
                        )
                    new_item['name'] = payload.get('name', '')
                    done_val = payload.get('done')
                    if isinstance(done_val, bool):
                        new_item['done'] = done_val
                    elif isinstance(done_val, str):
                        if done_val.lower() in ('true', '1'):
                            new_item['done'] = True
                        elif done_val.lower() in ('false', '0'):
                            new_item['done'] = False
                except (ValueError, TypeError) as exc:
                    print(f"JSON parse error: {exc}")
                    return Response(
                        'Invalid JSON body',
                        status=400,
                        mimetype='text/html',
                    )
            else:
                new_item['name'] = request.form.get('name', '')
                done_val = request.form.get('done', '')
                if done_val.lower() in ('true', '1'):
                    new_item['done'] = True
                elif done_val.lower() in ('false', '0'):
                    new_item['done'] = False

            data_store.append(new_item)

        return jsonify(data_store)


if __name__ == '__main__':
    app.run(debug=False, host='0.0.0.0')

