import serial
import time
import sys

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUD_RATE = 38400
COMMAND_PREFIX = "X"
TRANSMISSION_DELAY = 0.1


def create_bluetooth_serial(device, baudrate):
    """Establishes a serial connection to the specified Bluetooth device."""
    try:
        bluetooth_serial = serial.Serial(
            port=device,
            baudrate=baudrate,
            timeout=1,
            write_timeout=5
        )
        if not bluetooth_serial.is_open:
            raise RuntimeError(f"Failed to open serial port {device}")
        return bluetooth_serial
    except serial.SerialException as e:
        raise RuntimeError(f"Error connecting to Bluetooth device: {e}")


def send_command(bluetooth_serial, command):
    """Sends a command over the Bluetooth serial connection."""
    try:
        full_command = f"{COMMAND_PREFIX}{command}\n"
        bytes_written = bluetooth_serial.write(full_command.encode("utf-8"))
        if bytes_written != len(full_command):
            raise RuntimeError(f"Incomplete write: only {bytes_written} of {len(full_command)} bytes sent")
        bluetooth_serial.flush()
        time.sleep(TRANSMISSION_DELAY)
    except serial.SerialException as e:
        raise RuntimeError(f"Error sending command: {e}")


def main():
    """Main function to handle user input and command transmission."""
    bluetooth_serial = None
    try:
        bluetooth_serial = create_bluetooth_serial(BLUETOOTH_DEVICE, BLUETOOTH_BAUD_RATE)
        print(f"Connected to {BLUETOOTH_DEVICE} at {BLUETOOTH_BAUD_RATE} baud. Type 'exit' to quit.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
